@st.cache_resource(show_spinner="Preparing active-country climate workspace…", max_entries=1)
def _load_country_runtime_resource(
    cities_path: str,
    cities_size: int,
    cities_mtime_ns: int,
    climate_path: str,
    climate_size: int,
    climate_mtime_ns: int,
    country: str,
):
    # File size/mtime arguments provide cheap invalidation after Dataset Updater
    # replaces the authoritative CSV. The DataFrames are read-only resources.
    return build_country_runtime(cities_path, climate_path, country)


