# ============================================================
# GENERAL HELPERS
# ============================================================

def get_city_state_order(df_long: pd.DataFrame) -> pd.DataFrame:
    """Return one deterministic row per CITY/STATE pair."""
    return (
        df_long[["CITY", "STATE"]]
        .drop_duplicates()
        .sort_values(["CITY", "STATE"])
        .reset_index(drop=True)
    )


def location_options(df_long: pd.DataFrame) -> pd.DataFrame:
    options = get_city_state_order(df_long).copy()
    options["Location"] = options["CITY"] + " (" + options["STATE"] + ")"
    return options


def safe_float(value) -> float:
    try:
        return float(value)
    except (TypeError, ValueError):
        return np.nan


def format_number(value, digits: int = 3) -> str:
    return "NA" if pd.isna(value) else f"{float(value):.{digits}f}"


def _interpolate_hex(low_hex: str, high_hex: str, value: float) -> str:
    """Interpolate between two colours using a 0–1 value."""
    value = float(np.clip(value, 0.0, 1.0))
    low = tuple(int(low_hex[i:i + 2], 16) for i in (1, 3, 5))
    high = tuple(int(high_hex[i:i + 2], 16) for i in (1, 3, 5))
    rgb = tuple(int(round(a + (b - a) * value)) for a, b in zip(low, high))
    return f"#{rgb[0]:02x}{rgb[1]:02x}{rgb[2]:02x}"


def score_to_hex(score: float, reverse: bool = False) -> str:
    """Colour-blind-friendly sequential scale for similarity and suitability."""
    score = float(np.clip(score, 0.0, 1.0))
    if reverse:
        score = 1.0 - score
    return _interpolate_hex("#5AA9E6", "#084C8D", score)


def risk_to_hex(score: float) -> str:
    """Sequential neutral-to-orange scale for increasing climate risk."""
    return _interpolate_hex("#F6C85F", "#8C1D18", score)


def add_map_legend(
    map_object: folium.Map,
    title: str,
    low_label: str,
    high_label: str,
    low_colour: str,
    high_colour: str
) -> None:
    """Add a compact accessible legend to a Folium map."""
    legend_html = f"""
    <div style="position: fixed; bottom: 28px; left: 28px; z-index: 9999;
                background: white; border: 1px solid #999; border-radius: 6px;
                padding: 10px 12px; font-size: 12px; min-width: 190px;
                box-shadow: 0 1px 5px rgba(0,0,0,0.25);">
      <div style="font-weight: 700; margin-bottom: 6px;">{title}</div>
      <div style="height: 10px; border-radius: 4px;
                  background: linear-gradient(to right, {low_colour}, {high_colour});"></div>
      <div style="display:flex; justify-content:space-between; margin-top:4px;">
        <span>{low_label}</span><span>{high_label}</span>
      </div>
    </div>
    """
    map_object.get_root().html.add_child(folium.Element(legend_html))


def metric_scale(series: pd.Series, lower_is_better: bool = False) -> pd.Series:
    values = pd.to_numeric(series, errors="coerce")
    valid = values.dropna()

    if valid.empty:
        return pd.Series(np.nan, index=series.index)

    low = valid.quantile(0.05)
    high = valid.quantile(0.95)

    if not np.isfinite(low) or not np.isfinite(high) or abs(high - low) < 1e-12:
        scaled = pd.Series(np.nan, index=series.index, dtype=float)
        scaled.loc[values.notna()] = 0.5
    else:
        scaled = ((values - low) / (high - low)).clip(0, 1)

    return 1.0 - scaled if lower_is_better else scaled


def annual_location_variable_table(
    df_long: pd.DataFrame,
    year: int
) -> pd.DataFrame:
    """
    Return annual means joined by CITY and STATE.

    This avoids the old positional-index bug where one independently sorted
    array was attached to a different city list.
    """
    table = (
        df_long[df_long["Year"] == year]
        .groupby(["CITY", "STATE", "Variable"], as_index=False)["Value"]
        .mean()
        .pivot_table(
            index=["CITY", "STATE"],
            columns="Variable",
            values="Value",
            aggfunc="mean"
        )
        .reset_index()
    )

    return (
        get_city_state_order(df_long)
        .merge(table, on=["CITY", "STATE"], how="left")
    )


def get_annual_stats(df_long: pd.DataFrame, year: int) -> tuple[np.ndarray, ...]:
    """
    Backwards-compatible annual-stat tuple aligned to get_city_state_order().
    """
    stat_vars = [
        "EVAPOTRANSPIRATION",
        "PRECIPITATION_AVG",
        "TEMPERATURE",
        "TEMPERATURE_MAX",
        "TEMPERATURE_MIN",
        "WIND_SPEED",
        "CLEARNESS_INDEX",
        "SOLAR_RADIATION",
        "LONGWAVE_RADIATION",
        "SURFACE_PRESSURE",
        "PRECIPITATION_MIN",
        "PRECIPITATION_MAX",
        "SOIL_TEMP_LAYER1",
        "SOIL_TEMP_LAYER2",
        "SOIL_HEAT_FLUX",
        "EVAPOTRANSPIRATION_ENERGY_FLUX"
    ]

    table = annual_location_variable_table(df_long, year)
    n_locations = len(table)

    output = []
    for variable in stat_vars:
        if variable in table.columns:
            output.append(table[variable].to_numpy(dtype=float))
        else:
            output.append(np.full(n_locations, np.nan))

    return tuple(output)


# ============================================================
# CLIMATE SIMILARITY
# ============================================================

def parse_var_from_col(column: str) -> str:
    """
    Columns look like VARIABLE_MONTH_YEAR.
    Recover VARIABLE even when it contains underscores.
    """
    parts = column.split("_")
    return "_".join(parts[:-2]) if len(parts) >= 3 else column


def pivot_to_wide(df_long: pd.DataFrame, year: int) -> pd.DataFrame | None:
    df_year = df_long[df_long["Year"] == year].copy()

    if df_year.empty:
        return None

    wide = (
        df_year
        .groupby(["CITY", "STATE", "Variable", "Month"], as_index=False)["Value"]
        .mean()
        .pivot_table(
            index=["CITY", "STATE"],
            columns=["Variable", "Month"],
            values="Value",
            aggfunc="mean"
        )
    )

    wide.columns = [
        f"{variable}_{month}_{year}"
        for variable, month in wide.columns.to_flat_index()
    ]

    return (
        wide
        .reset_index()
        .sort_values(["CITY", "STATE"])
        .reset_index(drop=True)
    )


def select_climate_columns(df_wide: pd.DataFrame) -> list[str]:
    return [
        column
        for column in df_wide.columns
        if column not in {"CITY", "STATE"}
        and parse_var_from_col(column) in ALLOWED_VARS
    ]


def prepare_similarity_matrix(
    df_long: pd.DataFrame,
    year: int,
    weights: dict[str, float] | None
):
    df_wide = pivot_to_wide(df_long, year)

    if df_wide is None:
        return None, None, None

    climate_columns = select_climate_columns(df_wide)

    if weights:
        climate_columns = [
            column
            for column in climate_columns
            if float(weights.get(parse_var_from_col(column), 1.0)) > 0
        ]

    if not climate_columns:
        return None, None, None

    matrix = (
        df_wide[climate_columns]
        .astype(float)
        .replace([np.inf, -np.inf], np.nan)
    )

    medians = matrix.median(numeric_only=True)
    matrix = matrix.fillna(medians).fillna(0.0)

    scaler = StandardScaler()
    standardized = pd.DataFrame(
        scaler.fit_transform(matrix),
        columns=climate_columns,
        index=df_wide.index
    )

    if weights:
        for column in climate_columns:
            variable = parse_var_from_col(column)
            standardized[column] *= float(weights.get(variable, 1.0))

    return df_wide, standardized, climate_columns


def compute_similarity(
    selected_city: str,
    selected_state: str,
    df_long: pd.DataFrame,
    weights: dict[str, float] | None,
    year: int,
    use_raw: bool = False,
    use_cache: bool = False
):
    """
    Return a CITY/STATE-keyed similarity table.

    The old script returned a bare vector and later attached it to separately
    generated city lists. This function keeps the identifiers beside every score.
    """
    weights_signature = tuple(sorted((weights or {}).items()))
    data_mtime = climate_file.stat().st_mtime_ns if climate_file.exists() else None
    cache_key = (
        selected_city,
        selected_state,
        int(year),
        bool(use_raw),
        weights_signature,
        data_mtime
    )

    cache = {}

    if use_cache and similarity_cache.exists():
        try:
            cache = joblib.load(similarity_cache)
            cached = cache.get(cache_key)
            if cached is not None:
                return cached
        except Exception:
            cache = {}

    df_wide, standardized, climate_columns = prepare_similarity_matrix(
        df_long,
        year,
        weights
    )

    if df_wide is None or standardized is None:
        return None, None

    reference_mask = (
        df_wide["CITY"].eq(selected_city)
        & df_wide["STATE"].eq(selected_state)
    )

    if not reference_mask.any():
        return None, None

    reference_index = int(np.flatnonzero(reference_mask.to_numpy())[0])
    reference_vector = standardized.iloc[[reference_index]]

    similarities = cosine_similarity(reference_vector, standardized)[0]
    similarity_scores = similarities if use_raw else (similarities + 1.0) / 2.0
    similarity_scores[reference_index] = 1.0

    results = df_wide[["CITY", "STATE"]].copy()
    results["Similarity Score"] = similarity_scores

    annual = annual_location_variable_table(df_long, year)
    headline_variables = [
        "EVAPOTRANSPIRATION",
        "PRECIPITATION_AVG",
        "TEMPERATURE"
    ]

    for variable in headline_variables:
        if variable not in annual.columns:
            annual[variable] = np.nan

    results = results.merge(
        annual[["CITY", "STATE"] + headline_variables],
        on=["CITY", "STATE"],
        how="left"
    )

    reference_stats = annual[
        annual["CITY"].eq(selected_city)
        & annual["STATE"].eq(selected_state)
    ]

    if not reference_stats.empty:
        ref = reference_stats.iloc[0]
        results["ETo Diff (mm/day)"] = (
            safe_float(ref["EVAPOTRANSPIRATION"])
            - results["EVAPOTRANSPIRATION"]
        )
        results["Precip Diff (mm/day)"] = (
            safe_float(ref["PRECIPITATION_AVG"])
            - results["PRECIPITATION_AVG"]
        )
        results["Temp Diff (°C)"] = (
            safe_float(ref["TEMPERATURE"])
            - results["TEMPERATURE"]
        )

    results = (
        results
        .sort_values("Similarity Score", ascending=False)
        .reset_index(drop=True)
    )

    output = (results, climate_columns)

    if use_cache:
        cache[cache_key] = output
        try:
            joblib.dump(cache, similarity_cache)
        except Exception:
            pass

    return output


