def _threshold_tuple_to_dict(values: tuple[float, ...]) -> dict[str, float]:
    keys = [
        "temp_min_abs", "temp_min_opt", "temp_max_opt", "temp_max_abs",
        "precip_min_abs", "precip_min_opt", "precip_max_opt", "precip_max_abs",
        "water_deficit_abs", "water_deficit_opt"
    ]
    return dict(zip(keys, values))


for _crop_name, _profile in ADDITIONAL_CROP_PRESETS.items():
    CROP_SEASONAL_WINDOWS.setdefault(_crop_name, {}).update(_profile["windows"])
    CROP_STAGE_THRESHOLDS.setdefault(_crop_name, {})
    for _stage_name, _values in _profile["thresholds"].items():
        CROP_STAGE_THRESHOLDS[_crop_name][_stage_name] = _threshold_tuple_to_dict(_values)


def load_json_file(path: Path, default):
    try:
        if path.exists():
            return json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        pass
    return deepcopy(default)


def save_json_file(path: Path, data) -> tuple[bool, str]:
    try:
        path.write_text(json.dumps(data, indent=2, ensure_ascii=False), encoding="utf-8")
        return True, "Saved"
    except Exception as exc:
        return False, str(exc)


def load_custom_crop_profiles() -> dict:
    profiles = load_json_file(custom_crop_file, {})
    if not isinstance(profiles, dict):
        return {}
    return profiles


def merge_custom_crop_profiles(profiles: dict) -> None:
    for crop_name, profile in profiles.items():
        windows = profile.get("windows", {})
        thresholds = profile.get("thresholds", {})
        if windows and thresholds:
            CROP_SEASONAL_WINDOWS.setdefault(crop_name, {}).update(windows)
            CROP_STAGE_THRESHOLDS.setdefault(crop_name, {}).update(thresholds)


