def haversine_km(lat1: float, lon1: float, lat2: float, lon2: float) -> float:
    if any(pd.isna(value) for value in [lat1, lon1, lat2, lon2]):
        return np.nan
    radius = 6371.0088
    phi1, phi2 = np.radians([lat1, lat2])
    delta_phi = np.radians(lat2 - lat1)
    delta_lambda = np.radians(lon2 - lon1)
    a = np.sin(delta_phi / 2) ** 2 + np.cos(phi1) * np.cos(phi2) * np.sin(delta_lambda / 2) ** 2
    return float(2 * radius * np.arctan2(np.sqrt(a), np.sqrt(1 - a)))


def initial_bearing_degrees(lat1: float, lon1: float, lat2: float, lon2: float) -> float:
    if any(pd.isna(value) for value in [lat1, lon1, lat2, lon2]):
        return np.nan
    phi1, phi2 = np.radians([lat1, lat2])
    delta_lambda = np.radians(lon2 - lon1)
    y = np.sin(delta_lambda) * np.cos(phi2)
    x = np.cos(phi1) * np.sin(phi2) - np.sin(phi1) * np.cos(phi2) * np.cos(delta_lambda)
    return float((np.degrees(np.arctan2(y, x)) + 360.0) % 360.0)


def bearing_label(degrees: float) -> str:
    if pd.isna(degrees):
        return "Unknown"
    labels = ["N", "NE", "E", "SE", "S", "SW", "W", "NW"]
    return labels[int((degrees + 22.5) // 45) % 8]


def compute_climate_migration_trajectory(
    df_long: pd.DataFrame,
    city: str,
    state: str,
    reference_year: int,
    comparison_years: list[int],
    variables: list[str],
    exclude_reference_location: bool = False
) -> pd.DataFrame:
    reference_coordinates = mexico_cities[
        mexico_cities["CITY"].eq(city) & mexico_cities["STATE"].eq(state)
    ]
    if reference_coordinates.empty:
        return pd.DataFrame()
    ref_coord = reference_coordinates.iloc[0]
    rows = []
    for comparison_year in sorted(set(int(year) for year in comparison_years)):
        result, common_columns, error = compute_cross_year_analogues(
            df_long,
            city,
            state,
            int(reference_year),
            comparison_year,
            variables,
            False
        )
        if error or result is None or result.empty:
            continue
        candidates = result.copy()
        if exclude_reference_location:
            candidates = candidates[
                ~(
                    candidates["CITY"].eq(city)
                    & candidates["STATE"].eq(state)
                )
            ]
        if candidates.empty:
            continue
        best = candidates.iloc[0]
        coordinate = mexico_cities[
            mexico_cities["CITY"].eq(best["CITY"])
            & mexico_cities["STATE"].eq(best["STATE"])
        ]
        if coordinate.empty:
            continue
        coordinate = coordinate.iloc[0]
        distance = haversine_km(
            ref_coord["lat"], ref_coord["lng"], coordinate["lat"], coordinate["lng"]
        )
        bearing = initial_bearing_degrees(
            ref_coord["lat"], ref_coord["lng"], coordinate["lat"], coordinate["lng"]
        )
        rows.append({
            "Reference City": city,
            "Reference State": state,
            "Reference Year": int(reference_year),
            "Comparison Year": int(comparison_year),
            "Analogue City": best["CITY"],
            "Analogue State": best["STATE"],
            "Analogue Location": f"{best['CITY']} ({best['STATE']})",
            "Analogue Similarity": float(best["Analogue Similarity"]),
            "Distance from Reference (km)": distance,
            "Bearing (degrees)": bearing,
            "Direction": bearing_label(bearing),
            "Latitude": float(coordinate["lat"]),
            "Longitude": float(coordinate["lng"]),
            "Shared Features": len(common_columns)
        })
    return pd.DataFrame(rows).sort_values("Comparison Year").reset_index(drop=True) if rows else pd.DataFrame()


def compute_constrained_similarity(
    selected_city: str,
    selected_state: str,
    df_long: pd.DataFrame,
    weights: dict[str, float],
    year: int,
    minimum_distance_km: float,
    maximum_distance_km: float,
    state_mode: str,
    selected_states: list[str] | None,
    metadata: pd.DataFrame | None = None,
    elevation_tolerance_m: float | None = None,
    landscape_filter: str = "Any"
) -> pd.DataFrame:
    result, _ = compute_similarity(
        selected_city,
        selected_state,
        df_long,
        weights,
        year,
        False,
        False
    )
    if result is None or result.empty:
        return pd.DataFrame()
    joined = result.merge(mexico_cities, on=["CITY", "STATE"], how="left")
    reference = mexico_cities[
        mexico_cities["CITY"].eq(selected_city)
        & mexico_cities["STATE"].eq(selected_state)
    ]
    if reference.empty:
        return pd.DataFrame()
    ref = reference.iloc[0]
    joined["Distance from Reference (km)"] = joined.apply(
        lambda row: haversine_km(ref["lat"], ref["lng"], row["lat"], row["lng"]), axis=1
    )
    joined = joined[
        joined["Distance from Reference (km)"].between(
            float(minimum_distance_km), float(maximum_distance_km)
        )
    ]
    if state_mode == "Same state only":
        joined = joined[joined["STATE"].eq(selected_state)]
    elif state_mode == "Selected states" and selected_states:
        joined = joined[joined["STATE"].isin(selected_states)]

    if metadata is not None and not metadata.empty:
        metadata = metadata.copy()
        metadata.columns = [str(column).strip() for column in metadata.columns]
        if {"CITY", "STATE"}.issubset(metadata.columns):
            joined = joined.merge(metadata, on=["CITY", "STATE"], how="left")
            reference_meta = metadata[
                metadata["CITY"].astype(str).str.strip().eq(selected_city)
                & metadata["STATE"].astype(str).str.strip().eq(selected_state)
            ]
            if (
                elevation_tolerance_m is not None
                and "Elevation_m" in joined.columns
                and not reference_meta.empty
                and "Elevation_m" in reference_meta.columns
            ):
                reference_elevation = pd.to_numeric(
                    reference_meta.iloc[0]["Elevation_m"], errors="coerce"
                )
                joined["Elevation_m"] = pd.to_numeric(joined["Elevation_m"], errors="coerce")
                if pd.notna(reference_elevation):
                    joined["Elevation Difference (m)"] = (
                        joined["Elevation_m"] - reference_elevation
                    ).abs()
                    joined = joined[
                        joined["Elevation Difference (m)"] <= float(elevation_tolerance_m)
                    ]
            if landscape_filter != "Any" and "Landscape" in joined.columns:
                joined = joined[
                    joined["Landscape"].astype(str).str.casefold().eq(landscape_filter.casefold())
                ]
    return joined.sort_values("Similarity Score", ascending=False).reset_index(drop=True)


def compute_state_summary(
    df_long: pd.DataFrame,
    variable: str,
    year_range: tuple[int, int],
    months: list[str],
    summary_mode: str
) -> pd.DataFrame:
    filtered = df_long[
        df_long["Variable"].eq(variable)
        & df_long["Year"].between(year_range[0], year_range[1])
        & df_long["Month"].isin([month.upper() for month in months])
    ].copy()
    if filtered.empty:
        return pd.DataFrame()
    annual = filtered.groupby(["STATE", "CITY", "Year"], as_index=False)["Value"].mean()
    rows = []
    for state, group in annual.groupby("STATE"):
        yearly_state = group.groupby("Year", as_index=False)["Value"].mean()
        trend = calculate_trend_for_series(yearly_state)
        values = group["Value"].dropna()
        if values.empty:
            continue
        if summary_mode == "Median":
            headline = float(values.median())
        elif summary_mode == "Maximum":
            headline = float(values.max())
        elif summary_mode == "Minimum":
            headline = float(values.min())
        else:
            headline = float(values.mean())
        rows.append({
            "STATE": state,
            "Summary Value": headline,
            "Mean": float(values.mean()),
            "Median": float(values.median()),
            "Minimum": float(values.min()),
            "Maximum": float(values.max()),
            "Std": float(values.std(ddof=1)) if len(values) > 1 else 0.0,
            "Cities Available": int(group["CITY"].nunique()),
            "Years Available": int(group["Year"].nunique()),
            "Sen's Slope per Year": trend.get("Sen's Slope per Year", np.nan),
            "Mann-Kendall p-value": trend.get("Mann-Kendall p-value", np.nan),
            "Trend": trend.get("Trend", "Unknown")
        })
    result = pd.DataFrame(rows)
    return result.sort_values("Summary Value", ascending=False).reset_index(drop=True) if not result.empty else result


def compute_climate_space_embedding(
    df_long: pd.DataFrame,
    year_range: tuple[int, int],
    months: list[str],
    variables: list[str],
    method: str,
    minimum_completeness: float,
    random_seed: int
) -> dict | None:
    locations, standardised, feature_columns = build_climate_feature_matrix(
        df_long, year_range, months, variables, minimum_completeness
    )
    if locations is None or len(locations) < 4:
        return None
    matrix = standardised.to_numpy(dtype=float)
    method_used = method
    if method == "UMAP":
        try:
            import umap
            reducer = umap.UMAP(
                n_components=2,
                random_state=int(random_seed),
                n_neighbors=min(15, max(2, len(locations) - 1)),
                min_dist=0.1
            )
            coordinates = reducer.fit_transform(matrix)
        except Exception:
            method_used = "t-SNE fallback"
            perplexity = min(30, max(2, (len(locations) - 1) // 3))
            coordinates = TSNE(
                n_components=2,
                random_state=int(random_seed),
                perplexity=perplexity,
                init="pca",
                learning_rate="auto"
            ).fit_transform(matrix)
    elif method == "t-SNE":
        perplexity = min(30, max(2, (len(locations) - 1) // 3))
        coordinates = TSNE(
            n_components=2,
            random_state=int(random_seed),
            perplexity=perplexity,
            init="pca",
            learning_rate="auto"
        ).fit_transform(matrix)
    else:
        pca = PCA(n_components=2, random_state=int(random_seed))
        coordinates = pca.fit_transform(matrix)
    embedding = locations.copy()
    embedding["Dimension 1"] = coordinates[:, 0]
    embedding["Dimension 2"] = coordinates[:, 1]
    return {
        "embedding": embedding,
        "method": method_used,
        "features": feature_columns,
        "standardised": standardised
    }


def percentile_risk(series: pd.Series, higher_is_riskier: bool = True) -> pd.Series:
    numeric = pd.to_numeric(series, errors="coerce")
    ranked = numeric.rank(pct=True, method="average") * 100.0
    return ranked if higher_is_riskier else 100.0 - ranked


def compute_composite_agricultural_risk(
    df_long: pd.DataFrame,
    year_range: tuple[int, int],
    months: list[str],
    weights: dict[str, float],
    crop: str | None = None,
    stage: str | None = None
) -> pd.DataFrame:
    months_upper = [month.upper() for month in months]
    location_base = get_city_state_order(df_long)

    water = compute_water_stress_table(df_long, "Cities", year_range, months)
    if water.empty:
        return pd.DataFrame()
    result = location_base.merge(
        water[["CITY", "STATE", "Water Stress Score"]], on=["CITY", "STATE"], how="left"
    )

    temp_variable = "TEMPERATURE_MAX" if "TEMPERATURE_MAX" in available_variables else "TEMPERATURE"
    temperature = df_long[
        df_long["Variable"].eq(temp_variable)
        & df_long["Year"].between(year_range[0], year_range[1])
        & df_long["Month"].isin(months_upper)
    ].groupby(["CITY", "STATE"], as_index=False)["Value"].mean().rename(columns={"Value": "Heat Exposure"})
    result = result.merge(temperature, on=["CITY", "STATE"], how="left")

    precip = df_long[
        df_long["Variable"].eq("PRECIPITATION_AVG")
        & df_long["Year"].between(year_range[0], year_range[1])
        & df_long["Month"].isin(months_upper)
    ].groupby(["CITY", "STATE", "Year"], as_index=False)["Value"].mean()
    variability = precip.groupby(["CITY", "STATE"])["Value"].agg(["mean", "std"]).reset_index()
    variability["Rainfall Variability"] = np.where(
        variability["mean"].abs() > 1e-12,
        variability["std"] / variability["mean"].abs() * 100.0,
        np.nan
    )
    result = result.merge(
        variability[["CITY", "STATE", "Rainfall Variability"]], on=["CITY", "STATE"], how="left"
    )

    trend = compute_trend_table(
        df_long,
        "Cities",
        "TEMPERATURE" if "TEMPERATURE" in available_variables else temp_variable,
        year_range,
        months,
        0.05
    )
    if not trend.empty:
        result = result.merge(
            trend[["CITY", "STATE", "Sen's Slope per Year"]].rename(
                columns={"Sen's Slope per Year": "Warming Trend"}
            ),
            on=["CITY", "STATE"],
            how="left"
        )
    else:
        result["Warming Trend"] = np.nan

    span = year_range[1] - year_range[0] + 1
    baseline_end = year_range[0] + max(1, span // 3) - 1
    comparison_start = year_range[1] - max(1, span // 3) + 1
    anomaly = compute_anomaly_table(
        df_long,
        "Cities",
        "TEMPERATURE" if "TEMPERATURE" in available_variables else temp_variable,
        (year_range[0], baseline_end),
        (comparison_start, year_range[1]),
        months
    ) if baseline_end < comparison_start else pd.DataFrame()
    if not anomaly.empty:
        result = result.merge(
            anomaly[["CITY", "STATE", "Standardized Anomaly (z)"]].rename(
                columns={"Standardized Anomaly (z)": "Temperature Anomaly z"}
            ),
            on=["CITY", "STATE"],
            how="left"
        )
    else:
        result["Temperature Anomaly z"] = np.nan

    if crop and stage:
        stability, _ = compute_crop_stability_tables(
            df_long,
            crop,
            stage,
            year_range,
            CROP_SEASONAL_WINDOWS[crop][stage],
            "Limiting factor",
            CROP_STAGE_THRESHOLDS[crop][stage]
        )
        if not stability.empty:
            result = result.merge(
                stability[["CITY", "STATE", "Reliability Score"]], on=["CITY", "STATE"], how="left"
            )
            result["Crop Instability"] = 100.0 - result["Reliability Score"]
        else:
            result["Crop Instability"] = np.nan
    else:
        result["Crop Instability"] = np.nan

    component_specs = {
        "Water Stress": ("Water Stress Score", True),
        "Heat Exposure": ("Heat Exposure", True),
        "Rainfall Variability": ("Rainfall Variability", True),
        "Warming Trend": ("Warming Trend", True),
        "Temperature Anomaly": ("Temperature Anomaly z", True),
        "Crop Instability": ("Crop Instability", True)
    }
    weighted_sum = pd.Series(0.0, index=result.index)
    available_weight = pd.Series(0.0, index=result.index)
    for label, (column, higher_is_riskier) in component_specs.items():
        risk_column = f"{label} Risk"
        result[risk_column] = percentile_risk(result[column], higher_is_riskier)
        weight = float(weights.get(label, 0.0))
        valid = result[risk_column].notna()
        weighted_sum.loc[valid] += result.loc[valid, risk_column] * weight
        available_weight.loc[valid] += weight
    result["Composite Risk Score"] = np.where(
        available_weight > 0, weighted_sum / available_weight, np.nan
    )
    result["Risk Class"] = pd.cut(
        result["Composite Risk Score"],
        bins=[-np.inf, 20, 40, 60, 80, np.inf],
        labels=["Very low", "Low", "Moderate", "High", "Very high"]
    ).astype(str)
    result["Location"] = result["CITY"] + " (" + result["STATE"] + ")"
    return result.sort_values("Composite Risk Score", ascending=False).reset_index(drop=True)


