def cyclic_month_window(start_index: int, length: int) -> list[str]:
    return [MONTHS[(start_index + offset) % 12] for offset in range(length)]


def optimise_planting_dates(
    df_long: pd.DataFrame,
    city: str,
    state: str,
    crop: str,
    stage: str,
    year_range: tuple[int, int],
    window_length: int,
    aggregation_method: str
) -> pd.DataFrame:
    rows = []
    selected_years = list(range(int(year_range[0]), int(year_range[1]) + 1))
    thresholds = CROP_STAGE_THRESHOLDS[crop][stage]
    for start_index in range(12):
        months = cyclic_month_window(start_index, int(window_length))
        history = get_location_crop_window_series(
            df_long,
            city,
            state,
            crop,
            stage,
            selected_years,
            months,
            aggregation_method,
            thresholds
        )
        if history.empty:
            continue
        scores = pd.to_numeric(history["Overall Suitability (%)"], errors="coerce").dropna()
        if scores.empty:
            continue
        rows.append({
            "Planting Month": MONTHS[start_index],
            "Window Months": ", ".join(months),
            "N Years": int(history["Year"].nunique()),
            "Mean Suitability (%)": float(scores.mean()),
            "Median Suitability (%)": float(scores.median()),
            "Minimum Suitability (%)": float(scores.min()),
            "Std Suitability (%)": float(scores.std(ddof=1)) if len(scores) > 1 else 0.0,
            "% Suitable Years (>=60)": float((scores >= 60).mean() * 100.0),
            "% Highly Suitable Years (>=80)": float((scores >= 80).mean() * 100.0),
            "Mean Water Balance (mm)": float(history["Water Deficit P - ETo (mm)"].mean()),
            "Recurring Limiting Factor": (
                history["Limiting Factor"].mode().iloc[0]
                if not history["Limiting Factor"].mode().empty
                else "Unknown"
            )
        })
    result = pd.DataFrame(rows)
    if result.empty:
        return result
    result["Planting Window Score"] = np.clip(
        0.50 * result["Mean Suitability (%)"]
        + 0.25 * result["Minimum Suitability (%)"]
        + 0.25 * result["% Suitable Years (>=60)"]
        - 0.15 * result["Std Suitability (%)"],
        0,
        100
    )
    return result.sort_values("Planting Window Score", ascending=False).reset_index(drop=True)


def estimate_irrigation_requirements(
    df_long: pd.DataFrame,
    city: str,
    state: str,
    year_range: tuple[int, int],
    months: list[str],
    crop_coefficient: float,
    irrigation_efficiency: float,
    effective_precipitation_fraction: float
) -> pd.DataFrame:
    filtered = df_long[
        df_long["CITY"].eq(city)
        & df_long["STATE"].eq(state)
        & df_long["Year"].between(year_range[0], year_range[1])
        & df_long["Month"].isin([month.upper() for month in months])
        & df_long["Variable"].isin(["PRECIPITATION_AVG", "EVAPOTRANSPIRATION"])
    ].copy()
    if filtered.empty:
        return pd.DataFrame()
    monthly = filtered.groupby(["Year", "Month", "Variable"], as_index=False)["Value"].mean().pivot_table(
        index=["Year", "Month"], columns="Variable", values="Value", aggfunc="mean"
    ).reset_index()
    if "PRECIPITATION_AVG" not in monthly.columns or "EVAPOTRANSPIRATION" not in monthly.columns:
        return pd.DataFrame()
    monthly["Days"] = monthly["Month"].map(MONTH_DAYS_APPROX).fillna(30)
    monthly["Precipitation Total (mm)"] = monthly["PRECIPITATION_AVG"] * monthly["Days"]
    monthly["Reference ETo Total (mm)"] = monthly["EVAPOTRANSPIRATION"] * monthly["Days"]
    monthly["Crop ETo Total (mm)"] = monthly["Reference ETo Total (mm)"] * float(crop_coefficient)
    monthly["Effective Precipitation (mm)"] = monthly["Precipitation Total (mm)"] * float(effective_precipitation_fraction)
    monthly["Net Irrigation Requirement (mm)"] = (
        monthly["Crop ETo Total (mm)"] - monthly["Effective Precipitation (mm)"]
    ).clip(lower=0)
    efficiency = max(float(irrigation_efficiency), 1e-6)
    monthly["Gross Irrigation Requirement (mm)"] = monthly["Net Irrigation Requirement (mm)"] / efficiency
    yearly = monthly.groupby("Year", as_index=False).agg({
        "Precipitation Total (mm)": "sum",
        "Reference ETo Total (mm)": "sum",
        "Crop ETo Total (mm)": "sum",
        "Effective Precipitation (mm)": "sum",
        "Net Irrigation Requirement (mm)": "sum",
        "Gross Irrigation Requirement (mm)": "sum"
    })
    yearly["Gross Irrigation (m³/ha)"] = yearly["Gross Irrigation Requirement (mm)"] * 10.0
    yearly["CITY"] = city
    yearly["STATE"] = state
    yearly["Location"] = f"{city} ({state})"
    return yearly


def compute_crop_stage_vulnerability(
    df_long: pd.DataFrame,
    city: str,
    state: str,
    crop: str,
    year_range: tuple[int, int],
    aggregation_method: str
) -> pd.DataFrame:
    rows = []
    years_selected = list(range(year_range[0], year_range[1] + 1))
    for stage, months in CROP_SEASONAL_WINDOWS[crop].items():
        history = get_location_crop_window_series(
            df_long,
            city,
            state,
            crop,
            stage,
            years_selected,
            months,
            aggregation_method,
            CROP_STAGE_THRESHOLDS[crop][stage]
        )
        if history.empty:
            continue
        scores = history["Overall Suitability (%)"].dropna()
        if scores.empty:
            continue
        limiting = history["Limiting Factor"].fillna("Unknown").value_counts()
        rows.append({
            "Crop Stage": stage,
            "Months": ", ".join(months),
            "N Years": int(history["Year"].nunique()),
            "Mean Suitability (%)": float(scores.mean()),
            "Minimum Suitability (%)": float(scores.min()),
            "Std Suitability (%)": float(scores.std(ddof=1)) if len(scores) > 1 else 0.0,
            "% Failure Years (<40)": float((scores < 40).mean() * 100.0),
            "% Suitable Years (>=60)": float((scores >= 60).mean() * 100.0),
            "Mean Temperature Suitability (%)": float(history["Temperature Suitability (%)"].mean()),
            "Mean Precipitation Suitability (%)": float(history["Precipitation Suitability (%)"].mean()),
            "Mean Water Balance Suitability (%)": float(history["Water Balance Suitability (%)"].mean()),
            "Recurring Limiting Factor": limiting.index[0] if not limiting.empty else "Unknown",
            "Recurring Limiting Factor (%)": float(limiting.iloc[0] / limiting.sum() * 100.0) if not limiting.empty else np.nan
        })
    result = pd.DataFrame(rows)
    if result.empty:
        return result
    result["Vulnerability Score"] = np.clip(
        100.0 - result["Mean Suitability (%)"]
        + 0.30 * result["% Failure Years (<40)"]
        + 0.20 * result["Std Suitability (%)"],
        0,
        100
    )
    return result.sort_values("Vulnerability Score", ascending=False).reset_index(drop=True)


def choose_full_season_stage(crop: str) -> str:
    stages = list(CROP_SEASONAL_WINDOWS[crop])
    full_candidates = [stage for stage in stages if "full" in stage.casefold()]
    return full_candidates[0] if full_candidates else stages[-1]


def compute_multi_crop_portfolio(
    df_long: pd.DataFrame,
    crops: list[str],
    year_range: tuple[int, int],
    aggregation_method: str
) -> tuple[pd.DataFrame, pd.DataFrame]:
    crop_tables = []
    for crop in crops:
        stage = choose_full_season_stage(crop)
        summary, _ = compute_crop_stability_tables(
            df_long,
            crop,
            stage,
            year_range,
            CROP_SEASONAL_WINDOWS[crop][stage],
            aggregation_method,
            CROP_STAGE_THRESHOLDS[crop][stage]
        )
        if summary.empty:
            continue
        selected = summary[[
            "CITY", "STATE", "Location", "Reliability Score", "Mean Suitability (%)",
            "Minimum Suitability (%)", "% Suitable Years (>=60)", "Recurring Limiting Factor"
        ]].copy()
        selected["Crop"] = crop
        selected["Stage"] = stage
        crop_tables.append(selected)
    if not crop_tables:
        return pd.DataFrame(), pd.DataFrame()
    detail = pd.concat(crop_tables, ignore_index=True)
    rows = []
    for (city, state, location), group in detail.groupby(["CITY", "STATE", "Location"]):
        reliability = group["Reliability Score"].dropna()
        if reliability.empty:
            continue
        suitable_crops = group.loc[group["Reliability Score"] >= 60, "Crop"].tolist()
        rows.append({
            "CITY": city,
            "STATE": state,
            "Location": location,
            "Crops Evaluated": int(group["Crop"].nunique()),
            "Mean Portfolio Reliability": float(reliability.mean()),
            "Minimum Crop Reliability": float(reliability.min()),
            "Maximum Crop Reliability": float(reliability.max()),
            "Portfolio Spread": float(reliability.std(ddof=1)) if len(reliability) > 1 else 0.0,
            "Suitable Crops": ", ".join(suitable_crops) if suitable_crops else "None",
            "N Suitable Crops": len(suitable_crops),
            "Best Crop": group.loc[group["Reliability Score"].idxmax(), "Crop"],
            "Worst Crop": group.loc[group["Reliability Score"].idxmin(), "Crop"]
        })
    portfolio = pd.DataFrame(rows)
    if portfolio.empty:
        return portfolio, detail
    portfolio["Portfolio Score"] = np.clip(
        0.60 * portfolio["Mean Portfolio Reliability"]
        + 0.20 * portfolio["Minimum Crop Reliability"]
        + 20.0 * portfolio["N Suitable Crops"] / portfolio["Crops Evaluated"].clip(lower=1)
        - 0.10 * portfolio["Portfolio Spread"],
        0,
        100
    )
    return portfolio.sort_values("Portfolio Score", ascending=False).reset_index(drop=True), detail


def compute_crop_substitution_options(
    df_long: pd.DataFrame,
    city: str,
    state: str,
    current_crop: str,
    year_range: tuple[int, int],
    aggregation_method: str
) -> pd.DataFrame:
    rows = []
    for crop in CROP_SEASONAL_WINDOWS:
        stage = choose_full_season_stage(crop)
        summary, yearly = compute_crop_stability_tables(
            df_long,
            crop,
            stage,
            year_range,
            CROP_SEASONAL_WINDOWS[crop][stage],
            aggregation_method,
            CROP_STAGE_THRESHOLDS[crop][stage]
        )
        if summary.empty:
            continue
        selected = summary[summary["CITY"].eq(city) & summary["STATE"].eq(state)]
        if selected.empty:
            continue
        row = selected.iloc[0]
        yearly_selected = yearly[yearly["CITY"].eq(city) & yearly["STATE"].eq(state)]
        mean_eto = float(yearly_selected["Seasonal ETo Total (mm)"].mean()) if not yearly_selected.empty else np.nan
        mean_precip = float(yearly_selected["Seasonal Precipitation Total (mm)"].mean()) if not yearly_selected.empty else np.nan
        rows.append({
            "Crop": crop,
            "Stage": stage,
            "Current Crop": crop == current_crop,
            "Reliability Score": float(row["Reliability Score"]),
            "Mean Suitability (%)": float(row["Mean Suitability (%)"]),
            "Minimum Suitability (%)": float(row["Minimum Suitability (%)"]),
            "% Suitable Years (>=60)": float(row["% Suitable Years (>=60)"]),
            "Mean Seasonal ETo (mm)": mean_eto,
            "Mean Seasonal Precipitation (mm)": mean_precip,
            "Recurring Limiting Factor": row["Recurring Limiting Factor"],
            "Stability Class": row["Stability Class"]
        })
    result = pd.DataFrame(rows)
    if result.empty:
        return result
    current = result[result["Current Crop"]]
    current_reliability = float(current.iloc[0]["Reliability Score"]) if not current.empty else np.nan
    current_eto = float(current.iloc[0]["Mean Seasonal ETo (mm)"]) if not current.empty else np.nan
    result["Reliability Gain vs Current"] = result["Reliability Score"] - current_reliability
    result["ETo Change vs Current (mm)"] = result["Mean Seasonal ETo (mm)"] - current_eto
    result["Substitution Score"] = np.clip(
        result["Reliability Score"]
        + 0.35 * result["Reliability Gain vs Current"].fillna(0)
        - 0.02 * result["ETo Change vs Current (mm)"].clip(lower=0).fillna(0),
        0,
        100
    )
    return result.sort_values("Substitution Score", ascending=False).reset_index(drop=True)


