def compute_monthly_extreme_events(
    df_long: pd.DataFrame,
    city: str,
    state: str,
    baseline_range: tuple[int, int],
    analysis_range: tuple[int, int],
    hot_quantile: float,
    dry_quantile: float,
    wet_quantile: float
) -> tuple[pd.DataFrame, pd.DataFrame]:
    variables = ["TEMPERATURE_MAX", "TEMPERATURE", "PRECIPITATION_AVG", "EVAPOTRANSPIRATION"]
    filtered = df_long[
        df_long["CITY"].eq(city)
        & df_long["STATE"].eq(state)
        & df_long["Year"].between(min(baseline_range[0], analysis_range[0]), max(baseline_range[1], analysis_range[1]))
        & df_long["Variable"].isin(variables)
    ].copy()
    if filtered.empty:
        return pd.DataFrame(), pd.DataFrame()
    monthly = filtered.groupby(["Year", "Month", "Variable"], as_index=False)["Value"].mean().pivot_table(
        index=["Year", "Month"], columns="Variable", values="Value", aggfunc="mean"
    ).reset_index()
    temp_col = "TEMPERATURE_MAX" if "TEMPERATURE_MAX" in monthly.columns else "TEMPERATURE"
    for column in [temp_col, "PRECIPITATION_AVG", "EVAPOTRANSPIRATION"]:
        if column not in monthly.columns:
            monthly[column] = np.nan
    monthly["Water Balance"] = monthly["PRECIPITATION_AVG"] - monthly["EVAPOTRANSPIRATION"]
    baseline = monthly[monthly["Year"].between(*baseline_range)]
    analysis = monthly[monthly["Year"].between(*analysis_range)].copy()
    if baseline.empty or analysis.empty:
        return pd.DataFrame(), pd.DataFrame()

    threshold_rows = []
    for month in MONTHS_UPPER:
        base_month = baseline[baseline["Month"].eq(month)]
        if base_month.empty:
            continue
        threshold_rows.append({
            "Month": month,
            "Hot Threshold": base_month[temp_col].quantile(hot_quantile),
            "Dry Threshold": base_month["PRECIPITATION_AVG"].quantile(dry_quantile),
            "Wet Threshold": base_month["PRECIPITATION_AVG"].quantile(wet_quantile),
            "Water Deficit Threshold": base_month["Water Balance"].quantile(dry_quantile)
        })
    thresholds = pd.DataFrame(threshold_rows)
    if thresholds.empty:
        return pd.DataFrame(), pd.DataFrame()
    detail = analysis.merge(thresholds, on="Month", how="left")
    detail["Hot Month"] = detail[temp_col] > detail["Hot Threshold"]
    detail["Dry Month"] = detail["PRECIPITATION_AVG"] < detail["Dry Threshold"]
    detail["Wet Month"] = detail["PRECIPITATION_AVG"] > detail["Wet Threshold"]
    detail["Severe Water Deficit Month"] = detail["Water Balance"] < detail["Water Deficit Threshold"]
    detail["Event Count"] = detail[["Hot Month", "Dry Month", "Wet Month", "Severe Water Deficit Month"]].sum(axis=1)
    yearly = detail.groupby("Year", as_index=False).agg({
        "Hot Month": "sum",
        "Dry Month": "sum",
        "Wet Month": "sum",
        "Severe Water Deficit Month": "sum",
        "Event Count": "sum"
    })
    yearly.columns = [
        "Year", "Hot Months", "Dry Months", "Wet Months",
        "Severe Water-Deficit Months", "Total Extreme Flags"
    ]
    return yearly, detail


def pettitt_test(values: np.ndarray) -> dict:
    values = np.asarray(values, dtype=float)
    values = values[np.isfinite(values)]
    n = len(values)
    if n < 6:
        return {"Change Index": np.nan, "Statistic": np.nan, "p-value": np.nan}
    ranks = stats.rankdata(values)
    u = np.array([2 * np.sum(ranks[:t + 1]) - (t + 1) * (n + 1) for t in range(n)])
    k = int(np.argmax(np.abs(u)))
    statistic = float(abs(u[k]))
    p_value = float(min(1.0, 2 * np.exp((-6 * statistic ** 2) / (n ** 3 + n ** 2))))
    return {"Change Index": k, "Statistic": statistic, "p-value": p_value}


def compute_change_point_analysis(
    df_long: pd.DataFrame,
    analysis_level: str,
    location_value,
    variable: str,
    year_range: tuple[int, int],
    months: list[str]
) -> tuple[pd.DataFrame, dict]:
    series = get_location_series(df_long, analysis_level, location_value, variable, year_range, months)
    if series.empty:
        return series, {}
    result = pettitt_test(series["Value"].to_numpy(dtype=float))
    if pd.notna(result.get("Change Index")):
        index = int(result["Change Index"])
        result["Change Year"] = int(series.iloc[index]["Year"])
        result["Mean Before"] = float(series.iloc[:index + 1]["Value"].mean())
        result["Mean After"] = float(series.iloc[index + 1:]["Value"].mean()) if index + 1 < len(series) else np.nan
        result["Mean Shift"] = result["Mean After"] - result["Mean Before"] if pd.notna(result["Mean After"]) else np.nan
    return series, result


def compute_climate_variability(
    df_long: pd.DataFrame,
    variable: str,
    year_range: tuple[int, int],
    months: list[str],
    rolling_window: int
) -> tuple[pd.DataFrame, pd.DataFrame]:
    filtered = df_long[
        df_long["Variable"].eq(variable)
        & df_long["Year"].between(year_range[0], year_range[1])
        & df_long["Month"].isin([month.upper() for month in months])
    ].copy()
    annual = filtered.groupby(["CITY", "STATE", "Year"], as_index=False)["Value"].mean()
    rows = []
    detail_rows = []
    for (city, state), group in annual.groupby(["CITY", "STATE"]):
        group = group.sort_values("Year").copy()
        values = group["Value"].dropna()
        if values.empty:
            continue
        mean = float(values.mean())
        std = float(values.std(ddof=1)) if len(values) > 1 else 0.0
        cv = std / abs(mean) * 100.0 if abs(mean) > 1e-12 else np.nan
        q25, q75 = values.quantile([0.25, 0.75])
        reliability = float(((values >= q25) & (values <= q75)).mean() * 100.0)
        rows.append({
            "CITY": city,
            "STATE": state,
            "Location": f"{city} ({state})",
            "Mean": mean,
            "Std": std,
            "CV (%)": cv,
            "Interquartile Range": float(q75 - q25),
            "Central-Range Reliability (%)": reliability,
            "Minimum": float(values.min()),
            "Maximum": float(values.max()),
            "N Years": int(group["Year"].nunique())
        })
        group["Rolling Mean"] = group["Value"].rolling(int(rolling_window), min_periods=2).mean()
        group["Rolling Std"] = group["Value"].rolling(int(rolling_window), min_periods=2).std()
        group["CITY"] = city
        group["STATE"] = state
        group["Location"] = f"{city} ({state})"
        detail_rows.append(group)
    summary = pd.DataFrame(rows)
    detail = pd.concat(detail_rows, ignore_index=True) if detail_rows else pd.DataFrame()
    return summary.sort_values("CV (%)", ascending=False).reset_index(drop=True) if not summary.empty else summary, detail


def _standardise_by_calendar_month(frame: pd.DataFrame, value_column: str, output_column: str) -> pd.DataFrame:
    result = frame.copy()
    result[output_column] = result.groupby("Month")[value_column].transform(
        lambda values: (values - values.mean()) / values.std(ddof=1) if values.std(ddof=1) and np.isfinite(values.std(ddof=1)) else np.nan
    )
    return result


def compute_seasonal_drought_indices(
    df_long: pd.DataFrame,
    city: str,
    state: str,
    year_range: tuple[int, int],
    accumulation_months: int
) -> pd.DataFrame:
    filtered = df_long[
        df_long["CITY"].eq(city)
        & df_long["STATE"].eq(state)
        & df_long["Year"].between(year_range[0], year_range[1])
        & df_long["Variable"].isin(["PRECIPITATION_AVG", "EVAPOTRANSPIRATION"])
    ].copy()
    if filtered.empty:
        return pd.DataFrame()
    monthly = filtered.groupby(["Year", "Month", "Variable"], as_index=False)["Value"].mean().pivot_table(
        index=["Year", "Month"], columns="Variable", values="Value", aggfunc="mean"
    ).reset_index()
    if "PRECIPITATION_AVG" not in monthly.columns or "EVAPOTRANSPIRATION" not in monthly.columns:
        return pd.DataFrame()
    month_number = {month.upper(): index + 1 for index, month in enumerate(MONTHS)}
    monthly["Month Number"] = monthly["Month"].map(month_number)
    monthly["Date"] = pd.to_datetime(dict(year=monthly["Year"], month=monthly["Month Number"], day=1), errors="coerce")
    monthly = monthly.sort_values("Date")
    monthly["Days"] = monthly["Month"].map(MONTH_DAYS_APPROX).fillna(30)
    monthly["Precipitation Total"] = monthly["PRECIPITATION_AVG"] * monthly["Days"]
    monthly["Water Balance Total"] = (monthly["PRECIPITATION_AVG"] - monthly["EVAPOTRANSPIRATION"]) * monthly["Days"]
    window = max(1, int(accumulation_months))
    monthly["Accumulated Precipitation"] = monthly["Precipitation Total"].rolling(window, min_periods=window).sum()
    monthly["Accumulated Water Balance"] = monthly["Water Balance Total"].rolling(window, min_periods=window).sum()
    monthly = _standardise_by_calendar_month(monthly, "Accumulated Precipitation", "Standardised Precipitation Index-like")
    monthly = _standardise_by_calendar_month(monthly, "Accumulated Water Balance", "Standardised Water-Balance Index-like")
    monthly["Drought Class"] = pd.cut(
        monthly["Standardised Water-Balance Index-like"],
        bins=[-np.inf, -2, -1.5, -1, 1, np.inf],
        labels=["Extreme drought", "Severe drought", "Moderate drought", "Near normal", "Wet"]
    ).astype(str)
    return monthly


def validate_future_scenario_data(frame: pd.DataFrame) -> tuple[pd.DataFrame | None, str | None]:
    required = {"CITY", "STATE", "Year", "Month", "Variable", "Value", "Scenario"}
    missing = required.difference(frame.columns)
    if missing:
        return None, f"Missing columns: {sorted(missing)}"
    clean = frame.copy()
    clean["CITY"] = clean["CITY"].astype(str).str.strip()
    clean["STATE"] = clean["STATE"].astype(str).str.strip()
    clean["Month"] = clean["Month"].astype(str).str.upper().str.strip()
    clean["Variable"] = clean["Variable"].astype(str).str.upper().str.strip()
    clean["Year"] = pd.to_numeric(clean["Year"], errors="coerce")
    clean["Value"] = pd.to_numeric(clean["Value"], errors="coerce")
    clean = clean.dropna(subset=["CITY", "STATE", "Year", "Month", "Variable", "Value", "Scenario"])
    clean["Year"] = clean["Year"].astype(int)
    if clean.empty:
        return None, "No valid scenario rows remained after cleaning."
    return clean, None


def compare_future_scenario(
    historical: pd.DataFrame,
    future: pd.DataFrame,
    scenario: str,
    variable: str,
    baseline_range: tuple[int, int],
    future_range: tuple[int, int],
    months: list[str]
) -> pd.DataFrame:
    hist = historical[
        historical["Variable"].eq(variable)
        & historical["Year"].between(*baseline_range)
        & historical["Month"].isin([month.upper() for month in months])
    ].groupby(["CITY", "STATE"], as_index=False)["Value"].mean().rename(columns={"Value": "Historical Mean"})
    fut = future[
        future["Scenario"].astype(str).eq(str(scenario))
        & future["Variable"].eq(variable)
        & future["Year"].between(*future_range)
        & future["Month"].isin([month.upper() for month in months])
    ].groupby(["CITY", "STATE"], as_index=False)["Value"].mean().rename(columns={"Value": "Future Mean"})
    result = hist.merge(fut, on=["CITY", "STATE"], how="inner")
    if result.empty:
        return result
    result["Absolute Change"] = result["Future Mean"] - result["Historical Mean"]
    result["% Change"] = np.where(
        result["Historical Mean"].abs() > 1e-12,
        result["Absolute Change"] / result["Historical Mean"] * 100.0,
        np.nan
    )
    result["Location"] = result["CITY"] + " (" + result["STATE"] + ")"
    result["Scenario"] = scenario
    return result.sort_values("Absolute Change", ascending=False).reset_index(drop=True)


