# COMPLETE-SUITE: ROBUSTNESS, REPORTING, AND WORKFLOW HELPERS
# ============================================================


def bootstrap_crop_uncertainty(
    df_long: pd.DataFrame,
    city: str,
    state: str,
    crop: str,
    stage: str,
    year_range: tuple[int, int],
    months: list[str],
    aggregation_method: str,
    n_bootstrap: int,
    threshold_noise_pct: float,
    random_seed: int
) -> tuple[pd.DataFrame, pd.DataFrame]:
    rng = np.random.default_rng(int(random_seed))
    years_selected = np.array(list(range(year_range[0], year_range[1] + 1)), dtype=int)
    base_thresholds = CROP_STAGE_THRESHOLDS[crop][stage]
    simulation_rows = []
    yearly_rows = []
    for run in range(int(n_bootstrap)):
        sampled_years = rng.choice(years_selected, size=len(years_selected), replace=True)
        perturbed = {}
        for key, value in base_thresholds.items():
            scale = max(abs(float(value)) * threshold_noise_pct / 100.0, threshold_noise_pct / 100.0)
            perturbed[key] = float(value) + float(rng.normal(0.0, scale))
        # Preserve ordered trapezoid thresholds.
        temp_values = sorted([
            perturbed["temp_min_abs"], perturbed["temp_min_opt"],
            perturbed["temp_max_opt"], perturbed["temp_max_abs"]
        ])
        precip_values = sorted([
            perturbed["precip_min_abs"], perturbed["precip_min_opt"],
            perturbed["precip_max_opt"], perturbed["precip_max_abs"]
        ])
        perturbed.update(dict(zip(
            ["temp_min_abs", "temp_min_opt", "temp_max_opt", "temp_max_abs"], temp_values
        )))
        perturbed.update(dict(zip(
            ["precip_min_abs", "precip_min_opt", "precip_max_opt", "precip_max_abs"], precip_values
        )))
        if perturbed["water_deficit_abs"] > perturbed["water_deficit_opt"]:
            perturbed["water_deficit_abs"], perturbed["water_deficit_opt"] = (
                perturbed["water_deficit_opt"], perturbed["water_deficit_abs"]
            )
        scores = []
        for year in sampled_years:
            table = compute_crop_window_suitability_table(
                df_long, crop, stage, int(year), months, aggregation_method, perturbed
            )
            selected = table[table["CITY"].eq(city) & table["STATE"].eq(state)] if not table.empty else pd.DataFrame()
            if not selected.empty:
                score = float(selected.iloc[0]["Overall Suitability (%)"])
                scores.append(score)
                yearly_rows.append({"Run": run + 1, "Year": int(year), "Suitability (%)": score})
        if scores:
            simulation_rows.append({
                "Run": run + 1,
                "Mean Suitability (%)": float(np.mean(scores)),
                "Minimum Suitability (%)": float(np.min(scores)),
                "% Suitable Years (>=60)": float(np.mean(np.asarray(scores) >= 60) * 100.0),
                "Std Suitability (%)": float(np.std(scores, ddof=1)) if len(scores) > 1 else 0.0
            })
    simulations = pd.DataFrame(simulation_rows)
    yearly = pd.DataFrame(yearly_rows)
    return simulations, yearly


def compute_data_quality_dashboard(df_long: pd.DataFrame) -> dict:
    key_columns = ["CITY", "STATE", "Year", "Month", "Variable"]
    duplicates = df_long[df_long.duplicated(key_columns, keep=False)].sort_values(key_columns)
    years_count = df_long["Year"].nunique()
    expected_months = len(MONTHS_UPPER)
    location_variable = df_long.groupby(["CITY", "STATE", "Variable"]).agg(
        Records=("Value", "size"),
        Years=("Year", "nunique"),
        Months=("Month", "nunique"),
        Missing_Values=("Value", lambda values: int(values.isna().sum())),
        Unique_Values=("Value", "nunique"),
        Mean=("Value", "mean"),
        Std=("Value", "std")
    ).reset_index()
    expected_records = max(years_count * expected_months, 1)
    location_variable["Completeness (%)"] = np.clip(
        location_variable["Records"] / expected_records * 100.0, 0, 100
    )
    location_variable["Constant Series"] = location_variable["Unique_Values"] <= 1

    outlier_rows = []
    for keys, group in df_long.groupby(["CITY", "STATE", "Variable"]):
        values = group["Value"].dropna()
        if len(values) < 8:
            continue
        q1, q3 = values.quantile([0.25, 0.75])
        iqr = q3 - q1
        if not np.isfinite(iqr) or iqr <= 0:
            continue
        low, high = q1 - 3 * iqr, q3 + 3 * iqr
        flagged = group[(group["Value"] < low) | (group["Value"] > high)]
        for _, row in flagged.iterrows():
            outlier_rows.append({
                "CITY": keys[0], "STATE": keys[1], "Variable": keys[2],
                "Year": row["Year"], "Month": row["Month"], "Value": row["Value"],
                "Lower Extreme Fence": low, "Upper Extreme Fence": high
            })
    outliers = pd.DataFrame(outlier_rows)
    city_summary = location_variable.groupby(["CITY", "STATE"], as_index=False).agg(
        **{
            "Mean Completeness (%)": ("Completeness (%)", "mean"),
            "Minimum Variable Completeness (%)": ("Completeness (%)", "min"),
            "Variables Available": ("Variable", "nunique"),
            "Constant Series Count": ("Constant Series", "sum")
        }
    )
    return {
        "location_variable": location_variable,
        "city_summary": city_summary,
        "duplicates": duplicates,
        "outliers": outliers
    }


def benjamini_hochberg(p_values: pd.Series) -> pd.Series:
    p = pd.to_numeric(p_values, errors="coerce")
    valid = p.dropna()
    adjusted = pd.Series(np.nan, index=p.index, dtype=float)
    if valid.empty:
        return adjusted
    order = np.argsort(valid.to_numpy())
    sorted_p = valid.to_numpy()[order]
    n = len(sorted_p)
    raw_adjusted = sorted_p * n / np.arange(1, n + 1)
    monotonic = np.minimum.accumulate(raw_adjusted[::-1])[::-1]
    monotonic = np.clip(monotonic, 0, 1)
    valid_indices = valid.index.to_numpy()[order]
    adjusted.loc[valid_indices] = monotonic
    return adjusted


def compute_multiple_testing_corrected_trends(
    df_long: pd.DataFrame,
    variable: str,
    year_range: tuple[int, int],
    months: list[str],
    alpha: float
) -> pd.DataFrame:
    result = compute_trend_table(df_long, "Cities", variable, year_range, months, alpha)
    if result.empty:
        return result
    result["BH-adjusted p-value"] = benjamini_hochberg(result["Mann-Kendall p-value"])
    result["Raw Significant"] = result["Mann-Kendall p-value"] < alpha
    result["BH Significant"] = result["BH-adjusted p-value"] < alpha
    result["Significance Retained"] = result["Raw Significant"] & result["BH Significant"]
    return result.sort_values("BH-adjusted p-value").reset_index(drop=True)


def compare_similarity_methods(
    df_long: pd.DataFrame,
    city: str,
    state: str,
    year: int,
    weights: dict[str, float],
    top_n: int
) -> tuple[pd.DataFrame, pd.DataFrame]:
    wide, standardised, columns = prepare_similarity_matrix(df_long, year, weights)
    if wide is None or standardised is None:
        return pd.DataFrame(), pd.DataFrame()
    mask = wide["CITY"].eq(city) & wide["STATE"].eq(state)
    if not mask.any():
        return pd.DataFrame(), pd.DataFrame()
    ref_index = int(np.flatnonzero(mask.to_numpy())[0])
    matrix = standardised.to_numpy(dtype=float)
    ref = matrix[[ref_index]]
    cosine_scores = (cosine_similarity(ref, matrix)[0] + 1.0) / 2.0
    euclidean = pairwise_distances(ref, matrix, metric="euclidean")[0]
    euclidean_scores = 1.0 / (1.0 + euclidean)
    correlation_distance = pairwise_distances(ref, matrix, metric="correlation")[0]
    correlation_scores = 1.0 - np.nan_to_num(correlation_distance, nan=1.0)
    methods = {
        "Cosine": cosine_scores,
        "Euclidean similarity": euclidean_scores,
        "Correlation similarity": correlation_scores
    }
    rows = []
    ranking_sets = {}
    for method, scores in methods.items():
        frame = wide[["CITY", "STATE"]].copy()
        frame["Method"] = method
        frame["Score"] = scores
        frame = frame.sort_values("Score", ascending=False).reset_index(drop=True)
        frame["Rank"] = np.arange(1, len(frame) + 1)
        frame["Location"] = frame["CITY"] + " (" + frame["STATE"] + ")"
        rows.append(frame)
        ranking_sets[method] = set(frame.head(top_n)["Location"])
    rankings = pd.concat(rows, ignore_index=True)
    overlap_rows = []
    method_names = list(methods)
    for i, first in enumerate(method_names):
        for second in method_names[i + 1:]:
            intersection = len(ranking_sets[first].intersection(ranking_sets[second]))
            union = len(ranking_sets[first].union(ranking_sets[second]))
            overlap_rows.append({
                "Method 1": first,
                "Method 2": second,
                f"Top-{top_n} overlap": intersection,
                "Jaccard overlap": intersection / union if union else np.nan
            })
    return rankings, pd.DataFrame(overlap_rows)


def compare_crop_aggregation_models(
    df_long: pd.DataFrame,
    crop: str,
    stage: str,
    year: int,
    months: list[str]
) -> tuple[pd.DataFrame, pd.DataFrame]:
    strict = compute_crop_window_suitability_table(
        df_long, crop, stage, year, months, "Limiting factor", CROP_STAGE_THRESHOLDS[crop][stage]
    )
    mean_model = compute_crop_window_suitability_table(
        df_long, crop, stage, year, months, "Mean of components", CROP_STAGE_THRESHOLDS[crop][stage]
    )
    if strict.empty or mean_model.empty:
        return pd.DataFrame(), pd.DataFrame()
    strict = strict[["CITY", "STATE", "Location", "Overall Suitability (%)"]].rename(
        columns={"Overall Suitability (%)": "Limiting-factor Score"}
    )
    mean_model = mean_model[["CITY", "STATE", "Overall Suitability (%)"]].rename(
        columns={"Overall Suitability (%)": "Mean-component Score"}
    )
    comparison = strict.merge(mean_model, on=["CITY", "STATE"], how="inner")
    comparison["Difference"] = comparison["Mean-component Score"] - comparison["Limiting-factor Score"]
    comparison["Limiting-factor Rank"] = comparison["Limiting-factor Score"].rank(ascending=False, method="min")
    comparison["Mean-component Rank"] = comparison["Mean-component Score"].rank(ascending=False, method="min")
    comparison["Rank Difference"] = comparison["Mean-component Rank"] - comparison["Limiting-factor Rank"]
    summary = pd.DataFrame([{
        "Locations": len(comparison),
        "Score Correlation": comparison[["Limiting-factor Score", "Mean-component Score"]].corr().iloc[0, 1],
        "Mean Absolute Score Difference": comparison["Difference"].abs().mean(),
        "Mean Absolute Rank Difference": comparison["Rank Difference"].abs().mean(),
        "Maximum Rank Difference": comparison["Rank Difference"].abs().max()
    }])
    return comparison.sort_values("Rank Difference", key=lambda values: values.abs(), ascending=False), summary


def sha256_file(path: Path) -> str:
    if not path.exists():
        return "Missing"
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def package_version(package_name: str) -> str:
    try:
        from importlib.metadata import version
        return version(package_name)
    except Exception:
        return "Unknown"


def build_reproducibility_metadata(extra_parameters: dict | None = None) -> dict:
    metadata = {
        "app_version": APP_VERSION,
        "generated_utc": datetime.now(timezone.utc).isoformat(),
        "python_version": sys.version,
        "platform": platform.platform(),
        "datasets": {
            "cities_file": str(cities_file),
            "cities_sha256": sha256_file(cities_file),
            "climate_file": str(climate_file),
            "climate_sha256": sha256_file(climate_file),
            "climate_modified_utc": (
                datetime.fromtimestamp(climate_file.stat().st_mtime, timezone.utc).isoformat()
                if climate_file.exists() else None
            )
        },
        "data_coverage": {
            "minimum_year": int(min(years)),
            "maximum_year": int(max(years)),
            "matched_locations": int(merged_df_long[["CITY", "STATE"]].drop_duplicates().shape[0]),
            "variables": available_variables
        },
        "packages": {
            name: package_version(name)
            for name in ["streamlit", "pandas", "numpy", "scipy", "statsmodels", "scikit-learn", "plotly", "folium"]
        },
        "parameters": extra_parameters or {}
    }
    return metadata


def dataframe_to_html_section(title: str, frame: pd.DataFrame | None, max_rows: int = 100) -> str:
    if frame is None or frame.empty:
        return f"<h2>{title}</h2><p>No results available.</p>"
    return f"<h2>{title}</h2>" + frame.head(max_rows).to_html(index=False, border=0)


def rule_based_interpretation(name: str, result) -> str:
    if result is None or not isinstance(result, pd.DataFrame) or result.empty:
        return f"No {name} results are currently available."
    if name == "Climate similarity" and "Similarity Score" in result.columns:
        alternative = result.iloc[1] if len(result) > 1 else result.iloc[0]
        return (
            f"The closest alternative climate was {alternative.get('CITY')} ({alternative.get('STATE')}) "
            f"with a similarity score of {alternative['Similarity Score']:.3f}. Review variable contributions "
            "before treating this location as agronomically interchangeable."
        )
    if name == "Crop suitability" and "Overall Suitability (%)" in result.columns:
        best = result.iloc[0]
        suitable = int((result["Overall Suitability (%)"] >= 60).sum())
        return (
            f"{best.get('Location')} ranked highest at {best['Overall Suitability (%)']:.1f}% suitability. "
            f"{suitable} locations met the 60% suitability threshold; the most common limiting factor was "
            f"{result['Limiting Factor'].mode().iloc[0] if 'Limiting Factor' in result and not result['Limiting Factor'].mode().empty else 'not identified'}."
        )
    if name == "Crop stability" and "Reliability Score" in result.columns:
        best = result.iloc[0]
        return (
            f"{best.get('Location')} had the highest long-term reliability ({best['Reliability Score']:.1f}). "
            f"Its minimum suitability was {best.get('Minimum Suitability (%)', np.nan):.1f}%, which should be "
            "considered alongside the average when evaluating climate resilience."
        )
    if name == "Water stress" and "Water Stress Score" in result.columns:
        highest = result.iloc[0]
        return (
            f"{highest.get('Location')} showed the greatest climatic water stress ({highest['Water Stress Score']:.1f}). "
            "This indicator compares precipitation with atmospheric demand and does not include irrigation or stored soil moisture."
        )
    if name == "Trend analysis" and "Trend" in result.columns:
        significant = int((result.get("Mann-Kendall p-value", pd.Series(dtype=float)) < 0.05).sum())
        return f"{significant} locations showed nominally significant monotonic trends at p < .05. Use false-discovery correction before interpreting many simultaneous tests."
    if name == "Composite risk" and "Composite Risk Score" in result.columns:
        highest = result.iloc[0]
        return (
            f"{highest.get('Location')} had the highest composite risk score ({highest['Composite Risk Score']:.1f}). "
            "Because the score is weight-dependent, inspect every component and rerun sensitivity checks before decision use."
        )
    return f"The current {name} result contains {len(result):,} rows. Inspect the headline metrics, uncertainty, and methodology before drawing conclusions."


def build_complete_html_report(selected_results: dict[str, pd.DataFrame], title: str, notes: str) -> bytes:
    metadata = build_reproducibility_metadata({"report_title": title, "notes": notes})
    sections = [
        "<!doctype html><html><head><meta charset='utf-8'>",
        "<style>body{font-family:Arial,sans-serif;margin:36px;color:#1f2a24;}table{border-collapse:collapse;width:100%;font-size:12px;}th,td{border:1px solid #ddd;padding:5px;}th{background:#eaf0ec;}h1,h2{color:#2f6b4f;}pre{white-space:pre-wrap;background:#f4f6f4;padding:12px;}</style>",
        f"</head><body><h1>{title}</h1><p>{notes}</p>",
        "<h2>Automated interpretation</h2>"
    ]
    for name, frame in selected_results.items():
        sections.append(f"<h3>{name}</h3><p>{rule_based_interpretation(name, frame)}</p>")
    for name, frame in selected_results.items():
        sections.append(dataframe_to_html_section(name, frame))
    sections.append("<h2>Reproducibility metadata</h2><pre>")
    sections.append(json.dumps(metadata, indent=2, ensure_ascii=False))
    sections.append("</pre><p><i>Climate-screening outputs should be validated against local soils, management, irrigation, and observed production data.</i></p></body></html>")
    return "".join(sections).encode("utf-8")


