def safe_session_parameters() -> dict:
    parameters = {}
    for key, value in st.session_state.items():
        if key.endswith("_params") or key.endswith("_year_range") or key.endswith("_period"):
            try:
                json.dumps(value)
                parameters[key] = value
            except TypeError:
                parameters[key] = str(value)
    return parameters


def save_analysis_preset(name: str, description: str) -> tuple[bool, str]:
    presets = load_json_file(presets_file, {})
    presets[name] = {
        "description": description,
        "saved_utc": datetime.now(timezone.utc).isoformat(),
        "parameters": safe_session_parameters()
    }
    return save_json_file(presets_file, presets)


def apply_analysis_preset(name: str) -> tuple[bool, str]:
    presets = load_json_file(presets_file, {})
    if name not in presets:
        return False, "Preset not found."
    applied = 0
    for key, value in presets[name].get("parameters", {}).items():
        try:
            st.session_state[key] = value
            applied += 1
        except Exception:
            continue
    return True, f"Applied {applied} saved parameter values."


def record_analysis_event(name: str, result: pd.DataFrame, parameters=None) -> None:
    if result is None or not isinstance(result, pd.DataFrame) or result.empty:
        return
    sample_hash = int(pd.util.hash_pandas_object(result.head(100), index=True).sum())
    signature = f"{result.shape}-{sample_hash}"
    if st.session_state.history_signatures.get(name) == signature:
        return
    st.session_state.history_signatures[name] = signature
    event = {
        "analysis": name,
        "timestamp_utc": datetime.now(timezone.utc).isoformat(),
        "rows": int(len(result)),
        "columns": int(len(result.columns)),
        "parameters": str(parameters)[:1000]
    }
    st.session_state.analysis_history.append(event)
    existing = load_json_file(history_file, [])
    existing.append(event)
    save_json_file(history_file, existing[-500:])


def sync_analysis_history() -> None:
    mapping = {
        "Climate similarity": ("similarity_results", "similarity_params"),
        "Crop suitability": ("crop_window_results", "crop_window_params"),
        "Yield screening": ("yield_results", "yield_params"),
        "Climate analogues": ("analogue_results", "analogue_params"),
        "Trend analysis": ("trend_results", "trend_params"),
        "Climate anomalies": ("anomaly_results", "anomaly_params"),
        "Water stress": ("water_stress_results", "water_stress_params"),
        "Crop stability": ("crop_stability_results", "crop_stability_params"),
        "Composite risk": ("composite_risk_results", None),
        "Climate migration": ("migration_results", None),
        "State summary": ("state_summary_results", None),
        "Planting optimiser": ("planting_optimizer_results", None),
        "Irrigation": ("irrigation_results", None),
        "Root-zone soil-water balance": ("soil_water_balance_results", "soil_water_metadata"),
        "Historical root-zone risk": ("soil_water_historical_results", "soil_water_historical_metadata"),
        "Root-zone scenario comparison": ("soil_water_scenario_results", "soil_water_scenario_metadata"),
        "Stage vulnerability": ("vulnerability_results", None),
        "Crop portfolio": ("portfolio_results", None),
        "Crop substitution": ("substitution_results", None),
        "Extreme events": ("extreme_event_results", None),
        "Climate variability": ("variability_results", None),
        "Drought indices": ("drought_index_results", None),
        "Future scenarios": ("future_scenario_results", None),
        "Uncertainty": ("uncertainty_results", None),
        "Multiple testing": ("multiple_testing_results", None),
        "Model comparison": ("model_comparison_results", None),
        "Batch analysis": ("batch_results", None)
    }
    for name, (result_key, parameter_key) in mapping.items():
        result = st.session_state.get(result_key)
        params = st.session_state.get(parameter_key) if parameter_key else None
        if isinstance(result, pd.DataFrame) and not result.empty:
            record_analysis_event(name, result, params)


def process_batch_analysis(frame: pd.DataFrame) -> pd.DataFrame:
    def _batch_int(value, default):
        numeric = pd.to_numeric(value, errors="coerce")
        return int(default) if pd.isna(numeric) else int(numeric)

    required = {"Task"}
    if not required.issubset(frame.columns):
        raise ValueError("Batch file must include a Task column.")
    rows = []
    locations = location_options(merged_df_long)
    for index, request in frame.iterrows():
        task = str(request.get("Task", "")).strip().casefold()
        city = str(request.get("CITY", "")).strip()
        state = str(request.get("STATE", "")).strip()
        year = _batch_int(request.get("Year", max(years)), max(years))
        try:
            if task == "similarity":
                result, _ = compute_similarity(city, state, merged_df_long, similarity_weight_profile("General"), year, False, False)
                if result is None or result.empty:
                    raise ValueError("No similarity result")
                alternative = result[~(result["CITY"].eq(city) & result["STATE"].eq(state))].iloc[0]
                rows.append({"Row": index + 1, "Task": task, "Status": "Complete", "Result": f"{alternative['CITY']} ({alternative['STATE']})", "Value": alternative["Similarity Score"]})
            elif task == "crop_suitability":
                crop = str(request.get("Crop", "Maize"))
                stage = str(request.get("Stage", choose_full_season_stage(crop)))
                result = compute_crop_window_suitability_table(
                    merged_df_long, crop, stage, year, CROP_SEASONAL_WINDOWS[crop][stage], "Limiting factor", CROP_STAGE_THRESHOLDS[crop][stage]
                )
                selected = result[result["CITY"].eq(city) & result["STATE"].eq(state)]
                if selected.empty:
                    raise ValueError("Location not found")
                rows.append({"Row": index + 1, "Task": task, "Status": "Complete", "Result": selected.iloc[0]["Suitability Class"], "Value": selected.iloc[0]["Overall Suitability (%)"]})
            elif task == "water_stress":
                start_year = _batch_int(request.get("Start Year", min(years)), min(years))
                end_year = _batch_int(request.get("End Year", max(years)), max(years))
                result = compute_water_stress_table(merged_df_long, "Cities", (start_year, end_year), MONTHS)
                selected = result[result["CITY"].eq(city) & result["STATE"].eq(state)]
                if selected.empty:
                    raise ValueError("Location not found")
                rows.append({"Row": index + 1, "Task": task, "Status": "Complete", "Result": selected.iloc[0]["Water Stress Class"], "Value": selected.iloc[0]["Water Stress Score"]})
            elif task == "trend":
                variable = str(request.get("Variable", "TEMPERATURE")).upper()
                start_year = _batch_int(request.get("Start Year", min(years)), min(years))
                end_year = _batch_int(request.get("End Year", max(years)), max(years))
                result = compute_trend_table(merged_df_long, "Cities", variable, (start_year, end_year), MONTHS, 0.05)
                selected = result[result["CITY"].eq(city) & result["STATE"].eq(state)]
                if selected.empty:
                    raise ValueError("Location not found")
                rows.append({"Row": index + 1, "Task": task, "Status": "Complete", "Result": selected.iloc[0]["Trend"], "Value": selected.iloc[0]["Sen's Slope per Year"]})
            else:
                raise ValueError("Unsupported Task. Use similarity, crop_suitability, water_stress, or trend.")
        except Exception as exc:
            rows.append({"Row": index + 1, "Task": task, "Status": "Error", "Result": str(exc), "Value": np.nan})
    return pd.DataFrame(rows)


