    stability_yearly = st.session_state.get(
        "crop_stability_yearly"
    )

    if stability_results is None:
        empty_state("No crop-stability results yet.", "Choose a crop window and multi-year period, then compute stability.")

    methods_panel(
        "Stability summarises yearly crop-window suitability across the selected period.",
        [
            "Reliability rewards high mean and minimum suitability and a large percentage of suitable years.",
            "Variability and recurring limiting factors reveal locations that perform well only under favourable years.",
            "Inspect the year-by-year series before using a summary rank for planning or research conclusions."
        ]
    )

    if stability_results is not None:
        top_stability_row = stability_results.iloc[0]
        stable_count = int(stability_results["Stability Class"].isin(["Highly stable and suitable", "Stable suitable"]).sum())
        stability_metrics = st.columns(4)
        stability_metrics[0].metric("Most reliable location", top_stability_row["Location"])
        stability_metrics[1].metric("Top reliability", f"{top_stability_row['Reliability Score']:.1f}")
        stability_metrics[2].metric("Stable suitable locations", f"{stable_count:,}")
