        metrics[0].metric("Best location", best["Location"])
        metrics[1].metric("Best suitability", f"{best['Overall Suitability (%)']:.1f}%")
        metrics[2].metric("Suitable locations", f"{int((result['Overall Suitability (%)'] >= 60).sum()):,}")
        metrics[3].metric("Common limiting factor", result["Limiting Factor"].mode().iloc[0] if not result["Limiting Factor"].mode().empty else "Unknown")
        display_columns = [
            "Location", "Crop", "Seasonal Window", "Year", "Months Included", "Mean Temperature (°C)",
            "Annual Precipitation Total (mm)", "Seasonal Precipitation Total (mm)", "Seasonal ETo Total (mm)",
            "Crop Coefficient Kc", "Crop ETc Total (mm)", "Effective Precipitation (mm)", "Water Adequacy ETa / ETm",
            "Yield Response Factor Ky", "Relative Water-Limited Yield (%)", "Temperature Suitability (%)",
            "Precipitation Suitability (%)", "Water Adequacy Suitability (%)", "Overall Suitability (%)",
            "Suitability Class", "Limiting Factor", "Parameter Evidence Grade", "Parameter Source IDs",
        ]
        display_columns = [column for column in display_columns if column in result.columns]
        st.dataframe(
            result[display_columns], hide_index=True, width="stretch",
            column_config={
                "Overall Suitability (%)": st.column_config.ProgressColumn(min_value=0.0, max_value=100.0, format="%.1f%%"),
                "Temperature Suitability (%)": st.column_config.NumberColumn(format="%.1f%%"),
                "Precipitation Suitability (%)": st.column_config.NumberColumn(format="%.1f%%"),
                "Water Adequacy Suitability (%)": st.column_config.NumberColumn(format="%.1f%%"),
            },
        )
        st.download_button("Download results CSV", result.to_csv(index=False).encode("utf-8"), file_name=f"validated_crop_suitability_{crop}_{stage}_{year}.csv".replace(" ", "_").replace("/", "_"), mime="text/csv", key="download_crop_window_v5")

