            selected_result = selected.iloc[0]
            st.markdown(
                f"**{selected_location}:** overall suitability **{selected_result['Overall Suitability (%)']:.1f}%**; "
                f"limiting factor **{selected_result['Limiting Factor']}**; Kc **{format_number(selected_result.get('Crop Coefficient Kc'))}**; "
                f"ETc **{format_number(selected_result.get('Crop ETc Total (mm)'))} mm**."
            )

