def _satellite_parse_geojson_upload(uploaded_file) -> dict:
    try:
        payload = json.loads(uploaded_file.getvalue().decode("utf-8-sig"))
        return validate_aoi_geometry(payload)
    except Exception as error:
        raise SatelliteMonitoringError(f"Could not read the uploaded GeoJSON: {error}") from error


def _satellite_current_schedule() -> pd.DataFrame | None:
    candidates = [
        st.session_state.get("phenology_schedule"),
        st.session_state.get("soil_water_schedule"),
    ]
    for candidate in candidates:
        if isinstance(candidate, pd.DataFrame) and not candidate.empty:
            return candidate.copy()
    return None


def _satellite_add_stage_bands(figure: go.Figure, schedule: pd.DataFrame | None) -> None:
    if schedule is None or schedule.empty:
        return
    stage_column = next((column for column in ["Stage", "Crop stage"] if column in schedule.columns), None)
    start_column = next((column for column in ["Start date", "Start", "Stage start"] if column in schedule.columns), None)
    end_column = next((column for column in ["End date", "End", "Stage end"] if column in schedule.columns), None)
    if not all([stage_column, start_column, end_column]):
        return
    for index, row in schedule.iterrows():
        start = pd.to_datetime(row[start_column], errors="coerce")
        end = pd.to_datetime(row[end_column], errors="coerce")
        if pd.isna(start) or pd.isna(end):
            continue
        figure.add_vrect(
            x0=start,
            x1=end,
            opacity=0.07 if index % 2 == 0 else 0.12,
            line_width=0,
            annotation_text=str(row[stage_column]),
            annotation_position="top left",
        )


def _satellite_safe_map_centre(geometry: dict | None) -> tuple[float, float]:
    """Return a valid map centre without allowing stale geometry to suppress rendering."""
    if geometry is not None:
        try:
            latitude, longitude = geometry_centroid(validate_aoi_geometry(geometry))
            latitude, longitude = float(latitude), float(longitude)
            if np.isfinite(latitude) and np.isfinite(longitude) and -90 <= latitude <= 90 and -180 <= longitude <= 180:
                return latitude, longitude
        except Exception:
            pass
    latitude, longitude = ACTIVE_COUNTRY_MAP_CENTRE
    return float(latitude), float(longitude)


def _satellite_aoi_selector(locations: pd.DataFrame) -> tuple[dict | None, dict]:
    st.markdown("### Analysis area")
    area_sources = ["Use current session field", "App city buffer", "Custom point buffer", "Upload GeoJSON field", "Choose or draw on map"]
    if st.session_state.get("satellite_aoi_mode") == "Draw field on map":
        st.session_state["satellite_aoi_mode"] = "Choose or draw on map"
    has_session_field = st.session_state.get("satellite_aoi_geometry") is not None
    mode = st.radio(
        "Area source",
        area_sources,
        index=0 if has_session_field else 1,
        horizontal=True,
        key="satellite_aoi_mode",
    )
    metadata: dict[str, object] = {"Area source": mode}
    geometry = None

    if mode == "Use current session field":
        geometry = st.session_state.get("satellite_aoi_geometry")
        if geometry is None:
            st.warning("No field geometry is currently stored in this session.")
        else:
            metadata.update(st.session_state.get("satellite_aoi_metadata") or {})
            metadata["Area source"] = "Current session field"
            if st.session_state.get("pollination_satellite_target"):
                target = st.session_state.get("pollination_satellite_target") or {}
                st.info(
                    "Using the mapped Maize Flowering Synchrony Lab target: "
                    + ", ".join(target.get("plot_labels", []))
                )
    elif mode == "App city buffer":
        selected_label = st.selectbox(
            "City",
            locations["Location"].tolist(),
            index=_module_a_default_location_index(locations),
            key="satellite_city",
        )
        selected = locations.loc[locations["Location"].eq(selected_label)].iloc[0]
        radius = float(st.slider("Buffer radius (m)", 100, 5000, 500, 100, key="satellite_city_radius"))
        geometry = geometry_from_point_buffer(float(selected["lat"]), float(selected["lng"]), radius)
        metadata.update({
            "Location": selected_label,
            "Latitude": float(selected["lat"]),
            "Longitude": float(selected["lng"]),
            "Buffer radius (m)": radius,
        })
    elif mode == "Custom point buffer":
        columns = st.columns(3)
        latitude = float(columns[0].number_input("Latitude", -90.0, 90.0, float(ACTIVE_COUNTRY_MAP_CENTRE[0]), 0.0001, key="satellite_lat"))
        longitude = float(columns[1].number_input("Longitude", -180.0, 180.0, float(ACTIVE_COUNTRY_MAP_CENTRE[1]), 0.0001, key="satellite_lon"))
        radius = float(columns[2].number_input("Buffer radius (m)", 50.0, 10000.0, 500.0, 50.0, key="satellite_custom_radius"))
        geometry = geometry_from_point_buffer(latitude, longitude, radius)
        metadata.update({"Location": "Custom point", "Latitude": latitude, "Longitude": longitude, "Buffer radius (m)": radius})
    elif mode == "Upload GeoJSON field":
        upload = st.file_uploader(
            "Upload a Polygon or MultiPolygon GeoJSON",
            type=["geojson", "json"],
            key="satellite_geojson_upload",
        )
        if upload is not None:
            geometry = _satellite_parse_geojson_upload(upload)
            metadata["Uploaded file"] = upload.name
        elif st.session_state.get("satellite_aoi_geometry") is not None:
            geometry = st.session_state.satellite_aoi_geometry
            st.info("Using the field geometry already stored in this session.")
    else:
        # Always render the interactive drawing map. Existing geometry is only an
        # optional overlay and starting point; it never bypasses the map component.
        existing = st.session_state.get("satellite_aoi_geometry")
        centre_lat, centre_lon = _satellite_safe_map_centre(existing)
        st.session_state.setdefault("satellite_draw_map_revision", 0)
        map_controls = st.columns([1, 1, 2])
        if map_controls[0].button("Reload drawing map", key="satellite_reload_draw_map", width="stretch"):
            st.session_state["satellite_draw_map_revision"] += 1
            st.rerun()
        if map_controls[1].button("Clear current AOI", key="satellite_clear_draw_aoi", width="stretch"):
            st.session_state.pop("satellite_aoi_geometry", None)
            st.session_state.pop("satellite_aoi_metadata", None)
            st.session_state["satellite_draw_map_revision"] += 1
            st.rerun()
        map_controls[2].caption(f"Map starts at {centre_lat:.5f}, {centre_lon:.5f}. A saved centroid is used only to centre the view.")

        with st.container(border=True):
            st.markdown("#### Choose the field on the map")
            st.caption("The map below is always shown in this mode. Search for a place, switch the base layer, then draw a polygon or rectangle. If a stale component ever appears blank, use Reload drawing map.")
            draw_map = folium.Map(location=[centre_lat, centre_lon], zoom_start=14, tiles=None, control_scale=True)
            folium.TileLayer("OpenStreetMap", name="Roads & places", overlay=False, control=True, show=False).add_to(draw_map)
            folium.TileLayer("CartoDB positron", name="Light map", overlay=False, control=True, show=False).add_to(draw_map)
            folium.TileLayer("Esri.WorldImagery", name="Satellite imagery", attr="Esri, Maxar, Earthstar Geographics, and the GIS User Community", overlay=False, control=True, show=True).add_to(draw_map)
            Fullscreen().add_to(draw_map)
            MeasureControl(
                position="topleft", primary_length_unit="meters", secondary_length_unit="kilometers",
                primary_area_unit="sqmeters", secondary_area_unit="hectares",
                active_color="#dc2626", completed_color="#2563eb",
            ).add_to(draw_map)
            Draw(
                export=False,
                draw_options={
                    "polyline": {"metric": True, "feet": False, "showLength": True},
                    "rectangle": {"metric": True, "feet": False, "showArea": True},
                    "polygon": {"allowIntersection": False, "metric": True, "feet": False, "showArea": True, "showLength": True},
                    "circle": False,
                    "circlemarker": False,
                    "marker": False,
                },
                edit_options={"edit": True, "remove": True},
            ).add_to(draw_map)
            _add_live_draw_distance(draw_map)
            if existing is not None:
                try:
                    folium.GeoJson(existing, name="Current field", style_function=lambda _: {"color": "#111827", "weight": 3, "fillOpacity": 0.08}).add_to(draw_map)
                except Exception:
                    st.warning("The previously stored AOI could not be drawn, so the map opened at the country default. Draw a new field boundary.")
            folium.LayerControl(collapsed=False, position="topright").add_to(draw_map)
            revision = int(st.session_state.get("satellite_draw_map_revision", 0))
            try:
                draw_result = st_folium(
                    draw_map,
                    height=560,
                    use_container_width=True,
                    key=f"satellite_draw_field_map_{revision}",
                    returned_objects=["all_drawings", "last_active_drawing", "bounds", "center", "zoom"],
                )
            except Exception as error:
                st.error(f"The interactive map component could not render: {type(error).__name__}: {error}")
                st.info("Press Reload drawing map. If the problem continues, run INSTALL_DEPENDENCIES.bat to refresh streamlit-folium and Folium.")
                draw_result = {}

        drawings = (draw_result or {}).get("all_drawings") or []
        last_drawing = (draw_result or {}).get("last_active_drawing")
        candidate = last_drawing or (drawings[-1] if drawings else None)
        if candidate and candidate.get("geometry"):
            geometry = validate_aoi_geometry(candidate)
            st.session_state.satellite_aoi_geometry = geometry
            st.success("The last drawn polygon is now the active field area.")
        elif existing is not None:
            geometry = validate_aoi_geometry(existing)
            st.info("The current AOI remains active until you finish a new drawing or press Clear current AOI.")
        else:
            st.info("Draw a polygon or rectangle on the visible map. The last drawing becomes the active area.")

    if geometry is not None:
        geometry = validate_aoi_geometry(geometry)
        area_ha = geometry_area_hectares(geometry)
        centre_lat, centre_lon = geometry_centroid(geometry)
        metadata.update({"Area (ha)": area_ha, "Centroid latitude": centre_lat, "Centroid longitude": centre_lon})
        st.session_state.satellite_aoi_geometry = geometry
        st.session_state.satellite_aoi_metadata = metadata
        metric_columns = st.columns(3)
        metric_columns[0].metric("Area", f"{area_ha:,.2f} ha")
        metric_columns[1].metric("Centroid", f"{centre_lat:.4f}, {centre_lon:.4f}")
        metric_columns[2].metric("Spatial source", mode)
        if area_ha < 0.5:
            st.warning("This area is smaller than roughly five 10-m Sentinel-2 pixels. Field statistics may be unstable.")
        if area_ha > 5000:
            st.warning("This is a large area. Use 20–60 m analysis resolution and a limited scene count to control processing time.")
        st.download_button(
            "Download active field GeoJSON",
            geometry_geojson_bytes(geometry, metadata),
            file_name="satellite_field_aoi.geojson",
            mime="application/geo+json",
            key="download_satellite_aoi",
            width="stretch",
        )
    return geometry, metadata


def _satellite_time_series_figure(time_series: pd.DataFrame, indices: list[str]) -> go.Figure:
    usable = time_series.loc[time_series["Status"].eq("Usable")].copy()
    mean_columns = [f"{name} Mean" for name in indices if f"{name} Mean" in usable.columns]
    if not mean_columns:
        return go.Figure()
    long = usable.melt(
        id_vars=[column for column in ["Date", "Field usable pixels (%)", "Scene cloud (%)", "Scene ID"] if column in usable],
        value_vars=mean_columns,
        var_name="Index",
        value_name="Field mean",
    )
    long["Index"] = long["Index"].str.replace(" Mean", "", regex=False)
    figure = px.line(
        long,
        x="Date",
        y="Field mean",
        color="Index",
        markers=True,
        hover_data=[column for column in ["Field usable pixels (%)", "Scene cloud (%)", "Scene ID"] if column in long],
        title="Satellite vegetation-index time series",
    )
    figure.update_yaxes(range=[-1, 1.25])
    _satellite_add_stage_bands(figure, _satellite_current_schedule())
    return figure


def page_satellite_crop_monitoring() -> None:
    page_header(
        "Earth Observation · Sentinel-2",
        "Field satellite monitoring",
        "Retrieve Sentinel-2 Level-2A imagery for a mapped field or custom analysis area, apply pixel-level cloud masking, quantify vegetation and canopy-moisture indices, compare seasons, and evaluate agreement with crop development and root-zone evidence.",
    )

    dependencies = satellite_dependency_status()
    missing = [name for name, available in dependencies.items() if not available]
    if missing:
        st.error(
            "Satellite monitoring cannot start because these packages are missing: "
            + ", ".join(missing)
            + ". Run INSTALL_DEPENDENCIES.bat and restart the app."
        )
        return

    st.info(
        "Sentinel-2 vegetation indices describe optical canopy and surface conditions inside the selected area. "
        "They are not direct yield measurements, crop diagnoses, or proof that a modelled climate stress caused an observed vegetation response."
    )

    locations = _module_a_location_table()
    if locations.empty:
        st.error(f"No georeferenced locations are available for {selected_country}.")
        return

    with st.expander("Field or analysis area", expanded=True):
        geometry, aoi_metadata = _satellite_aoi_selector(locations)
        field_columns = st.columns(3)
        with field_columns[0]:
            field_name = st.text_input("Field or analysis-area name", value=str(aoi_metadata.get("Location", "Satellite analysis area")), key="satellite_field_name")
        with field_columns[1]:
            crop_options = ["Unspecified"] + sorted(VALIDATED_CROP_LIBRARY.get("crops", {}))
            crop = st.selectbox("Crop", crop_options, key="satellite_crop")
        with field_columns[2]:
            planting_date = st.date_input("Planting or season start", value=date(date.today().year, 5, 1), key="satellite_planting_date")

    if geometry is None:
        st.warning("Select, upload, or draw an analysis area before searching for imagery.")
        return

    search_tab, image_tab, anomaly_tab, integration_tab, methods_tab = st.tabs(
        ["Field status & time series", "Imagery", "Seasonal anomalies", "Phenology & stress", "Advanced methods"]
    )

    with search_tab:
        st.markdown("### Search Sentinel-2 Level-2A imagery")
        search_columns = st.columns(5)
        today = date.today()
        with search_columns[0]:
            start_date = st.date_input("Search start", value=date(max(2017, today.year - 2), 1, 1), min_value=date(2015, 6, 23), max_value=today, key="satellite_search_start")
        with search_columns[1]:
            end_date = st.date_input("Search end", value=today, min_value=date(2015, 6, 23), max_value=today, key="satellite_search_end")
        with search_columns[2]:
            maximum_cloud = float(st.slider("Maximum scene cloud (%)", 0, 100, 50, 5, key="satellite_max_scene_cloud"))
        with search_columns[3]:
            maximum_items = int(st.number_input("Maximum catalogue items", 10, 1000, 300, 10, key="satellite_max_catalogue_items"))
        with search_columns[4]:
            provider_preference = st.selectbox(
                "Catalogue provider",
                ["Automatic failover", "Earth Search", "Planetary Computer"],
                index=0,
                help=(
                    "Automatic tries Earth Search first and switches to Planetary "
                    "Computer when Earth Search is unavailable."
                ),
                key="satellite_catalogue_provider",
            )

        if st.button("Search Sentinel-2 catalogue", type="primary", width="stretch", key="satellite_search_button"):
            if start_date > end_date:
                st.error("Search start must not be after search end.")
            else:
                with st.status("Searching Sentinel-2 STAC catalogues...", expanded=True) as status:
                    try:
                        config = SatelliteSearchConfig(
                            start_date=str(start_date),
                            end_date=str(end_date),
                            maximum_scene_cloud_percent=maximum_cloud,
                            maximum_items=maximum_items,
                            provider_preference=provider_preference,
                        )
                        items = search_sentinel2_scenes(geometry, config)
                        catalogue = scene_catalog_table(items)
                        providers_used = sorted(
                            {
                                scene_provider(item)
                                for item in items
                                if scene_provider(item) != "Unknown"
                            }
                        )
                        provider_label = ", ".join(providers_used) or "Unknown"
                        st.session_state.satellite_scene_items = items
                        st.session_state.satellite_scene_catalog = catalogue
                        st.session_state.satellite_search_config = {
                            "Start date": str(start_date),
                            "End date": str(end_date),
                            "Maximum scene cloud (%)": maximum_cloud,
                            "Maximum items": maximum_items,
                            "Provider preference": provider_preference,
                            "Provider used": provider_label,
                            "Catalogue URLs": {
                                name: details["catalog"]
                                for name, details in STAC_PROVIDERS.items()
                            },
                        }
                        st.session_state.satellite_preview = None
                        status.update(
                            label=(
                                f"Found {len(items):,} unique Sentinel-2 acquisitions "
                                f"using {provider_label}"
                            ),
                            state="complete",
                            expanded=False,
                        )
                        if (
                            provider_preference == "Automatic failover"
                            and "Planetary Computer" in providers_used
                        ):
                            st.info(
                                "Earth Search was unavailable, so the search completed "
                                "through Microsoft Planetary Computer."
                            )
                    except Exception as error:
                        status.update(label="Satellite catalogue search failed", state="error", expanded=True)
                        st.error(f"{type(error).__name__}: {error}")

        catalogue = st.session_state.get("satellite_scene_catalog")
        items = st.session_state.get("satellite_scene_items")
        if isinstance(catalogue, pd.DataFrame) and not catalogue.empty and isinstance(items, list):
            metrics = st.columns(5)
            metrics[0].metric("Catalogue scenes", f"{len(catalogue):,}")
            metrics[1].metric("First acquisition", str(pd.to_datetime(catalogue["Date"]).min().date()))
            metrics[2].metric("Last acquisition", str(pd.to_datetime(catalogue["Date"]).max().date()))
            metrics[3].metric("Median scene cloud", f"{pd.to_numeric(catalogue['Scene cloud (%)'], errors='coerce').median():.1f}%")
            provider_values = (
                ", ".join(sorted(catalogue["Provider"].dropna().astype(str).unique()))
                if "Provider" in catalogue.columns
                else "Unknown"
            )
            metrics[4].metric("Provider", provider_values)
            with st.expander("Scene catalogue", expanded=False):
                st.dataframe(catalogue, hide_index=True, width="stretch")
                st.download_button(
                    "Download scene catalogue",
                    catalogue.to_csv(index=False).encode("utf-8"),
                    file_name="sentinel2_scene_catalog.csv",
                    mime="text/csv",
                    key="download_satellite_catalogue",
                )

            st.markdown("### Process field-level satellite indicators")
            processing_columns = st.columns(5)
            with processing_columns[0]:
                selected_indices = st.multiselect("Indices", list(SATELLITE_INDEX_REGISTRY), default=["NDVI", "EVI", "NDMI", "NDRE"], key="satellite_indices")
            with processing_columns[1]:
                scene_method = st.selectbox(
                    "Scene-selection rule",
                    ["Lowest-cloud scene per month", "Evenly sample maximum N", "Lowest-cloud maximum N", "All search results"],
                    key="satellite_scene_selection_method",
                )
            with processing_columns[2]:
                max_scenes = int(st.number_input("Maximum scenes to process", 1, 300, 36, 1, key="satellite_max_process_scenes"))
            with processing_columns[3]:
                resolution = float(st.selectbox("Analysis resolution", [10, 20, 30, 60], index=1, key="satellite_resolution"))
            with processing_columns[4]:
                minimum_usable = float(st.slider("Minimum clear field pixels (%)", 1, 100, 30, 1, key="satellite_min_usable"))

            with st.expander("Advanced pixel-quality settings"):
                include_water = st.checkbox("Include SCL water pixels", value=False, key="satellite_include_water")
                force_refresh = st.checkbox("Ignore processed-scene cache", value=False, key="satellite_force_refresh")
                maximum_pixels = int(st.number_input("Maximum raster pixels per scene", 50_000, 5_000_000, 2_000_000, 50_000, key="satellite_max_pixels"))
                excluded_scl = set(DEFAULT_EXCLUDED_SCL)
                if include_water:
                    excluded_scl.discard(6)
                st.caption("Excluded SCL classes: " + ", ".join(f"{value} ({SCL_CLASSES[value]})" for value in sorted(excluded_scl)))

            subset = select_scene_subset(items, scene_method, max_scenes)
            st.caption(f"The current rule selects {len(subset):,} of {len(items):,} catalogue scenes for processing.")

            if st.button("Process selected satellite scenes", type="primary", width="stretch", key="satellite_process_button"):
                if not selected_indices:
                    st.error("Select at least one vegetation index.")
                else:
                    progress = st.progress(0.0, text="Preparing satellite processing...")
                    status_box = st.empty()

                    def progress_callback(position: int, total: int, scene_id: str) -> None:
                        progress.progress(position / max(total, 1), text=f"Processing scene {position}/{total}")
                        status_box.caption(scene_id)

                    try:
                        time_series = process_scene_collection(
                            subset,
                            geometry,
                            selected_indices,
                            satellite_cache_dir,
                            resolution_m=resolution,
                            minimum_usable_pixel_percent=minimum_usable,
                            excluded_scl_classes=excluded_scl,
                            maximum_pixels=maximum_pixels,
                            force_refresh=force_refresh,
                            progress_callback=progress_callback,
                        )
                        st.session_state.satellite_time_series = time_series
                        st.session_state.satellite_processing_config = {
                            "Field": field_name,
                            "Crop": crop,
                            "Planting date": str(planting_date),
                            "Indices": selected_indices,
                            "Scene-selection rule": scene_method,
                            "Processed scenes": len(subset),
                            "Analysis resolution (m)": resolution,
                            "Minimum clear pixels (%)": minimum_usable,
                            "Excluded SCL classes": sorted(excluded_scl),
                            "AOI": aoi_metadata,
                        }
                        st.session_state.satellite_preview = None
                        progress.progress(1.0, text="Satellite processing complete")
                        st.toast("Satellite time series complete", icon="✅")
                    except Exception as error:
                        st.error(f"Satellite processing failed: {type(error).__name__}: {error}")

        time_series = st.session_state.get("satellite_time_series")
        if isinstance(time_series, pd.DataFrame) and not time_series.empty:
            usable = time_series.loc[time_series["Status"].eq("Usable")].copy()
            failed = time_series.loc[~time_series["Status"].eq("Usable")].copy()
            summary_metrics = st.columns(5)
            summary_metrics[0].metric("Processed scenes", f"{len(time_series):,}")
            summary_metrics[1].metric("Usable observations", f"{len(usable):,}")
            summary_metrics[2].metric("Rejected or failed", f"{len(failed):,}")
            summary_metrics[3].metric("Median clear field", f"{pd.to_numeric(usable.get('Field usable pixels (%)'), errors='coerce').median():.1f}%" if not usable.empty else "NA")
            summary_metrics[4].metric("Cache hits", f"{pd.Series(time_series.get('Loaded from cache', False)).fillna(False).astype(bool).sum():,}")

            current_indices = (st.session_state.get("satellite_processing_config") or {}).get("Indices", [])
            figure = _satellite_time_series_figure(time_series, list(current_indices))
            if figure.data:
                st.plotly_chart(figure, width="stretch")
            with st.expander("Processed satellite observations"):
                st.dataframe(time_series, hide_index=True, width="stretch")
            if not failed.empty:
                with st.expander("Rejected or failed scenes"):
                    failure_columns = [column for column in ["Date", "Scene ID", "Status", "Error", "Field usable pixels (%)", "Scene cloud (%)"] if column in failed]
                    st.dataframe(failed[failure_columns], hide_index=True, width="stretch")

            download_columns = st.columns(2)
            with download_columns[0]:
                st.download_button(
                    "Download satellite time series",
                    time_series.to_csv(index=False).encode("utf-8"),
                    file_name="satellite_index_time_series.csv",
                    mime="text/csv",
                    key="download_satellite_time_series",
                    width="stretch",
                )
            with download_columns[1]:
                export_path = satellite_export_dir / "satellite_crop_monitoring_package.zip"
                try:
                    build_satellite_export_package(
                        export_path,
                        geometry=geometry,
                        search_catalog=st.session_state.get("satellite_scene_catalog"),
                        time_series=time_series,
                        metadata={
                            **satellite_module_metadata(),
                            "field": field_name,
                            "crop": crop,
                            "planting_date": str(planting_date),
                            "aoi": aoi_metadata,
                            "search": st.session_state.get("satellite_search_config"),
                            "processing": st.session_state.get("satellite_processing_config"),
                        },
                        anomaly_table=st.session_state.get("satellite_anomaly_results"),
                        model_pairs=st.session_state.get("satellite_root_zone_pairs"),
                        model_correlations=st.session_state.get("satellite_root_zone_correlations"),
                    )
                    st.download_button(
                        "Download complete satellite package",
                        export_path.read_bytes(),
                        file_name="satellite_crop_monitoring_package.zip",
                        mime="application/zip",
                        key="download_satellite_package",
                        width="stretch",
                    )
                except Exception as error:
                    st.warning(f"The export package could not be prepared: {error}")
        elif not isinstance(catalogue, pd.DataFrame) or catalogue.empty:
            empty_state("No Sentinel-2 catalogue has been searched in this session.", "Select an area and search period, then press Search Sentinel-2 catalogue.")

    with image_tab:
        st.markdown("### Inspect an individual acquisition")
        items = st.session_state.get("satellite_scene_items")
        catalogue = st.session_state.get("satellite_scene_catalog")
        if not isinstance(items, list) or not items or not isinstance(catalogue, pd.DataFrame) or catalogue.empty:
            st.info("Search the Sentinel-2 catalogue first.")
        else:
            labels = {
                f"{row['Date']} · {row['Scene ID']} · cloud {safe_float(row['Scene cloud (%)']):.1f}%": row["Scene ID"]
                for _, row in catalogue.iterrows()
            }
            selected_label = st.selectbox("Scene", list(labels), key="satellite_preview_scene")
            selected_scene_id = labels[selected_label]
            selected_index = st.selectbox("Index preview", list(SATELLITE_INDEX_REGISTRY), key="satellite_preview_index")
            preview_resolution = float(st.selectbox("Preview resolution", [10, 20, 30, 60], index=1, key="satellite_preview_resolution"))
            if st.button("Generate field preview", type="primary", width="stretch", key="satellite_preview_button"):
                selected_item = next(item for item in items if item.get("id") == selected_scene_id)
                try:
                    with st.spinner("Reading the selected Sentinel-2 COG windows..."):
                        preview = generate_scene_preview(
                            selected_item,
                            geometry,
                            selected_index,
                            resolution_m=preview_resolution,
                            maximum_pixels=2_000_000,
                        )
                    st.session_state.satellite_preview = preview
                    st.session_state.satellite_preview_scene_id = selected_scene_id
                except Exception as error:
                    st.error(f"Preview generation failed: {type(error).__name__}: {error}")

            preview = st.session_state.get("satellite_preview")
            if isinstance(preview, dict):
                metrics = st.columns(3)
                metrics[0].metric("Scene date", str(preview.get("date")))
                metrics[1].metric("Usable field pixels", f"{safe_float(preview.get('usable_pixel_percent')):.1f}%")
                metrics[2].metric("Index", str(preview.get("index_name")))
                image_columns = st.columns(2)
                with image_columns[0]:
                    st.image(preview["true_colour_png"], caption="Cloud-masked true-colour field window", width="stretch")
                    st.download_button("Download true-colour PNG", preview["true_colour_png"], file_name=f"{preview['scene_id']}_true_colour.png", mime="image/png", key="download_satellite_true_colour")
                with image_columns[1]:
                    st.image(preview["index_png"], caption=f"{preview['index_name']} field window", width="stretch")
                    st.download_button("Download index PNG", preview["index_png"], file_name=f"{preview['scene_id']}_{preview['index_name']}.png", mime="image/png", key="download_satellite_index_png")

                centre_lat, centre_lon = geometry_centroid(geometry)
                overlay_map = folium.Map(location=[centre_lat, centre_lon], zoom_start=15, tiles=None, control_scale=True)
                folium.TileLayer("OpenStreetMap", name="Roads & places", overlay=False, control=True, show=False).add_to(overlay_map)
                folium.TileLayer("CartoDB positron", name="Light map", overlay=False, control=True, show=False).add_to(overlay_map)
                folium.TileLayer("Esri.WorldImagery", name="Satellite imagery", attr="Esri, Maxar, Earthstar Geographics, and the GIS User Community", overlay=False, control=True, show=True).add_to(overlay_map)
                folium.GeoJson(geometry, name="Field boundary", style_function=lambda _: {"color": "#111827", "weight": 3, "fillOpacity": 0}).add_to(overlay_map)
                folium.raster_layers.ImageOverlay(
                    preview["true_colour_array"],
                    bounds=preview["bounds"],
                    name="True colour",
                    opacity=0.85,
                    interactive=True,
                ).add_to(overlay_map)
                folium.raster_layers.ImageOverlay(
                    preview["index_rgba_array"],
                    bounds=preview["bounds"],
                    name=preview["index_name"],
                    opacity=0.80,
                    interactive=True,
                    show=False,
                ).add_to(overlay_map)
                Fullscreen().add_to(overlay_map)
                folium.LayerControl(collapsed=False).add_to(overlay_map)
                st_folium(overlay_map, height=520, use_container_width=True, key="satellite_preview_overlay_map")
                with st.expander("Field-level SCL composition"):
                    scl_table = pd.DataFrame([
                        {"Class": key, "Field pixels (%)": value}
                        for key, value in preview.get("scl_percentages", {}).items()
                    ])
                    st.dataframe(scl_table, hide_index=True, width="stretch")

    with anomaly_tab:
        st.markdown("### Compare a crop season with historical satellite observations")
        time_series = st.session_state.get("satellite_time_series")
        if not isinstance(time_series, pd.DataFrame) or time_series.empty:
            st.info("Process a multi-year satellite time series first.")
        else:
            available_indices = [name for name in SATELLITE_INDEX_REGISTRY if f"{name} Mean" in time_series]
            years_available = sorted(pd.to_datetime(time_series["Date"], errors="coerce").dropna().dt.year.unique().tolist())
            if len(years_available) < 2:
                st.warning("At least two years of processed satellite observations are needed for a historical comparison.")
            else:
                controls = st.columns(5)
                with controls[0]:
                    anomaly_index = st.selectbox("Index", available_indices, key="satellite_anomaly_index")
                with controls[1]:
                    target_year = int(st.selectbox("Target season year", years_available, index=len(years_available) - 1, key="satellite_target_year"))
                with controls[2]:
                    season_length = int(st.number_input("Season length (days)", 30, 365, 180, 5, key="satellite_season_length"))
                with controls[3]:
                    bin_width = int(st.selectbox("Phenology-time bin", [5, 10, 15, 20, 30], index=2, key="satellite_anomaly_bin"))
                with controls[4]:
                    baseline_years = st.multiselect("Baseline years", [year for year in years_available if year != target_year], default=[year for year in years_available if year != target_year], key="satellite_baseline_years")

                if st.button("Calculate historical satellite anomalies", type="primary", width="stretch", key="satellite_anomaly_button"):
                    try:
                        seasonal, comparison = historical_index_anomaly(
                            time_series.loc[time_series["Status"].eq("Usable")],
                            anomaly_index,
                            target_year,
                            planting_date.month,
                            planting_date.day,
                            season_length,
                            bin_width_days=bin_width,
                            baseline_years=baseline_years,
                        )
                        st.session_state.satellite_anomaly_seasonal = seasonal
                        st.session_state.satellite_anomaly_results = comparison
                        st.session_state.satellite_anomaly_config = {
                            "Index": anomaly_index,
                            "Target year": target_year,
                            "Baseline years": baseline_years,
                            "Planting month/day": f"{planting_date.month:02d}-{planting_date.day:02d}",
                            "Season length (days)": season_length,
                            "Bin width (days)": bin_width,
                        }
                    except Exception as error:
                        st.error(f"Historical anomaly analysis failed: {type(error).__name__}: {error}")

                comparison = st.session_state.get("satellite_anomaly_results")
                config = st.session_state.get("satellite_anomaly_config") or {}
                if isinstance(comparison, pd.DataFrame) and not comparison.empty:
                    anomaly_metrics = st.columns(4)
                    anomaly_metrics[0].metric("Comparable bins", f"{len(comparison):,}")
                    anomaly_metrics[1].metric("Mean anomaly", f"{pd.to_numeric(comparison['Absolute anomaly'], errors='coerce').mean():+.3f}")
                    anomaly_metrics[2].metric("Lowest percentile", f"{pd.to_numeric(comparison['Target historical percentile'], errors='coerce').min():.1f}")
                    anomaly_metrics[3].metric("Baseline years", f"{len(config.get('Baseline years', [])):,}")
                    figure = go.Figure()
                    figure.add_trace(go.Scatter(x=comparison["DAP bin"], y=comparison["Baseline P90"], line={"width": 0}, name="Baseline P90", showlegend=False))
                    figure.add_trace(go.Scatter(x=comparison["DAP bin"], y=comparison["Baseline P10"], fill="tonexty", line={"width": 0}, name="Baseline P10–P90"))
                    figure.add_trace(go.Scatter(x=comparison["DAP bin"], y=comparison["Baseline median"], mode="lines+markers", name="Baseline median"))
                    figure.add_trace(go.Scatter(x=comparison["DAP bin"], y=comparison["Target value"], mode="lines+markers", name=f"Target {config.get('Target year')}"))
                    figure.update_layout(title=f"{config.get('Index')} relative to the historical crop-season trajectory", xaxis_title="Days after planting (binned)", yaxis_title=config.get("Index"))
                    st.plotly_chart(figure, width="stretch")
                    st.dataframe(comparison, hide_index=True, width="stretch")
                    st.download_button("Download historical satellite anomalies", comparison.to_csv(index=False).encode("utf-8"), file_name="historical_satellite_anomalies.csv", mime="text/csv", key="download_satellite_anomalies", width="stretch")

    with integration_tab:
        st.markdown("### Integrate satellite observations with Modules A and B")
        time_series = st.session_state.get("satellite_time_series")
        if not isinstance(time_series, pd.DataFrame) or time_series.empty:
            st.info("Process satellite observations first.")
        else:
            usable_time_series = time_series.loc[time_series["Status"].eq("Usable")].copy()
            schedule = _satellite_current_schedule()
            available_indices = [name for name in SATELLITE_INDEX_REGISTRY if f"{name} Mean" in usable_time_series]
            if schedule is not None:
                stage_summary = stage_index_summary(usable_time_series, schedule, available_indices)
                st.session_state.satellite_stage_summary = stage_summary
                st.markdown("#### Satellite condition by predicted crop stage")
                if stage_summary.empty:
                    st.info("The available satellite dates do not overlap the current crop-development / root-zone stage schedule.")
                else:
                    st.dataframe(stage_summary, hide_index=True, width="stretch")
                    st.download_button("Download stage-level satellite summary", stage_summary.to_csv(index=False).encode("utf-8"), file_name="satellite_stage_summary.csv", mime="text/csv", key="download_satellite_stage_summary", width="stretch")
            else:
                st.info("Run Daily weather & phenology or Soil-water balance to create a crop-stage schedule for overlay.")

            st.markdown("#### Satellite versus root-zone water model")
            root_zone = st.session_state.get("soil_water_balance_results")
            if not isinstance(root_zone, pd.DataFrame) or root_zone.empty:
                st.info("Run or attach a root-zone water analysis for the same field period before comparing it with satellite observations.")
            elif not available_indices:
                st.info("No compatible processed vegetation index is available.")
            else:
                comparison_controls = st.columns(2)
                model_index = comparison_controls[0].selectbox("Satellite index", available_indices, key="satellite_model_index")
                antecedent_days = int(comparison_controls[1].selectbox("Antecedent root-zone window", [3, 7, 14, 21, 30], index=2, key="satellite_model_window"))
                if st.button("Compare satellite and root-zone results", type="primary", width="stretch", key="satellite_model_compare_button"):
                    try:
                        paired, correlations = compare_with_root_zone_model(usable_time_series, root_zone, model_index, antecedent_days)
                        st.session_state.satellite_root_zone_pairs = paired
                        st.session_state.satellite_root_zone_correlations = correlations
                        st.session_state.satellite_model_config = {"Index": model_index, "Antecedent window (days)": antecedent_days}
                    except Exception as error:
                        st.error(f"Model comparison failed: {type(error).__name__}: {error}")

                paired = st.session_state.get("satellite_root_zone_pairs")
                correlations = st.session_state.get("satellite_root_zone_correlations")
                if isinstance(paired, pd.DataFrame) and not paired.empty:
                    st.dataframe(correlations, hide_index=True, width="stretch")
                    metric = st.selectbox("Root-zone metric for scatter plot", [column for column in ["Mean Ks", "Minimum Ks", "Maximum relative depletion", "Stress days", "Severe stress days"] if column in paired], key="satellite_scatter_metric")
                    scatter = px.scatter(paired, x=metric, y="Index value", hover_data=["Satellite date"], trendline="ols", title=f"Satellite {st.session_state.get('satellite_model_config', {}).get('Index')} versus {metric}")
                    st.plotly_chart(scatter, width="stretch")
                    download_columns = st.columns(2)
                    download_columns[0].download_button("Download paired observations", paired.to_csv(index=False).encode("utf-8"), file_name="satellite_root_zone_pairs.csv", mime="text/csv", key="download_satellite_model_pairs", width="stretch")
