def _active_project(refresh: bool = False) -> dict | None:
    project_id = st.session_state.get("active_project_id")
    if not project_id:
        return None
    if refresh or not isinstance(st.session_state.get("active_project"), dict):
        try:
            st.session_state.active_project = PROJECT_STORE.load(project_id)
        except Exception:
            st.session_state.active_project_id = None
            st.session_state.active_project = None
            return None
    return st.session_state.get("active_project")


def _activate_project(project_id: str) -> dict:
    project = PROJECT_STORE.load(project_id)
    st.session_state.active_project_id = project_id
    st.session_state.active_project = project
    return project


def _compact_frame(frame, rows: int = 30):
    if not isinstance(frame, pd.DataFrame) or frame.empty:
        return None
    numeric = frame.select_dtypes(include=[np.number])
    summary = numeric.describe().reset_index() if not numeric.empty else None
    return {
        "rows": int(len(frame)),
        "columns": [str(c) for c in frame.columns],
        "head": frame.head(rows),
        "tail": frame.tail(min(rows, len(frame))),
        "numeric_summary": summary,
    }


def _workspace_snapshot_payload() -> dict:
    return {
        "daily_weather": {
            "request": st.session_state.get("daily_weather_request"),
            "metadata": st.session_state.get("daily_weather_metadata"),
            "events": st.session_state.get("daily_event_summary"),
            "phenology_parameters": st.session_state.get("phenology_params"),
            "phenology_schedule": _compact_frame(st.session_state.get("phenology_schedule"), 15),
            "stage_exposure": _compact_frame(st.session_state.get("phenology_exposure"), 15),
        },
        "soil_water": {
            "metadata": st.session_state.get("soil_water_metadata"),
            "season_summary": st.session_state.get("soil_water_season_summary"),
            "stage_summary": _compact_frame(st.session_state.get("soil_water_stage_summary"), 15),
        },
        "satellite": {
            "aoi_metadata": st.session_state.get("satellite_aoi_metadata"),
            "search": st.session_state.get("satellite_search_config"),
            "processing": st.session_state.get("satellite_processing_config"),
            "time_series": _compact_frame(st.session_state.get("satellite_time_series"), 20),
            "stage_summary": _compact_frame(st.session_state.get("satellite_stage_summary"), 15),
        },
    }


def _project_schedule(project: dict) -> pd.DataFrame:
    season = project.get("season", {}) or {}
    crop = str(season.get("crop") or "Maize")
    planting = pd.Timestamp(season.get("planting_date")).date()
    profiles = available_water_profiles(VALIDATED_CROP_LIBRARY, crop)
    profile = profiles[0] if profiles else "User-defined profile"
    rows = soil_stage_parameter_rows(VALIDATED_CROP_LIBRARY, crop, profile)
    has_durations = bool(
        not rows.empty
        and rows[["Duration minimum (days)", "Duration maximum (days)"]]
        .notna().any(axis=1).any()
    )
    expected_harvest = pd.to_datetime(season.get("expected_harvest_date"), errors="coerce")
    if pd.notna(expected_harvest):
        custom_days = max(1, int((expected_harvest.date() - planting).days) + 1)
    else:
        custom_days = 365 if crop in {"Coffee", "Avocado", "Citrus", "Agave"} else 140
    kc_values = pd.to_numeric(rows.get("Kc"), errors="coerce") if not rows.empty else pd.Series(dtype=float)
    constant_kc = float(kc_values.dropna().mean()) if kc_values.notna().any() else 0.8
    roots = crop_root_defaults(crop)
    return build_soil_stage_schedule(
        VALIDATED_CROP_LIBRARY,
        crop,
        profile,
        planting,
        duration_strategy="Midpoint",
        custom_season_days=custom_days,
        constant_kc=None if has_durations else constant_kc,
        constant_p=float(roots.get("p", 0.5)),
    )


def _project_location_selector(prefix: str) -> tuple[str, float, float, str | None]:
    locations = _module_a_location_table()
    mode = st.radio(
        "Location source",
        ["App city", "Custom coordinates"],
        horizontal=True,
        key=f"{prefix}_location_mode",
    )
    if mode == "App city":
        label = st.selectbox(
            "Location",
            locations["Location"].tolist(),
            index=_module_a_default_location_index(locations),
            key=f"{prefix}_location_label",
        )
        row = locations.loc[locations["Location"].eq(label)].iloc[0]
        return label, float(row["lat"]), float(row["lng"]), str(row["STATE"])
    columns = st.columns(2)
    with columns[0]:
        latitude = float(st.number_input("Latitude", -90.0, 90.0, float(ACTIVE_COUNTRY_MAP_CENTRE[0]), 0.01, key=f"{prefix}_latitude"))
    with columns[1]:
        longitude = float(st.number_input("Longitude", -180.0, 180.0, float(ACTIVE_COUNTRY_MAP_CENTRE[1]), 0.01, key=f"{prefix}_longitude"))
    return f"Custom point ({latitude:.4f}, {longitude:.4f})", latitude, longitude, None


def page_projects() -> None:
    page_header(
        "Release 1 · Research workspace",
        "Persistent field projects",
        "Create reusable field-season records and preserve crop, location, soil, irrigation, satellite and model-run provenance across modules.",
    )
    st.info(
        "Projects are stored locally as portable JSON files. API keys and source climate datasets are never written into project records."
    )
    create_tab, manage_tab, active_tab, import_tab = st.tabs(
        ["Create project", "Project library", "Active project", "Import & methods"]
    )

    with create_tab:
        with st.form("create_persistent_project"):
            name = st.text_input("Project name", value="Montecillo maize season", key="project_create_name")
            description = st.text_area("Description", key="project_create_description")
            location_name, latitude, longitude, state = _project_location_selector("project_create")
            crop_names = list((VALIDATED_CROP_LIBRARY.get("crops") or {}).keys())
            columns = st.columns(3)
            with columns[0]:
                crop = st.selectbox("Crop", crop_names, index=crop_names.index("Maize") if "Maize" in crop_names else 0, key="project_create_crop")
            with columns[1]:
                planting = st.date_input("Planting or season start", value=date(date.today().year, 5, 1), key="project_create_planting")
            with columns[2]:
                expected_days = int(st.number_input("Expected season length (days)", 1, 1000, 140, 1, key="project_create_duration"))
            capture_field = st.checkbox(
                "Attach the field geometry currently defined in Satellite crop monitoring",
                value=bool(st.session_state.get("satellite_aoi_geometry")),
                key="project_create_capture_field",
            )
            submitted = st.form_submit_button("Create and activate project", type="primary", width="stretch")
        if submitted:
            try:
                expected_harvest = (pd.Timestamp(planting) + pd.Timedelta(days=expected_days - 1)).date().isoformat()
                project = new_project_template(
                    name=name,
                    location_name=location_name,
                    latitude=latitude,
                    longitude=longitude,
                    crop=crop,
                    planting_date=str(planting),
                    expected_harvest_date=expected_harvest,
                    description=description,
                )
                project["location"]["state"] = state
                if capture_field and st.session_state.get("satellite_aoi_geometry"):
                    project["location"]["field_geometry"] = st.session_state.get("satellite_aoi_geometry")
                    project["location"]["field_area_ha"] = (st.session_state.get("satellite_aoi_metadata") or {}).get("Area (ha)")
                project = PROJECT_STORE.save(project, action="Project created through dashboard")
                _activate_project(project["project_id"])
                st.success(f"Created and activated {project['name']}.")
            except Exception as error:
                st.error(f"Project creation failed: {type(error).__name__}: {error}")

    with manage_tab:
        library = PROJECT_STORE.list_projects()
        if library.empty:
            empty_state("No projects have been saved.", "Create the first project in the Create project tab.")
        else:
            st.dataframe(library, hide_index=True, width="stretch")
            labels = {
                f"{row['Name']} · {row.get('Crop')} · {row.get('Location')} · {str(row['Project ID'])[:8]}": row["Project ID"]
                for _, row in library.iterrows()
                if row.get("Status") != "Error"
            }
            selection = st.selectbox("Project", list(labels), key="project_library_selection")
            project_id = labels[selection]
            action_columns = st.columns(4)
            if action_columns[0].button("Activate", type="primary", width="stretch", key="project_activate"):
                project = _activate_project(project_id)
                st.success(f"Active project: {project['name']}")
            if action_columns[1].button("Duplicate", width="stretch", key="project_duplicate"):
                project = PROJECT_STORE.duplicate(project_id)
