    with water_tab:
        if isinstance(root_zone, pd.DataFrame) and not root_zone.empty:
            depletion_column = next((c for c in root_zone.columns if "depletion" in str(c).casefold() and "start" not in str(c).casefold()), None)
            if depletion_column:
                plot = px.line(root_zone, x="DATE", y=[depletion_column, "RAW (mm)", "TAW (mm)"], title="Root-zone depletion relative to RAW and TAW")
                st.plotly_chart(plot, width="stretch")
            st.dataframe(root_zone.tail(120), hide_index=True, width="stretch")
        else:
            st.info("Root-zone status is unavailable until the monitor is refreshed.")
    with satellite_tab:
        if satellite_status.get("available"):
            sat_metrics = st.columns(6)
            sat_metrics[0].metric("Date", satellite_status.get("date"))
            sat_metrics[1].metric("Age", f"{satellite_status.get('age_days')} days")
            for index, name in enumerate(["NDVI", "EVI", "NDMI", "NDRE"], start=2):
                sat_metrics[index].metric(name, f"{satellite_status.get(name):.3f}" if satellite_status.get(name) is not None else "—")
            if isinstance(satellite, pd.DataFrame):
                st.dataframe(satellite.tail(50), hide_index=True, width="stretch")
        else:
            st.info("No processed Module C satellite time series is currently in memory. Run Satellite crop monitoring for this field, then return here.")
    with project_tab:
        st.download_button(
            "Download live snapshot JSON",
            json.dumps(_json_safe(snapshot), indent=2, ensure_ascii=False).encode("utf-8"),
            file_name="current_season_snapshot.json",
            mime="application/json",
            width="stretch",
            key="live_download_snapshot",
        )
        if st.button("Save live snapshot to active project", type="primary", width="stretch", key="live_save_snapshot"):
            try:
                updated = append_workspace_snapshot(project, label=f"Live monitor {date.today()}", modules={"live_monitor": snapshot})
                updated = PROJECT_STORE.save(updated)
                st.session_state.active_project = updated
                st.success("Live monitor snapshot saved to the project.")
            except Exception as error:
                st.error(f"Could not save snapshot: {type(error).__name__}: {error}")
        methods_panel(
            "The live monitor synthesises the active project's stage schedule, daily NASA POWER weather, Module B root-zone simulation and the latest processed Module C satellite observation.",
            [
                "Missing layers remain visibly unavailable rather than being imputed.",
                "The dashboard is an analytical monitor, not an automated irrigation or crop-management instruction system.",
                "Near-real-time weather and optical imagery can be delayed or revised.",
                "Satellite vegetation indices are not direct yield or diagnosis measurements.",
            ],
        )

    render_chatgpt_interpretation_group([
        (
            "current_season_monitor",
            "Current-season crop monitoring report",
            st.session_state.get("live_monitor_snapshot"),
            "Interpret the current-season layers conservatively. Distinguish observed NASA and Sentinel-2 data from phenology and root-zone model outputs, identify missing or stale layers, and do not issue operational irrigation or pesticide instructions.",
        )
    ])




