def _release2_numeric_columns(frame: pd.DataFrame) -> list[str]:
    if not isinstance(frame, pd.DataFrame) or frame.empty:
        return []
    columns: list[str] = []
    for column in frame.columns:
        converted = pd.to_numeric(frame[column], errors="coerce")
        if converted.notna().sum() >= max(2, int(len(frame) * 0.20)):
            columns.append(str(column))
    return columns


def _release2_read_csv(uploaded) -> pd.DataFrame:
    if uploaded is None:
        return pd.DataFrame()
    try:
        frame = pd.read_csv(uploaded)
    except Exception as error:
        raise ValueError(f"CSV could not be read: {error}") from error
    frame.columns = [str(column).strip() for column in frame.columns]
    return frame


def _release2_latest_aquacrop_run(project: dict | None) -> dict | None:
    current = st.session_state.get("aquacrop_run")
    if isinstance(current, dict):
        return current
    if not isinstance(project, dict):
        return None
    runs = project.get("model_runs", []) or []
    for run in reversed(runs):
        if isinstance(run, dict) and "aquacrop" in str(run.get("backend", "")).casefold():
            return run
    return None


def _release2_find_numeric_value(container, keywords: list[str]) -> float | None:
    frame = validation_json_safe_dataframe(container)
    if frame is None and isinstance(container, dict):
        records = []
        for key, value in container.items():
            if isinstance(value, (int, float, np.number)):
                records.append({"Parameter": str(key), "Value": value})
        frame = pd.DataFrame(records)
    if frame is None or frame.empty:
        return None
    for column in frame.columns:
        token = str(column).casefold()
        if any(keyword in token for keyword in keywords):
            series = pd.to_numeric(frame[column], errors="coerce").dropna()
            if not series.empty:
                return float(series.iloc[-1])
    if {"Parameter", "Value"}.issubset(frame.columns):
        for _, row in frame.iterrows():
            token = str(row["Parameter"]).casefold()
            if any(keyword in token for keyword in keywords):
                value = pd.to_numeric(pd.Series([row["Value"]]), errors="coerce").iloc[0]
                if pd.notna(value):
                    return float(value)
    return None


def _release2_validation_template() -> bytes:
    template = pd.DataFrame({
        "Record ID": ["field_a_2024", "field_b_2024", "field_a_2025"],
        "Location": ["Field A", "Field B", "Field A"],
        "Year": [2024, 2024, 2025],
        "Observed yield (t/ha)": [6.2, 4.8, 6.7],
        "AquaCrop prediction": [5.9, 5.1, 6.4],
        "Suitability model prediction": [5.5, 4.6, 5.8],
        "Satellite model prediction": [6.0, 4.9, 6.5],
    })
    return template.to_csv(index=False).encode("utf-8")


def page_validation_centre() -> None:
    page_header(
        "Release 2 · Scientific evaluation",
        "Validation Centre",
        "Evaluate model predictions against independent observations using transparent, leakage-aware validation designs.",
    )
    project = _active_project()
    if project:
        st.caption(f"Active project: {project.get('name')} · {(project.get('season') or {}).get('crop')}")
    st.warning(
        "Validation is only as independent as the uploaded observations and matching procedure. "
        "Do not treat calibration performance on reused training data as external validation."
    )

    source_tab, setup_tab, results_tab, diagnostics_tab, export_tab = st.tabs(
        ["Data", "Design", "Results", "Diagnostics", "Export & project"]
    )

    with source_tab:
        source_choice = st.radio(
            "Validation-data source",
            ["Upload paired observations and predictions", "Use current Yield validation result", "Use current Validation Centre data"],
            horizontal=True,
            key="release2_validation_source_choice",
        )
        frame = pd.DataFrame()
        if source_choice == "Upload paired observations and predictions":
            uploaded = st.file_uploader(
                "Upload CSV containing one observed column and one or more prediction columns",
                type=["csv"],
                key="release2_validation_upload",
            )
            if uploaded is not None:
                try:
                    frame = _release2_read_csv(uploaded)
                    st.session_state.release2_validation_source = frame
                except Exception as error:
                    st.error(str(error))
            st.download_button(
                "Download validation CSV template",
                _release2_validation_template(),
                file_name="release2_validation_template.csv",
                mime="text/csv",
                key="release2_validation_template",
            )
        elif source_choice == "Use current Yield validation result":
            candidate = st.session_state.get("yield_validation_results")
            if isinstance(candidate, pd.DataFrame):
                frame = candidate.copy()
                st.session_state.release2_validation_source = frame
            else:
                st.info("No Yield validation result is currently in memory.")
        else:
            candidate = st.session_state.get("release2_validation_source")
            if isinstance(candidate, pd.DataFrame):
                frame = candidate.copy()

        if isinstance(frame, pd.DataFrame) and not frame.empty:
            st.success(f"Loaded {len(frame):,} rows and {len(frame.columns):,} columns.")
            st.dataframe(frame.head(200), hide_index=True, width="stretch")
            missing = frame.isna().mean().mul(100).sort_values(ascending=False).rename("Missing (%)").reset_index(names="Column")
            with st.expander("Missing-data summary"):
                st.dataframe(missing, hide_index=True, width="stretch")
        else:
            empty_state("No validation table loaded.", "Upload a CSV or select an existing result.")

    with setup_tab:
        frame = st.session_state.get("release2_validation_source")
        if not isinstance(frame, pd.DataFrame) or frame.empty:
            empty_state("No validation table loaded.", "Load data in the Data tab.")
        else:
            task = st.radio("Outcome type", ["Continuous outcome", "Binary event"], horizontal=True, key="release2_validation_task")
            numeric_columns = _release2_numeric_columns(frame)
            if len(numeric_columns) < 2:
                st.error("At least two numeric columns are required.")
            else:
                observed = st.selectbox("Observed outcome", numeric_columns, key="release2_validation_observed")
                prediction_options = [column for column in numeric_columns if column != observed]
                predictions = st.multiselect(
                    "Prediction columns",
                    prediction_options,
                    default=prediction_options[: min(3, len(prediction_options))],
                    key="release2_validation_predictions_select",
                )
                other_columns = ["None"] + [str(column) for column in frame.columns]
                controls = st.columns(3)
                group_column = controls[0].selectbox("Independent group", other_columns, key="release2_validation_group")
                date_column = controls[1].selectbox("Date or year", other_columns, key="release2_validation_date")
                id_column = controls[2].selectbox("Record identifier", other_columns, key="release2_validation_id")
                group_column = None if group_column == "None" else group_column
                date_column = None if date_column == "None" else date_column
                id_column = None if id_column == "None" else id_column

                if task == "Continuous outcome":
                    calibration = st.selectbox(
                        "Evaluation design",
                        ["None", "Grouped cross-validation", "Temporal holdout", "K-fold cross-validation"],
                        help=(
                            "None evaluates supplied predictions directly. Other options fit a simple linear "
                            "calibration only on training partitions and evaluate it on held-out records."
                        ),
                        key="release2_validation_calibration",
                    )
                    folds = int(st.slider("Cross-validation folds", 2, 10, 5, key="release2_validation_folds"))
                    bootstrap_iterations = int(st.select_slider(
                        "Bootstrap iterations",
                        options=[250, 500, 1000, 2000, 5000],
                        value=1000,
                        key="release2_validation_bootstrap_iterations",
                    ))
                    run_disabled = not predictions
                    if st.button("Run continuous validation", type="primary", width="stretch", disabled=run_disabled, key="release2_run_regression_validation"):
                        try:
                            metrics, prediction_table = evaluate_regression_models(
                                frame,
                                observed_column=observed,
                                prediction_columns=predictions,
                                calibration_strategy=calibration,
                                group_column=group_column,
                                date_column=date_column,
                                folds=folds,
                            )
                            grouped = grouped_regression_metrics(prediction_table, group_column=group_column) if group_column else pd.DataFrame()
                            intervals = []
                            for model_name, subset in prediction_table.groupby("Model"):
                                ci = bootstrap_metric_intervals(
                                    subset["Observed"],
                                    subset["Prediction"],
                                    iterations=bootstrap_iterations,
                                )
                                if not ci.empty:
                                    ci.insert(0, "Model", model_name)
                                    intervals.append(ci)
                            bootstrap = pd.concat(intervals, ignore_index=True) if intervals else pd.DataFrame()
                            settings = {
                                "task": task,
                                "observed_column": observed,
                                "prediction_columns": predictions,
                                "group_column": group_column,
                                "date_column": date_column,
                                "id_column": id_column,
                                "evaluation_design": calibration,
                                "folds": folds,
                                "bootstrap_iterations": bootstrap_iterations,
                            }
                            st.session_state.release2_validation_metrics = metrics
                            st.session_state.release2_validation_predictions = prediction_table
                            st.session_state.release2_validation_grouped = grouped
                            st.session_state.release2_validation_bootstrap = bootstrap
                            st.session_state.release2_validation_settings = settings
                            st.success("Validation completed.")
                        except Exception as error:
                            st.error(f"{type(error).__name__}: {error}")
                else:
                    threshold = float(st.slider("Prediction threshold", 0.0, 1.0, 0.5, 0.01, key="release2_binary_threshold"))
                    if st.button("Run binary-event validation", type="primary", width="stretch", disabled=not predictions, key="release2_run_binary_validation"):
                        try:
                            rows = []
                            prediction_rows = []
                            for model_name in predictions:
                                complete = frame[[observed, model_name]].copy()
                                complete[observed] = pd.to_numeric(complete[observed], errors="coerce")
                                complete[model_name] = pd.to_numeric(complete[model_name], errors="coerce")
                                complete = complete.dropna()
                                rows.append({"Model": model_name, **release2_binary_metrics(complete[observed], complete[model_name], threshold=threshold)})
                                part = complete.rename(columns={observed: "Observed", model_name: "Prediction"})
                                part["Model"] = model_name
                                prediction_rows.append(part)
                            st.session_state.release2_validation_metrics = pd.DataFrame(rows)
                            st.session_state.release2_validation_predictions = pd.concat(prediction_rows, ignore_index=True)
                            st.session_state.release2_validation_grouped = pd.DataFrame()
                            st.session_state.release2_validation_bootstrap = pd.DataFrame()
                            st.session_state.release2_validation_settings = {
                                "task": task,
                                "observed_column": observed,
                                "prediction_columns": predictions,
                                "threshold": threshold,
                                "id_column": id_column,
                            }
                            st.success("Binary validation completed.")
                        except Exception as error:
                            st.error(f"{type(error).__name__}: {error}")

    with results_tab:
        metrics = st.session_state.get("release2_validation_metrics")
        predictions_long = st.session_state.get("release2_validation_predictions")
        if not isinstance(metrics, pd.DataFrame) or metrics.empty:
            empty_state("No validation results.", "Configure and run an analysis in the Design tab.")
        else:
            st.dataframe(metrics, hide_index=True, width="stretch")
            settings = st.session_state.get("release2_validation_settings") or {}
            if settings.get("task") == "Continuous outcome" and isinstance(predictions_long, pd.DataFrame):
                chart = px.scatter(
                    predictions_long,
                    x="Observed",
                    y="Prediction",
                    color="Model",
                    hover_data=[column for column in ["Validation split", "Residual", "Absolute error"] if column in predictions_long.columns],
                    title="Observed versus independently evaluated predictions",
                )
                values = pd.concat([predictions_long["Observed"], predictions_long["Prediction"]]).dropna()
                if not values.empty:
                    chart.add_shape(type="line", x0=values.min(), y0=values.min(), x1=values.max(), y1=values.max(), line=dict(dash="dash"))
                st.plotly_chart(chart, width="stretch")
                error_chart = px.box(predictions_long, x="Model", y="Residual", points="outliers", title="Residual distributions")
                error_chart.add_hline(y=0, line_dash="dash")
                st.plotly_chart(error_chart, width="stretch")
            elif isinstance(predictions_long, pd.DataFrame):
                st.dataframe(predictions_long.head(500), hide_index=True, width="stretch")

    with diagnostics_tab:
        predictions_long = st.session_state.get("release2_validation_predictions")
        grouped = st.session_state.get("release2_validation_grouped")
        bootstrap = st.session_state.get("release2_validation_bootstrap")
        settings = st.session_state.get("release2_validation_settings") or {}
        if not isinstance(predictions_long, pd.DataFrame) or predictions_long.empty:
            empty_state("No diagnostic data.", "Run a validation analysis first.")
        else:
            if isinstance(grouped, pd.DataFrame) and not grouped.empty:
                st.markdown("### Performance by independent group")
                st.dataframe(grouped, hide_index=True, width="stretch")
            if isinstance(bootstrap, pd.DataFrame) and not bootstrap.empty:
                st.markdown("### Bootstrap metric intervals")
                st.dataframe(bootstrap, hide_index=True, width="stretch")
            if settings.get("task") == "Continuous outcome":
                model_names = predictions_long["Model"].dropna().astype(str).unique().tolist()
                selected_model = st.selectbox("Bland–Altman model", model_names, key="release2_bland_model")
                subset = predictions_long.loc[predictions_long["Model"].astype(str).eq(selected_model)]
                bland, bland_summary = bland_altman_table(subset["Observed"], subset["Prediction"])
                ba_chart = px.scatter(
                    bland,
                    x="Mean of observed and predicted",
                    y="Difference (predicted - observed)",
                    title=f"Bland–Altman agreement · {selected_model}",
                )
                ba_chart.add_hline(y=bland_summary["Bias"])
                ba_chart.add_hline(y=bland_summary["Lower agreement limit"], line_dash="dash")
                ba_chart.add_hline(y=bland_summary["Upper agreement limit"], line_dash="dash")
                st.plotly_chart(ba_chart, width="stretch")
                st.json(bland_summary)

    with export_tab:
        metrics = st.session_state.get("release2_validation_metrics")
        predictions_long = st.session_state.get("release2_validation_predictions")
        settings = st.session_state.get("release2_validation_settings") or {}
        if not isinstance(metrics, pd.DataFrame) or metrics.empty or not isinstance(predictions_long, pd.DataFrame):
            empty_state("No validation export available.", "Run a validation analysis.")
        else:
            package = validation_export_package(
                settings=settings,
                metrics=metrics,
                predictions=predictions_long,
                grouped_metrics=st.session_state.get("release2_validation_grouped"),
                bootstrap_intervals=st.session_state.get("release2_validation_bootstrap"),
            )
            st.download_button(
                "Download validation research package",
                package,
                file_name="release2_validation_centre_package.zip",
                mime="application/zip",
                width="stretch",
                key="release2_validation_export",
            )
            if project and st.button("Save validation snapshot to active project", type="primary", width="stretch", key="release2_validation_save_project"):
                try:
                    updated = append_workspace_snapshot(
                        project,
                        label=f"Validation Centre {datetime.now().strftime('%Y-%m-%d %H:%M')}",
                        modules={
                            "validation_settings": settings,
                            "validation_metrics": metrics,
                            "validation_predictions": predictions_long.head(500),
                        },
                    )
                    updated = PROJECT_STORE.save(updated)
                    st.session_state.active_project = updated
                    st.success("Validation snapshot saved.")
                except Exception as error:
                    st.error(f"Could not save validation snapshot: {type(error).__name__}: {error}")
            methods_panel(
                "The Validation Centre evaluates paired predictions and observations. Optional linear calibration is fitted only within training partitions.",
                [
                    "Grouped validation should use genuinely independent fields, locations or experimental units.",
                    "Temporal holdout trains on earlier observations and evaluates later observations.",
                    "Strong correlation does not guarantee low bias or good calibration.",
                    "Bootstrap intervals describe sampling uncertainty in the supplied validation sample.",
                ],
            )

    render_chatgpt_interpretation_group([
        (
            "release2_validation",
            "Model validation report",
            {
                "settings": st.session_state.get("release2_validation_settings"),
                "metrics": st.session_state.get("release2_validation_metrics"),
                "grouped_metrics": st.session_state.get("release2_validation_grouped"),
                "bootstrap_intervals": st.session_state.get("release2_validation_bootstrap"),
            },
            "Interpret validation performance conservatively. Distinguish direct external validation from cross-validated calibration, discuss bias and calibration alongside correlation, identify small groups or samples, and do not call a model validated beyond the represented crops, locations, years and management systems.",
        )
    ])


def page_water_productivity_economics() -> None:
    page_header(
        "Yield & economic decision analysis",
        "Water productivity & economics",
        "Compare field-season water productivity and economic scenarios using explicit prices, costs and uncertainty assumptions; reuse recorded field context where available.",
    )
    project = _active_project() or _aquacrop_active_field_context()
    season = (project or {}).get("season", {}) or {}
    location = (project or {}).get("location", {}) or {}
    observations = (project or {}).get("observations", {}) or {}
    water_summary = st.session_state.get("soil_water_season_summary") or {}
    aqua_run = _release2_latest_aquacrop_run(project)

    observed_yield = observations.get("observed_yield_t_ha")
    aqua_yield = _release2_find_numeric_value((aqua_run or {}).get("final_stats"), ["yield", "dry yield"])
    default_yield = next((value for value in [observed_yield, aqua_yield] if value is not None and np.isfinite(float(value))), 5.0)
    default_etc = float(water_summary.get("Actual ETc (mm)", water_summary.get("Potential ETc (mm)", 500.0)) or 500.0)
    default_irrigation = float(water_summary.get("Gross irrigation (mm)", 0.0) or 0.0)
    default_rain = float(water_summary.get("Effective rainfall (mm)", 0.0) or 0.0)
    default_area = float(location.get("field_area_ha") or 1.0)
    recorded_operation_cost_per_ha = None
    recorded_irrigation_mm = None
    if project and project.get("field_id"):
        try:
            operations = FIELD_OPERATIONS_DB.operations(str(project.get("field_id")))
            if isinstance(operations, pd.DataFrame) and not operations.empty:
                total_cost = pd.to_numeric(operations.get("cost"), errors="coerce").sum(min_count=1)
                total_water = pd.to_numeric(operations.get("water_mm"), errors="coerce").sum(min_count=1)
                if pd.notna(total_cost) and default_area > 0:
                    recorded_operation_cost_per_ha = float(total_cost) / float(default_area)
                if pd.notna(total_water):
                    recorded_irrigation_mm = float(total_water)
        except Exception:
            pass
    if (not water_summary) and recorded_irrigation_mm is not None:
        default_irrigation = float(recorded_irrigation_mm)

    setup_tab, scenarios_tab, risk_tab, export_tab = st.tabs(
        ["Add scenario", "Scenario comparison", "Financial uncertainty", "Export & project"]
    )

    with setup_tab:
        st.caption(
            "Economic inputs are explicit assumptions. When recorded field-operation costs or irrigation depth are available, AGROLATTICE uses them only as editable starting values; it does not assume they represent complete production costs."
        )
        with st.form("release2_economic_scenario_form"):
            name = st.text_input("Scenario name", value=f"{season.get('crop', 'Crop')} baseline", key="release2_econ_name")
            biological = st.columns(5)
            yield_t_ha = float(biological[0].number_input("Yield (t/ha)", min_value=0.0, value=float(default_yield), step=0.1, key="release2_econ_yield"))
            area_ha = float(biological[1].number_input("Area (ha)", min_value=0.01, value=max(0.01, default_area), step=0.1, key="release2_econ_area"))
            etc_mm = float(biological[2].number_input("Seasonal ETc (mm)", min_value=0.0, value=max(0.0, default_etc), step=10.0, key="release2_econ_etc"))
            effective_rain = float(biological[3].number_input("Effective rainfall (mm)", min_value=0.0, value=max(0.0, default_rain), step=10.0, key="release2_econ_rain"))
            irrigation_mm = float(biological[4].number_input("Gross irrigation (mm)", min_value=0.0, value=max(0.0, default_irrigation), step=10.0, key="release2_econ_irrigation"))

            financial = st.columns(4)
            crop_price = float(financial[0].number_input("Crop price (currency/t)", min_value=0.0, value=300.0, step=10.0, key="release2_econ_price"))
            variable_cost_default = float(recorded_operation_cost_per_ha) if recorded_operation_cost_per_ha is not None else 800.0
            variable_cost = float(financial[1].number_input("Non-water variable cost (currency/ha)", min_value=0.0, value=max(0.0, variable_cost_default), step=50.0, key="release2_econ_variable_cost"))
            fixed_cost = float(financial[2].number_input("Fixed cost (currency/ha)", min_value=0.0, value=200.0, step=50.0, key="release2_econ_fixed_cost"))
            water_price = float(financial[3].number_input("Water price (currency/m³)", min_value=0.0, value=0.0, step=0.01, format="%.3f", key="release2_econ_water_price"))

            pumping = st.columns(4)
            pumping_kwh = float(pumping[0].number_input("Pumping energy (kWh/m³)", min_value=0.0, value=0.0, step=0.01, format="%.3f", key="release2_econ_pumping_kwh"))
            electricity_price = float(pumping[1].number_input("Electricity price (currency/kWh)", min_value=0.0, value=0.0, step=0.01, format="%.3f", key="release2_econ_electricity"))
            irrigation_labour = float(pumping[2].number_input("Irrigation labour (currency/ha)", min_value=0.0, value=0.0, step=25.0, key="release2_econ_labour"))
            other_irrigation = float(pumping[3].number_input("Other irrigation cost (currency/ha)", min_value=0.0, value=0.0, step=25.0, key="release2_econ_other_irrigation"))
            add_scenario = st.form_submit_button("Calculate and add scenario", type="primary", width="stretch")

        if add_scenario:
            try:
                result = calculate_economic_scenario(
                    scenario_name=name,
                    yield_t_ha=yield_t_ha,
                    crop_price_per_t=crop_price,
                    area_ha=area_ha,
                    seasonal_etc_mm=etc_mm,
                    irrigation_mm=irrigation_mm,
                    effective_rainfall_mm=effective_rain,
                    non_water_variable_cost_per_ha=variable_cost,
                    fixed_cost_per_ha=fixed_cost,
                    water_price_per_m3=water_price,
                    pumping_energy_kwh_per_m3=pumping_kwh,
                    electricity_price_per_kwh=electricity_price,
                    irrigation_labour_cost_per_ha=irrigation_labour,
                    other_irrigation_cost_per_ha=other_irrigation,
                )
                scenarios = list(st.session_state.get("release2_economic_scenarios") or [])
                scenarios = [row for row in scenarios if str(row.get("Scenario")) != str(name)]
                scenarios.append(result)
                st.session_state.release2_economic_scenarios = scenarios
                st.success(f"Added scenario: {name}")
            except Exception as error:
                st.error(f"{type(error).__name__}: {error}")

    with scenarios_tab:
        scenarios = st.session_state.get("release2_economic_scenarios") or []
        if not scenarios:
            empty_state("No economic scenarios.", "Add a baseline and one or more alternatives.")
        else:
            names = [str(row.get("Scenario")) for row in scenarios]
            baseline = st.selectbox("Baseline scenario", names, key="release2_econ_baseline")
            comparison = compare_economic_scenarios(scenarios, baseline)
            st.session_state.release2_economic_comparison = comparison
            metrics = st.columns(5)
            base_row = comparison.loc[comparison["Scenario"].astype(str).eq(baseline)].iloc[0]
            metrics[0].metric("Baseline gross margin", f"{base_row['Gross margin (currency/ha)']:,.2f}")
            metrics[1].metric("Crop water productivity", f"{base_row['Crop water productivity (kg/m³ ETc)']:.3f} kg/m³")
            iwp = base_row["Irrigation water productivity (kg/m³ irrigation)"]
            metrics[2].metric("Irrigation water productivity", f"{iwp:.3f} kg/m³" if pd.notna(iwp) else "Rainfed / undefined")
            metrics[3].metric("Break-even yield", f"{base_row['Break-even yield (t/ha)']:.2f} t/ha")
            metrics[4].metric("Total irrigation", f"{base_row['Total irrigation (m³)']:,.0f} m³")
            st.dataframe(comparison, hide_index=True, width="stretch")
            chart = px.bar(
                comparison,
                x="Scenario",
                y=["Gross margin (currency/ha)", "Total irrigation cost (currency/ha)"],
                barmode="group",
                title="Economic comparison",
            )
            st.plotly_chart(chart, width="stretch")
            wp_chart = px.scatter(
                comparison,
                x="Irrigation (m³/ha)",
                y="Gross margin (currency/ha)",
                size="Yield (t/ha)",
                color="Scenario",
                title="Irrigation use versus gross margin",
            )
            st.plotly_chart(wp_chart, width="stretch")
            remove = st.multiselect("Remove scenarios", names, key="release2_econ_remove")
            if st.button("Remove selected scenarios", disabled=not remove, key="release2_econ_remove_button"):
                st.session_state.release2_economic_scenarios = [row for row in scenarios if str(row.get("Scenario")) not in remove]
                st.rerun()

    with risk_tab:
        scenarios = st.session_state.get("release2_economic_scenarios") or []
        if not scenarios:
            empty_state("No baseline scenario.", "Add at least one economic scenario.")
        else:
            names = [str(row.get("Scenario")) for row in scenarios]
            selected = st.selectbox("Scenario for Monte Carlo uncertainty", names, key="release2_econ_mc_scenario")
            row = next(item for item in scenarios if str(item.get("Scenario")) == selected)
            uncertainty = st.columns(4)
            yield_cv = float(uncertainty[0].slider("Yield CV (%)", 0, 60, 15, key="release2_econ_yield_cv"))
            price_cv = float(uncertainty[1].slider("Price CV (%)", 0, 60, 10, key="release2_econ_price_cv"))
            cost_cv = float(uncertainty[2].slider("Cost CV (%)", 0, 60, 10, key="release2_econ_cost_cv"))
            irrigation_cv = float(uncertainty[3].slider("Irrigation CV (%)", 0, 60, 10, key="release2_econ_irrigation_cv"))
            iterations = int(st.select_slider("Iterations", [500, 1000, 2500, 5000, 10000], value=5000, key="release2_econ_mc_iterations"))
            if st.button("Run economic uncertainty analysis", type="primary", width="stretch", key="release2_econ_mc_run"):
                try:
                    base_inputs = {
                        "yield_t_ha": row["Yield (t/ha)"],
                        "crop_price_per_t": row["Crop price (currency/t)"],
                        "area_ha": row["Area (ha)"],
                        "seasonal_etc_mm": row["Seasonal ETc (mm)"],
                        "irrigation_mm": row["Irrigation (mm)"],
                        "effective_rainfall_mm": row["Effective rainfall (mm)"],
                        "non_water_variable_cost_per_ha": row["Non-water variable cost (currency/ha)"],
                        "fixed_cost_per_ha": row["Fixed cost (currency/ha)"],
                        "water_price_per_m3": row["Water purchase cost (currency/ha)"] / row["Irrigation (m³/ha)"] if row["Irrigation (m³/ha)"] else 0,
                        "pumping_energy_kwh_per_m3": row["Pumping energy (kWh/ha)"] / row["Irrigation (m³/ha)"] if row["Irrigation (m³/ha)"] else 0,
                        "electricity_price_per_kwh": row["Pumping energy cost (currency/ha)"] / row["Pumping energy (kWh/ha)"] if row["Pumping energy (kWh/ha)"] else 0,
                        "irrigation_labour_cost_per_ha": row["Irrigation labour and other cost (currency/ha)"],
                        "other_irrigation_cost_per_ha": 0,
                    }
                    mc, summary = monte_carlo_economics(
                        base_inputs=base_inputs,
                        iterations=iterations,
                        yield_cv_percent=yield_cv,
                        price_cv_percent=price_cv,
                        cost_cv_percent=cost_cv,
                        irrigation_cv_percent=irrigation_cv,
                    )
                    st.session_state.release2_economic_monte_carlo = mc
                    st.session_state.release2_economic_monte_carlo_summary = summary
                    st.success("Economic uncertainty simulation completed.")
                except Exception as error:
                    st.error(f"{type(error).__name__}: {error}")
            mc = st.session_state.get("release2_economic_monte_carlo")
            summary = st.session_state.get("release2_economic_monte_carlo_summary")
            if isinstance(mc, pd.DataFrame) and not mc.empty and isinstance(summary, dict):
                cards = st.columns(5)
                cards[0].metric("Probability of profit", f"{summary['Probability of profit (%)']:.1f}%")
                cards[1].metric("Expected margin", f"{summary['Expected gross margin (currency/ha)']:,.2f}")
                cards[2].metric("Median margin", f"{summary['Median gross margin (currency/ha)']:,.2f}")
                cards[3].metric("P05 margin", f"{summary['Gross margin P05']:,.2f}")
                cards[4].metric("P95 margin", f"{summary['Gross margin P95']:,.2f}")
                distribution = px.histogram(mc, x="Gross margin (currency/ha)", nbins=60, title="Simulated gross-margin distribution")
                distribution.add_vline(x=0, line_dash="dash")
                st.plotly_chart(distribution, width="stretch")

    with export_tab:
        comparison = st.session_state.get("release2_economic_comparison")
        if not isinstance(comparison, pd.DataFrame) or comparison.empty:
            empty_state("No economic export available.", "Create and compare scenarios.")
        else:
            package = economics_export_package(
                assumptions={
                    "active_project": project.get("project_id") if project else None,
                    "crop": season.get("crop"),
                    "currency": "User-defined generic currency",
                },
                scenarios=comparison,
                monte_carlo_results=st.session_state.get("release2_economic_monte_carlo"),
                monte_carlo_summary=st.session_state.get("release2_economic_monte_carlo_summary"),
            )
            st.download_button(
                "Download economics and water-productivity package",
                package,
                file_name="release2_water_productivity_economics.zip",
                mime="application/zip",
                width="stretch",
                key="release2_econ_export",
            )
            save_label = "Save economics to Research Evidence" if project and project.get("_field_context") else "Save economic analysis to active project"
            if project and st.button(save_label, type="primary", width="stretch", key="release2_econ_save_project"):
                try:
                    if project.get("_field_context"):
                        decision_id = RESEARCH_EVIDENCE_DB.save_decision_run({
                            "decision_type": "Water productivity & economics",
                            "field_id": project.get("field_id"),
                            "objective": "Compare field-season water productivity and gross-margin scenarios",
                            "status": "Research scenario",
                            "input_snapshot": {"crop": season.get("crop"), "currency": "User-defined generic currency"},
                            "alternatives": comparison.to_dict(orient="records"),
                            "selected_alternative": {},
                            "constraints": {},
                            "metrics": {"monte_carlo_summary": st.session_state.get("release2_economic_monte_carlo_summary") or {}},
                            "provenance": {
                                "app_version": APP_VERSION,
                                "context": "Mapped field/season",
                                "recorded_costs_used_as_defaults": recorded_operation_cost_per_ha is not None,
                                "scientific_boundary": "Gross margin depends on user-entered/recorded costs and is not guaranteed farm profit.",
                            },
                        })
                        st.success(f"Economic scenario set saved to Research Evidence ({decision_id[:8]}).")
                    else:
                        updated = append_workspace_snapshot(
                            project,
                            label=f"Water economics {datetime.now().strftime('%Y-%m-%d %H:%M')}",
                            modules={
                                "scenario_comparison": comparison,
                                "monte_carlo_summary": st.session_state.get("release2_economic_monte_carlo_summary"),
                            },
                        )
                        updated = PROJECT_STORE.save(updated)
                        st.session_state.active_project = updated
                        st.success("Economic analysis saved.")
                except Exception as error:
                    st.error(f"Could not save analysis: {type(error).__name__}: {error}")
            methods_panel(
                "Water productivity is calculated from yield relative to seasonal crop water use or irrigation volume. Economic outputs combine user-entered prices and costs with biophysical scenarios.",
                [
                    "One millimetre over one hectare equals 10 cubic metres.",
                    "Gross margin is revenue minus the entered variable, fixed and irrigation costs; it is not net farm income unless all relevant costs are included.",
                    "Irrigation water productivity is undefined for a rainfed scenario with zero irrigation.",
                    "Monte Carlo results reflect only the uncertainty ranges selected by the user.",
                ],
            )

    render_chatgpt_interpretation_group([
        (
            "release2_water_economics",
            "Water-productivity and economic report",
            {
                "scenarios": st.session_state.get("release2_economic_comparison"),
                "monte_carlo_summary": st.session_state.get("release2_economic_monte_carlo_summary"),
            },
            "Interpret water productivity and financial results without assuming a currency or market context that was not supplied. Separate biophysical efficiency from profitability, identify omitted costs, discuss uncertainty assumptions, and do not present scenario results as guaranteed returns.",
        )
    ])


def _release2_ensemble_template() -> bytes:
    template = pd.DataFrame({
        "Record ID": ["location_a_2024", "location_b_2024", "location_c_2024"],
        "Observed outcome": [6.1, 4.9, 5.7],
        "Suitability model": [5.7, 4.5, 5.2],
        "AquaCrop": [6.0, 5.1, 5.8],
        "Satellite model": [6.2, 4.7, 5.6],
        "Latitude": [19.4, 20.1, 18.8],
        "Longitude": [-98.9, -101.2, -99.6],
    })
    return template.to_csv(index=False).encode("utf-8")


def _release2_validation_predictions_wide() -> pd.DataFrame:
    predictions = st.session_state.get("release2_validation_predictions")
    if not isinstance(predictions, pd.DataFrame) or predictions.empty or not {"Model", "Observed", "Prediction"}.issubset(predictions.columns):
        return pd.DataFrame()
    data = predictions.copy()
    data["_row_id"] = data.groupby("Model").cumcount()
    observed = data.groupby("_row_id")["Observed"].first()
    wide = data.pivot_table(index="_row_id", columns="Model", values="Prediction", aggfunc="first")
    wide.insert(0, "Observed", observed)
    return wide.reset_index(drop=True)


def page_model_ensemble() -> None:
    page_header(
        "Release 2 · Multi-model synthesis",
        "Model ensemble & disagreement",
        "Combine selected model outputs while retaining inter-model spread, pairwise agreement and ranking instability.",
    )
    project = _active_project()
    source_tab, setup_tab, results_tab, disagreement_tab, export_tab = st.tabs(
        ["Data", "Ensemble design", "Predictions", "Disagreement", "Export & project"]
    )

    with source_tab:
        choice = st.radio(
            "Ensemble-data source",
            ["Upload model-prediction CSV", "Use Validation Centre predictions", "Use current ensemble data"],
            horizontal=True,
            key="release2_ensemble_source_choice",
        )
        frame = pd.DataFrame()
        if choice == "Upload model-prediction CSV":
            uploaded = st.file_uploader("Upload one row per record with one column per model", type=["csv"], key="release2_ensemble_upload")
            if uploaded is not None:
                try:
                    frame = _release2_read_csv(uploaded)
                    st.session_state.release2_ensemble_source = frame
                except Exception as error:
                    st.error(str(error))
            st.download_button(
                "Download ensemble CSV template",
                _release2_ensemble_template(),
                file_name="release2_ensemble_template.csv",
                mime="text/csv",
                key="release2_ensemble_template",
            )
        elif choice == "Use Validation Centre predictions":
            frame = _release2_validation_predictions_wide()
            if not frame.empty:
                st.session_state.release2_ensemble_source = frame
            else:
                st.info("No compatible Validation Centre prediction table is available.")
        else:
            candidate = st.session_state.get("release2_ensemble_source")
            if isinstance(candidate, pd.DataFrame):
                frame = candidate.copy()
        if not frame.empty:
            st.success(f"Loaded {len(frame):,} records.")
            st.dataframe(frame.head(200), hide_index=True, width="stretch")
        else:
            empty_state("No ensemble table loaded.", "Upload a CSV or run the Validation Centre first.")

    with setup_tab:
        frame = st.session_state.get("release2_ensemble_source")
        if not isinstance(frame, pd.DataFrame) or frame.empty:
            empty_state("No ensemble data.", "Load a table in the Data tab.")
        else:
            numeric = _release2_numeric_columns(frame)
            observed_option = st.selectbox("Observed outcome, when available", ["None"] + numeric, key="release2_ensemble_observed")
            observed_column = None if observed_option == "None" else observed_option
            model_options = [column for column in numeric if column != observed_column]
            models = st.multiselect(
                "Model columns",
                model_options,
                default=model_options[: min(4, len(model_options))],
                key="release2_ensemble_models",
            )
            method = st.selectbox(
                "Ensemble method",
                ["Mean", "Median", "Trimmed mean", "Weighted mean", "Inverse-error weighted"],
                key="release2_ensemble_method",
            )
            weight_map = None
            if method == "Weighted mean" and models:
                st.caption("Weights are normalised automatically.")
                weight_columns = st.columns(min(4, len(models)))
                weight_map = {}
                for index, model in enumerate(models):
                    weight_map[model] = float(weight_columns[index % len(weight_columns)].number_input(
                        f"{model} weight",
                        min_value=0.0,
                        value=1.0,
                        step=0.1,
                        key=f"release2_weight_{hashlib.sha1(model.encode()).hexdigest()[:8]}",
                    ))
            elif method == "Inverse-error weighted":
                validation_metrics = st.session_state.get("release2_validation_metrics")
                if isinstance(validation_metrics, pd.DataFrame) and not validation_metrics.empty and "RMSE" in validation_metrics.columns:
                    try:
                        available_metrics = validation_metrics.loc[validation_metrics["Model"].astype(str).isin(models)]
                        weight_map = inverse_error_weights(available_metrics)
                        st.dataframe(pd.DataFrame({"Model": list(weight_map), "Validation-derived weight": list(weight_map.values())}), hide_index=True)
                    except Exception as error:
                        st.warning(f"Could not derive inverse-error weights: {error}")
                else:
                    st.warning("Run continuous Validation Centre analysis first, or select another ensemble method.")
            id_option = st.selectbox("Record identifier", ["None"] + [str(column) for column in frame.columns], key="release2_ensemble_id")
            id_column = None if id_option == "None" else id_option
            higher_is_better = st.checkbox("Higher predictions indicate better outcomes", value=True, key="release2_ensemble_higher")
            threshold_enabled = st.checkbox("Calculate model consensus around a threshold", key="release2_ensemble_consensus_enabled")
            threshold = float(st.number_input("Consensus threshold", value=60.0, key="release2_ensemble_threshold")) if threshold_enabled else None
            direction = st.radio("Consensus condition", ["Above", "Below"], horizontal=True, key="release2_ensemble_direction") if threshold_enabled else "Above"

            if st.button("Calculate ensemble and disagreement", type="primary", width="stretch", disabled=len(models) < 2, key="release2_ensemble_run"):
                try:
                    results, weights = calculate_ensemble(
                        frame,
                        model_columns=models,
                        method=method,
                        weights=weight_map,
                        observed_column=observed_column,
                    )
                    pairwise = model_pairwise_agreement(frame, models)
                    ranking, rank_correlations = ranking_disagreement(
                        frame,
                        model_columns=models,
                        id_column=id_column,
                        higher_is_better=higher_is_better,
                    )
                    if threshold_enabled:
                        consensus = consensus_classification(frame, model_columns=models, threshold=threshold, direction=direction)
                        results = pd.concat([results.reset_index(drop=True), consensus.reset_index(drop=True)], axis=1)
                    settings = {
                        "models": models,
                        "method": method,
                        "observed_column": observed_column,
                        "id_column": id_column,
                        "higher_is_better": higher_is_better,
                        "consensus_threshold": threshold,
                        "consensus_direction": direction if threshold_enabled else None,
                    }
                    st.session_state.release2_ensemble_results = results
                    st.session_state.release2_ensemble_weights = weights
                    st.session_state.release2_ensemble_pairwise = pairwise
                    st.session_state.release2_ensemble_ranking = ranking
                    st.session_state.release2_ensemble_rank_correlations = rank_correlations
                    st.session_state.release2_ensemble_settings = settings
                    st.success("Ensemble analysis completed.")
                except Exception as error:
                    st.error(f"{type(error).__name__}: {error}")

    with results_tab:
        results = st.session_state.get("release2_ensemble_results")
        weights = st.session_state.get("release2_ensemble_weights")
        settings = st.session_state.get("release2_ensemble_settings") or {}
        if not isinstance(results, pd.DataFrame) or results.empty:
            empty_state("No ensemble results.", "Configure and run an ensemble.")
        else:
            cards = st.columns(5)
            cards[0].metric("Records", f"{len(results):,}")
            cards[1].metric("Models", len(settings.get("models", [])))
            cards[2].metric("Median disagreement", f"{results['Relative disagreement (%)'].median():.1f}%")
            cards[3].metric("Highest disagreement", f"{results['Relative disagreement (%)'].max():.1f}%")
            cards[4].metric("Complete-model records", f"{int((results['Models available'] == len(settings.get('models', []))).sum()):,}")
            if isinstance(weights, pd.DataFrame):
                st.dataframe(weights, hide_index=True, width="stretch")
            st.dataframe(results.head(1000), hide_index=True, width="stretch")
            observed_column = settings.get("observed_column")
            if observed_column and observed_column in results.columns:
                chart = px.scatter(
                    results,
                    x=observed_column,
                    y="Ensemble prediction",
                    color="Relative disagreement (%)",
                    title="Observed outcome versus ensemble prediction",
                )
                values = pd.concat([pd.to_numeric(results[observed_column], errors="coerce"), results["Ensemble prediction"]]).dropna()
                if not values.empty:
                    chart.add_shape(type="line", x0=values.min(), y0=values.min(), x1=values.max(), y1=values.max(), line=dict(dash="dash"))
                st.plotly_chart(chart, width="stretch")
                ensemble_metrics = release2_regression_metrics(results[observed_column], results["Ensemble prediction"])
                st.json(ensemble_metrics)

    with disagreement_tab:
        pairwise = st.session_state.get("release2_ensemble_pairwise")
        ranking = st.session_state.get("release2_ensemble_ranking")
        correlations = st.session_state.get("release2_ensemble_rank_correlations")
        results = st.session_state.get("release2_ensemble_results")
        if not isinstance(pairwise, pd.DataFrame) or pairwise.empty:
            empty_state("No disagreement analysis.", "Run an ensemble first.")
        else:
            st.markdown("### Pairwise model agreement")
            st.dataframe(pairwise, hide_index=True, width="stretch")
            if isinstance(correlations, pd.DataFrame) and not correlations.empty:
                heatmap = px.imshow(correlations, text_auto=".2f", zmin=-1, zmax=1, title="Spearman agreement among model rankings")
                st.plotly_chart(heatmap, width="stretch")
            if isinstance(ranking, pd.DataFrame) and not ranking.empty:
                st.markdown("### Records with unstable model rankings")
                st.dataframe(ranking.sort_values("Rank range", ascending=False).head(100), hide_index=True, width="stretch")
            if isinstance(results, pd.DataFrame):
                distribution = px.histogram(results, x="Relative disagreement (%)", nbins=50, title="Inter-model disagreement distribution")
                st.plotly_chart(distribution, width="stretch")

    with export_tab:
        results = st.session_state.get("release2_ensemble_results")
        settings = st.session_state.get("release2_ensemble_settings") or {}
        if not isinstance(results, pd.DataFrame) or results.empty:
            empty_state("No ensemble export.", "Run an ensemble.")
        else:
            package = ensemble_export_package(
                settings=settings,
                ensemble_results=results,
                weights=st.session_state.get("release2_ensemble_weights"),
                pairwise_agreement=st.session_state.get("release2_ensemble_pairwise"),
                ranking_results=st.session_state.get("release2_ensemble_ranking"),
                ranking_correlations=st.session_state.get("release2_ensemble_rank_correlations"),
            )
            st.download_button(
                "Download ensemble research package",
                package,
                file_name="release2_model_ensemble_package.zip",
                mime="application/zip",
                width="stretch",
                key="release2_ensemble_export",
            )
            if project and st.button("Save ensemble snapshot to active project", type="primary", width="stretch", key="release2_ensemble_save_project"):
                try:
                    updated = append_workspace_snapshot(
                        project,
                        label=f"Model ensemble {datetime.now().strftime('%Y-%m-%d %H:%M')}",
                        modules={
                            "ensemble_settings": settings,
                            "ensemble_weights": st.session_state.get("release2_ensemble_weights"),
                            "ensemble_summary": results.head(500),
                            "pairwise_agreement": st.session_state.get("release2_ensemble_pairwise"),
                        },
                    )
                    updated = PROJECT_STORE.save(updated)
                    st.session_state.active_project = updated
                    st.success("Ensemble snapshot saved.")
                except Exception as error:
                    st.error(f"Could not save ensemble: {type(error).__name__}: {error}")
            methods_panel(
                "The ensemble combines the selected model outputs row by row. Disagreement is retained as a result rather than interpreted as random uncertainty automatically.",
                [
                    "An unweighted ensemble assumes equal model credibility.",
                    "Inverse-error weights require comparable, independent validation metrics.",
                    "The model P10–P90 range is inter-model spread, not a calibrated confidence interval.",
                    "Models sharing data, equations or biases are not statistically independent.",
                ],
            )

    render_chatgpt_interpretation_group([
        (
            "release2_model_ensemble",
            "Model ensemble and disagreement report",
            {
                "settings": st.session_state.get("release2_ensemble_settings"),
                "weights": st.session_state.get("release2_ensemble_weights"),
                "pairwise_agreement": st.session_state.get("release2_ensemble_pairwise"),
                "results": _compact_frame(st.session_state.get("release2_ensemble_results"), 30),
            },
            "Interpret ensemble results without implying that averaging removes structural model bias. Discuss model dependence, validation-derived versus arbitrary weights, inter-model disagreement, ranking instability and records where the ensemble should be treated cautiously.",
        )
    ])




