def _release3_weather_source_frame() -> tuple[pd.DataFrame | None, str]:
    # Prefer persisted field/Twin evidence so external crop-model preparation is not
    # dependent on a particular Streamlit session still holding a legacy analysis.
    field_id = st.session_state.get("field_ops_active_field_id")
    if field_id:
        try:
            links = AGROLATTICE_TWIN_DB.links()
            if isinstance(links, pd.DataFrame) and not links.empty and "field_id" in links:
                hit = links.loc[links["field_id"].astype(str).eq(str(field_id))]
                if not hit.empty:
                    weather = AGROLATTICE_TWIN_DB.weather(str(hit.iloc[0]["link_id"]))
                    if isinstance(weather, pd.DataFrame) and not weather.empty:
                        return weather.copy(), "Saved field/Twin weather evidence"
        except Exception:
            pass
    candidates = [
        (st.session_state.get("phenology_weather"), "Current phenology weather in memory"),
        (st.session_state.get("daily_weather_derived"), "Current daily weather in memory"),
        (st.session_state.get("soil_water_raw_weather"), "Current root-zone weather in memory"),
        (st.session_state.get("aquacrop_weather"), "AquaCrop-prepared weather"),
    ]
    for candidate, label in candidates:
        if isinstance(candidate, pd.DataFrame) and not candidate.empty:
            return candidate.copy(), label
    return None, "Unavailable"


def _release3_project_location(project: dict | None) -> tuple[str, float, float, float]:
    if project:
        location = (project or {}).get("location", {}) or {}
        return (
            str(location.get("name") or "AgroLattice site"),
            float(location.get("latitude") or ACTIVE_COUNTRY_MAP_CENTRE[0]),
            float(location.get("longitude") or ACTIVE_COUNTRY_MAP_CENTRE[1]),
            float(location.get("elevation_m") or 0.0),
        )
    field_id = st.session_state.get("field_ops_active_field_id")
    if field_id:
        try:
            field = FIELD_OPERATIONS_DB.field(str(field_id))
        except Exception:
            field = None
        if field:
            lat = pd.to_numeric(field.get("centroid_lat"), errors="coerce")
            lon = pd.to_numeric(field.get("centroid_lon"), errors="coerce")
            if pd.notna(lat) and pd.notna(lon):
                return (str(field.get("name") or field_id), float(lat), float(lon), 0.0)
    return ("AgroLattice site", float(ACTIVE_COUNTRY_MAP_CENTRE[0]), float(ACTIVE_COUNTRY_MAP_CENTRE[1]), 0.0)


def _release3_run_directory(model: str) -> Path:
    token = datetime.now().strftime("%Y%m%d_%H%M%S_%f")
    directory = external_model_run_root / model.casefold() / token
    directory.mkdir(parents=True, exist_ok=True)
    return directory


def page_dssat_apsim_interoperability() -> None:
    page_header(
        "Crop models · External process-model interoperability",
        "DSSAT & APSIM interoperability",
        "Prepare traceable field-aware weather packages, execute locally installed model templates, and import model outputs without silently rewriting fragile experiment definitions.",
    )
    project = _active_project()
    site_name, latitude, longitude, elevation = _release3_project_location(project)
    st.warning(
        "DSSAT and APSIM remain separate scientific models. This page does not validate cultivar, soil, management, nitrogen or experiment settings automatically. "
        "Prepared model templates must be reviewed by a user familiar with the selected model."
    )
    weather_tab, package_tab, dssat_tab, apsim_tab, outputs_tab, methods_tab = st.tabs(
        ["Weather & readiness", "Prepare packages", "Run DSSAT", "Run APSIM", "Outputs & evidence", "Methods"]
    )

    with weather_tab:
        source_frame, source_label = _release3_weather_source_frame()
        source_choice = st.radio(
            "Daily weather source",
            ["Use current app daily weather", "Upload daily-weather CSV"],
            horizontal=True,
            key="release3_weather_source_choice",
        )
        if source_choice == "Upload daily-weather CSV":
            upload = st.file_uploader(
                "Upload daily CSV containing date, minimum temperature, maximum temperature, rainfall and solar radiation",
                type=["csv"],
                key="release3_weather_upload",
            )
            if upload is not None:
                try:
                    source_frame = pd.read_csv(upload)
                    source_label = "Uploaded CSV"
                except Exception as error:
                    st.error(f"Could not read weather CSV: {error}")
                    source_frame = None
        else:
            st.caption(f"Detected source: {source_label}")
        if isinstance(source_frame, pd.DataFrame) and not source_frame.empty:
            try:
                prepared = prepare_external_model_weather(source_frame)
                st.session_state.release3_external_weather = prepared
                st.session_state.release3_external_weather_metadata = {
                    "source": source_label,
                    "site": site_name,
                    "latitude": latitude,
                    "longitude": longitude,
                    "start": str(prepared["Date"].min().date()),
                    "end": str(prepared["Date"].max().date()),
                    "rows": len(prepared),
                }
                cards = st.columns(5)
                cards[0].metric("Days", f"{len(prepared):,}")
                cards[1].metric("Start", str(prepared["Date"].min().date()))
                cards[2].metric("End", str(prepared["Date"].max().date()))
                cards[3].metric("Rainfall", f"{prepared['Rain'].sum():,.1f} mm")
                cards[4].metric("Mean temperature", f"{((prepared['Tmin'] + prepared['Tmax']) / 2).mean():.1f} °C")
                st.dataframe(prepared.head(200), hide_index=True, width="stretch")
            except Exception as error:
                st.error(f"{type(error).__name__}: {error}")
        else:
            empty_state("No daily weather available.", "Link/retrieve field weather in Climate & Earth Observation, run a current crop-weather analysis, or upload a daily-weather CSV.")

    with package_tab:
        weather = st.session_state.get("release3_external_weather")
        if not isinstance(weather, pd.DataFrame) or weather.empty:
            empty_state("No prepared daily weather.", "Load weather in the Weather tab.")
        else:
            location_controls = st.columns(4)
            package_site = location_controls[0].text_input("Site name", value=site_name, key="release3_package_site")
            package_lat = float(location_controls[1].number_input("Latitude", -90.0, 90.0, latitude, format="%.6f", key="release3_package_lat"))
            package_lon = float(location_controls[2].number_input("Longitude", -180.0, 180.0, longitude, format="%.6f", key="release3_package_lon"))
            package_elevation = float(location_controls[3].number_input("Elevation (m)", value=elevation, key="release3_package_elevation"))
            station_code = st.text_input("Four-character DSSAT station code", value="MX01", max_chars=4, key="release3_station_code")
            base_apsimx = st.file_uploader("Optional APSIMX template", type=["apsimx"], key="release3_base_apsimx")
            apsim_selectors = st.columns(2)
            weather_selector = apsim_selectors[0].text_input("APSIM Weather selector", value="[Weather]", key="release3_weather_selector")
            clock_selector = apsim_selectors[1].text_input("APSIM Clock selector", value="[Clock]", key="release3_clock_selector")
            if st.button("Generate DSSAT and APSIM input packages", type="primary", width="stretch", key="release3_generate_model_packages"):
                try:
                    dssat_text = dssat_weather_text(
                        weather,
                        station_code=station_code,
                        station_name=package_site,
                        latitude=package_lat,
                        longitude=package_lon,
                        elevation_m=package_elevation,
                    )
                    apsim_text = apsim_met_text(
                        weather,
                        site_name=package_site,
                        latitude=package_lat,
                        longitude=package_lon,
                    )
                    start = str(weather["Date"].min().date())
                    end = str(weather["Date"].max().date())
                    metadata = {
                        "generated_utc": datetime.now(timezone.utc).isoformat(),
                        "project_id": project.get("project_id") if project else None,
                        "field_id": st.session_state.get("field_ops_active_field_id"),
                        "site": package_site,
                        "latitude": package_lat,
                        "longitude": package_lon,
                        "elevation_m": package_elevation,
                        "weather_start": start,
                        "weather_end": end,
                        "source": st.session_state.get("release3_external_weather_metadata"),
                    }
                    st.session_state.release3_dssat_package = interoperability_package(
                        model="DSSAT",
                        weather_filename=f"{station_code.upper()[:4]}0001.WTH",
                        weather_text=dssat_text,
                        metadata=metadata,
                        command_files={
                            "RUN_DSSAT_TEMPLATE.bat": "@echo off\nREM Edit executable/module/batch names before running.\nREM C:\\DSSAT48\\DSCSM048.EXE CSCER048 B DSSBatch.v48\n",
                            "DSSBatch_TEMPLATE.v48": "$BATCH(DSSAT48)\n! Add prepared experiment FileX paths and treatment numbers using DSSAT tools.\n",
                        },
                    )
                    base_files = {base_apsimx.name: base_apsimx.getvalue()} if base_apsimx is not None else {}
                    command_files = {}
                    if base_apsimx is not None:
                        command_files["configure_and_run.txt"] = apsim_command_text(
                            base_apsimx=base_apsimx.name,
                            output_apsimx="configured_simulation.apsimx",
                            weather_filename=f"{country_slug(selected_country)}_agroclimate.met",
                            start_date=start,
                            end_date=end,
                            weather_selector=weather_selector,
                            clock_selector=clock_selector,
                        )
                    st.session_state.release3_apsim_package = interoperability_package(
                        model="APSIM Next Generation",
                        weather_filename=f"{country_slug(selected_country)}_agroclimate.met",
                        weather_text=apsim_text,
                        metadata=metadata,
                        base_files=base_files,
                        command_files=command_files,
                    )
                    st.success("Model input packages generated.")
                except Exception as error:
                    st.error(f"{type(error).__name__}: {error}")
            downloads = st.columns(2)
            if st.session_state.get("release3_dssat_package"):
                downloads[0].download_button("Download DSSAT package", st.session_state.release3_dssat_package, file_name="dssat_interoperability_package.zip", mime="application/zip", width="stretch", key="release3_download_dssat_package")
            if st.session_state.get("release3_apsim_package"):
                downloads[1].download_button("Download APSIM package", st.session_state.release3_apsim_package, file_name="apsim_interoperability_package.zip", mime="application/zip", width="stretch", key="release3_download_apsim_package")

    with dssat_tab:
        st.markdown("### Execute a prepared DSSAT batch package")
        candidates = common_executable_candidates()["DSSAT"]
        dssat_exe = st.text_input("DSSAT executable path", value=next((item for item in candidates if Path(item).exists()), "C:\\DSSAT48\\DSCSM048.EXE"), key="release3_dssat_exe")
        controls = st.columns(3)
        crop_module = controls[0].text_input("Crop module", value="CSCER048", key="release3_dssat_module")
        batch_filename = controls[1].text_input("Batch filename", value="DSSBatch.v48", key="release3_dssat_batch")
        control_filename = controls[2].text_input("External control file (optional)", value="", key="release3_dssat_control")
        dssat_zip = st.file_uploader("Upload prepared DSSAT run package (.zip)", type=["zip"], key="release3_dssat_run_zip")
        timeout = int(st.number_input("DSSAT timeout (seconds)", 30, 86400, 1800, 30, key="release3_dssat_timeout"))
        status = external_executable_status(dssat_exe, "DSSAT")
        st.caption(f"Executable exists: {status['exists']}")
        if st.button("Prepare DSSAT working directory", disabled=dssat_zip is None, width="stretch", key="release3_prepare_dssat_workdir"):
            try:
                workdir = _release3_run_directory("dssat")
                safe_extract_zip(dssat_zip.getvalue(), workdir)
                st.session_state.release3_dssat_workdir = str(workdir)
                st.success(f"Prepared: {workdir}")
            except Exception as error:
                st.error(f"{type(error).__name__}: {error}")
        if st.session_state.get("release3_dssat_workdir"):
            st.code(st.session_state.release3_dssat_workdir)
            if st.button("Run DSSAT", type="primary", width="stretch", key="release3_run_dssat"):
                try:
                    run = run_dssat(
                        executable=dssat_exe,
                        crop_module=crop_module,
                        batch_filename=batch_filename,
                        working_directory=st.session_state.release3_dssat_workdir,
                        external_control_filename=control_filename or None,
                        timeout_seconds=timeout,
                    )
                    outputs = parse_output_directory(st.session_state.release3_dssat_workdir, "DSSAT")
                    st.session_state.release3_dssat_run = run
                    st.session_state.release3_dssat_outputs = outputs
                    st.success(f"DSSAT finished with return code {run['return_code']}.")
                    st.code((run.get("stdout") or "")[-5000:])
                    if run.get("stderr"):
                        st.error((run.get("stderr") or "")[-5000:])
                except Exception as error:
                    st.error(f"{type(error).__name__}: {error}")

    with apsim_tab:
        st.markdown("### Execute an APSIM Next Generation package")
        apsim_candidates = common_executable_candidates()["APSIM"]
        apsim_exe = st.text_input("APSIM Models.exe path", value=next((item for item in apsim_candidates if Path(item).exists()), "C:\\Program Files\\APSIM2026.7.0\\bin\\Models.exe"), key="release3_apsim_exe")
