def page_study_publication_builder() -> None:
    page_header(
        "Legacy publication builder",
        "Study & publication builder",
        "Legacy session-state/project workflow retained for backward compatibility. Use Reports for the persistent 11.19 reporting and publication workflow.",
    )
    project = _active_project()
    st.warning("Generated manuscript text is a structured draft. Every numerical claim, table, method and citation must be reviewed by the authors before submission.")
    library_tab, protocol_tab, artifacts_tab, figures_tab, build_tab = st.tabs(
        ["Study library", "Protocol", "Tables", "Figures", "Build package"]
    )

    with library_tab:
        library = STUDY_STORE.list_studies()
        if not library.empty:
            st.dataframe(library, hide_index=True, width="stretch")
            selected_id = st.selectbox("Load study", library["Study ID"].dropna().astype(str).tolist(), key="release3_load_study_id")
            if st.button("Load selected study", width="stretch", key="release3_load_study_button"):
                try:
                    st.session_state.release3_active_study = STUDY_STORE.load(selected_id)
                    st.success("Study loaded.")
                except Exception as error:
                    st.error(f"{type(error).__name__}: {error}")
        else:
            st.info("No saved studies yet.")
        new_title = st.text_input("New study title", value=f"Integrated agroclimate modelling and validation in {selected_country}", key="release3_new_study_title")
        if st.button("Create new study", type="primary", width="stretch", key="release3_create_study"):
            study = new_study_template(title=new_title, project_id=project.get("project_id") if project else None)
            study = STUDY_STORE.save(study)
            st.session_state.release3_active_study = study
            st.success("Study created.")

    study = st.session_state.get("release3_active_study")
    if not isinstance(study, dict):
        with protocol_tab:
            empty_state("No active study.", "Create or load a study in the Study library tab.")
        with artifacts_tab:
            empty_state("No active study.", "Create or load a study first.")
        with figures_tab:
            empty_state("No active study.", "Create or load a study first.")
        with build_tab:
            empty_state("No active study.", "Create or load a study first.")
        return

    with protocol_tab:
        with st.form("release3_study_protocol_form"):
            title = st.text_input("Title", value=study.get("title", ""), key="release3_study_title")
            short_title = st.text_input("Short title", value=study.get("short_title", ""), key="release3_study_short_title")
            authors = st.text_area("Authors, one per line", value="\n".join(study.get("authors", [])), key="release3_study_authors")
            journal = st.text_input("Target journal", value=study.get("journal", ""), key="release3_study_journal")
            research_question = st.text_area("Research question", value=study.get("research_question", ""), key="release3_study_question")
            design = st.text_area("Study design", value=study.get("study_design", ""), key="release3_study_design")
            methods = st.multiselect("Methods included", list(PUBLICATION_METHODS_REGISTRY), default=study.get("selected_methods", []), key="release3_study_methods")
            intro = st.text_area("Introduction draft", value=study.get("introduction", ""), height=180, key="release3_study_intro")
            discussion = st.text_area("Discussion draft", value=study.get("discussion", ""), height=180, key="release3_study_discussion")
            conclusion = st.text_area("Conclusion draft", value=study.get("conclusion", ""), height=100, key="release3_study_conclusion")
            save = st.form_submit_button("Save study protocol", type="primary", width="stretch")
        if save:
            updated = deepcopy(study)
            updated.update({
                "title": title,
                "short_title": short_title,
                "authors": [line.strip() for line in authors.splitlines() if line.strip()],
                "journal": journal,
                "research_question": research_question,
                "study_design": design,
                "selected_methods": methods,
                "introduction": intro,
                "discussion": discussion,
                "conclusion": conclusion,
            })
            try:
                updated = STUDY_STORE.save(updated)
                st.session_state.release3_active_study = updated
                study = updated
                st.success("Study protocol saved.")
            except Exception as error:
                st.error(f"{type(error).__name__}: {error}")

    catalog, frame_map = publication_artifact_catalog(project, _release3_session_artifacts())
    with artifacts_tab:
        if catalog.empty:
            empty_state("No tabular artifacts were found.", "Save project snapshots or run analyses first.")
        else:
            st.dataframe(catalog, hide_index=True, width="stretch")
            selected = st.multiselect("Tables to include", catalog["Artifact"].tolist(), default=st.session_state.get("release3_selected_artifacts", []), key="release3_table_artifacts")
            st.session_state.release3_selected_artifacts = selected
            for index, name in enumerate(selected, start=1):
                frame = frame_map.get(name)
                if isinstance(frame, pd.DataFrame):
                    with st.expander(f"Table {index}: {name}", expanded=False):
                        st.dataframe(frame.head(100), hide_index=True, width="stretch")
                        st.caption(f"{len(frame):,} rows × {len(frame.columns):,} columns")

    with figures_tab:
        if catalog.empty:
            empty_state("No data available for figures.", "Run or save analyses first.")
        else:
            artifact_name = st.selectbox("Figure data", catalog["Artifact"].tolist(), key="release3_figure_artifact")
            frame = frame_map.get(artifact_name)
            if isinstance(frame, pd.DataFrame) and not frame.empty:
                columns = [str(c) for c in frame.columns]
                numeric_columns = [c for c in columns if pd.to_numeric(frame[c], errors="coerce").notna().sum() >= 2]
                controls = st.columns(4)
                chart_type = controls[0].selectbox("Chart type", ["Line", "Scatter", "Bar", "Box"], key="release3_figure_type")
                x_column = controls[1].selectbox("X column", columns, key="release3_figure_x")
                y_columns = controls[2].multiselect("Y column(s)", numeric_columns, default=numeric_columns[:1], key="release3_figure_y")
                group_choice = controls[3].selectbox("Group", ["None"] + columns, key="release3_figure_group")
                figure_title = st.text_input("Figure title", value=artifact_name.split(".")[-1].replace("_", " ").title(), key="release3_figure_title")
                caption = st.text_area("Figure caption", value="", key="release3_figure_caption")
                if st.button("Generate publication figure", type="primary", width="stretch", disabled=not y_columns, key="release3_generate_figure"):
                    try:
                        png = publication_figure_png(
                            frame,
                            chart_type=chart_type,
                            x_column=x_column,
                            y_columns=y_columns,
                            group_column=None if group_choice == "None" else group_choice,
                            title=figure_title,
                            dpi=300,
                        )
                        figures = list(st.session_state.get("release3_publication_figures") or [])
                        figures.append({"title": figure_title, "caption": caption, "artifact": artifact_name, "png": png})
                        st.session_state.release3_publication_figures = figures
                        st.success("Figure added.")
                    except Exception as error:
                        st.error(f"{type(error).__name__}: {error}")
            figures = st.session_state.get("release3_publication_figures") or []
            for index, figure in enumerate(figures, start=1):
                st.image(figure["png"], caption=f"Figure {index}. {figure.get('caption') or figure.get('title')}")
            if figures and st.button("Clear generated figures", key="release3_clear_figures"):
                st.session_state.release3_publication_figures = []
                st.rerun()

    with build_tab:
        selected_names = st.session_state.get("release3_selected_artifacts") or []
        figures = st.session_state.get("release3_publication_figures") or []
        selected_tables = []
        for name in selected_names:
            frame = frame_map.get(name)
            if isinstance(frame, pd.DataFrame):
                selected_tables.append({
                    "title": name.split(".")[-1].replace("_", " ").title(),
                    "caption": f"Selected output from {name}.",
                    "narrative": "[[Insert a checked interpretation of the principal pattern and numerical findings.]]",
                    "frame": frame,
                })
        reproducibility = {
            "app_version": APP_VERSION,
            "generated_utc": datetime.now(timezone.utc).isoformat(),
            "project_id": project.get("project_id") if project else None,
            "study_id": study.get("study_id"),
            "selected_methods": study.get("selected_methods", []),
            "selected_artifacts": selected_names,
            "figure_count": len(figures),
            "climate_dataset": str(climate_file),
            "climate_dataset_sha256": updater_sha256_file(climate_file) if climate_file.exists() else None,
            "python": sys.version,
            "platform": platform.platform(),
        }
        st.json(reproducibility)
        if st.button("Build complete publication package", type="primary", width="stretch", key="release3_build_publication"):
            try:
                package = build_publication_package(
                    study=study,
                    selected_methods=study.get("selected_methods", []),
                    selected_tables=selected_tables,
                    figures=figures,
                    reproducibility=reproducibility,
                    project=project,
                )
                st.session_state.release3_publication_package = package
                st.session_state.release3_publication_manifest = reproducibility
                st.success("Publication package built.")
            except Exception as error:
                st.error(f"{type(error).__name__}: {error}")
        if st.session_state.get("release3_publication_package"):
            st.download_button(
                "Download publication package",
                st.session_state.release3_publication_package,
                file_name=f"{study.get('short_title','agroclimate-study').replace(' ','_')}_publication_package.zip",
                mime="application/zip",
                width="stretch",
                key="release3_download_publication",
            )
        methods_panel(
            "The publication builder exports a deterministic manuscript skeleton and selected results. It preserves a reproducibility manifest and parameter provenance, but it does not replace author verification, statistical review or journal formatting checks.",
            [
                "DOCX, Markdown and HTML manuscript drafts are included.",
                "Tables are exported in full as CSV, while manuscript previews are truncated for readability.",
                "Generated figures use 300-dpi PNG output and should be checked against journal specifications.",
                "Methods text is selected from a transparent registry and must be reconciled with the exact final analysis settings.",
            ],
        )

    render_chatgpt_interpretation_group([
        (
            "release3_publication_builder",
            "Publication-package scientific audit",
            {
                "study": study,
                "selected_artifacts": st.session_state.get("release3_selected_artifacts"),
                "figure_register": [{k: v for k, v in item.items() if k != "png"} for item in (st.session_state.get("release3_publication_figures") or [])],
                "reproducibility": st.session_state.get("release3_publication_manifest"),
            },
            "Audit the proposed study and publication package. Identify unsupported claims, missing validation, mismatches between research question and selected analyses, absent provenance, risks of selective reporting, and sections that still contain placeholders. Do not invent results or references.",
        )
    ])



