RELEASE4_UI_PATCH_APPLIED = True


def _release4_state_snapshot() -> dict:
    try:
        keys = list(st.session_state.keys())
    except Exception:
        keys = []
    return {key: st.session_state.get(key) for key in keys}


def _release4_recent_runs(active_project: dict | None) -> pd.DataFrame:
    if not isinstance(active_project, dict):
        return pd.DataFrame()
    rows = []
    for run in reversed(active_project.get("model_runs", []) or []):
        if not isinstance(run, dict):
            continue
        timestamp = run.get("timestamp") or (run.get("run") or {}).get("finished_utc") or run.get("created_at")
        rows.append({
            "Model / backend": run.get("backend") or (run.get("run") or {}).get("model") or "Model run",
            "Crop": run.get("crop") or (active_project.get("season") or {}).get("crop"),
            "Completed": str(timestamp or ""),
            "Run ID": str(run.get("run_id") or "")[:16],
        })
    return pd.DataFrame(rows)


def _release4_dataset_detail() -> str:
    if not climate_file.exists():
        return "Historical climate CSV is missing."
    latest_year = int(climate_df_long["Year"].max()) if not climate_df_long.empty else None
    months = climate_df_long.loc[climate_df_long["Year"].eq(latest_year), "Month"].dropna().astype(str).unique().tolist() if latest_year else []
    return f"Available through {latest_year}; {len(months)} month labels in the latest year." if latest_year else "Dataset is present but no valid year was detected."


def _release4_context() -> dict:
    active_project = None
    try:
        active_project = _active_project()
    except Exception:
        active_project = st.session_state.get("active_project")
    try:
        project_library = PROJECT_STORE.list_projects().sort_values("Updated", ascending=False)
    except Exception:
        project_library = pd.DataFrame()
    try:
        aquacrop_status = aquacrop_dependency_status()
    except Exception as error:
        aquacrop_status = {"installed": False, "message": f"Status check failed: {error}"}
    try:
        satellite_status_raw = satellite_dependency_status()
        satellite_status = {
            "ready": not bool(satellite_status_raw.get("Missing required packages")),
            "message": "Satellite dependencies available." if not satellite_status_raw.get("Missing required packages") else str(satellite_status_raw.get("Missing required packages")),
        }
    except Exception as error:
        satellite_status = {"ready": False, "message": f"Status check failed: {error}"}
    try:
        field_operations_status = FIELD_OPERATIONS_DB.portfolio_summary()
    except Exception as error:
        field_operations_status = {"farms": 0, "fields": 0, "open_tasks": 0, "open_alerts": 0, "error": str(error)}
    try:
        twin_links = AGROLATTICE_TWIN_DB.links()
        twin_status = {
            "twins": int(len(twin_links)),
            "snapshots": int(sum(len(AGROLATTICE_TWIN_DB.snapshots(str(link_id))) for link_id in twin_links.get("link_id", pd.Series(dtype=str)).astype(str))) if not twin_links.empty else 0,
            "ready": not twin_links.empty,
        }
    except Exception as error:
        twin_status = {"twins": 0, "snapshots": 0, "ready": False, "error": str(error)}
    coverage = merged_df_long[["CITY", "STATE"]].drop_duplicates()
    state = _release4_state_snapshot()
    return {
        "app_version": APP_VERSION,
        "active_project": active_project,
        "project_library": project_library,
        "recent_runs": _release4_recent_runs(active_project),
        "state": state,
        "coverage": {
            "country": selected_country,
            "locations": int(len(coverage)),
            "states": int(coverage["STATE"].nunique()),
            "period": f"{min(years)}–{max(years)}" if years else "Unavailable",
            "variables": int(len(available_variables)),
            "usable_percent": float(100.0 * merged_df_long["Value"].notna().mean()),
        },
        "available_variables": available_variables,
        "dataset_exists": climate_file.exists(),
        "dataset_detail": _release4_dataset_detail(),
        "aquacrop_status": aquacrop_status,
        "satellite_status": satellite_status,
        "field_operations_status": field_operations_status,
        "agrolattice_twin_status": twin_status,
        "paths": {
            "Active country climate dataset": climate_file,
            "Global cities dataset": cities_file,
            "Country settings": data_dir / "global_country_settings.json",
            "Cache directory": cache_dir,
            "Daily weather cache": daily_weather_cache_dir,
            "Satellite cache": satellite_cache_dir,
            "Dataset update workspace": dataset_update_root,
            "Project store": project_store_root,
            "Study store": study_store_root,
            "External model runs": external_model_run_root,
            "Maize flowering synchrony database": pollination_lab_root,
            "Field operations database and attachments": field_operations_root,
            "AgroLattice Twin database": agrolattice_twin_root,
            "Research evidence database and model artifacts": research_evidence_root,
        },
    }


