def page_country_workspace() -> None:
    page_header(
        "Release 9 · Global workspace",
        f"{selected_country} country workspace",
        "Search locations on the map, manage a country-specific climate dataset, and use the selected country as the default context for new field records and NASA downloads.",
    )
    status = DATASET_STATUS
    catalogue = country_cities
    metrics = st.columns(4)
    metrics[0].metric("Country", selected_country)
    metrics[1].metric("Catalogue locations", f"{len(catalogue):,}")
    metrics[2].metric("Installed climate locations", f"{status['locations']:,}")
    metrics[3].metric("Historical rows", f"{status['rows']:,}")

    if DATASET_READY:
        st.success(
            f"The {selected_country} historical climate dataset is active. Climate explorer, crop, risk and research pages are available."
        )
    else:
        st.warning(
            f"No historical monthly dataset has been installed for {selected_country}. "
            "Open **Dataset updater**, choose this country, select cities or administrative regions, download NASA POWER data, finalise, and install it."
        )

    st.markdown("### Find a location")
    st.caption(
        "Use the search box on the map. Results are preferentially restricted to the selected country; untick the sidebar option to search worldwide."
    )
    if not catalogue.empty:
        centre_lat = float(catalogue["lat"].median())
        centre_lon = float(catalogue["lng"].median())
        country_map = folium.Map(location=[centre_lat, centre_lon], zoom_start=5, tiles=None, control_scale=True)
        folium.TileLayer("OpenStreetMap", name="Roads & places", show=True).add_to(country_map)
        folium.TileLayer(
            tiles="https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}",
            attr="Esri World Imagery",
            name="Satellite imagery",
            show=False,
        ).add_to(country_map)
        folium.TileLayer("CartoDB positron", name="Light map", show=False).add_to(country_map)
        Fullscreen().add_to(country_map)
        MeasureControl(
            primary_length_unit="meters",
            secondary_length_unit="kilometers",
            primary_area_unit="sqmeters",
            secondary_area_unit="hectares",
        ).add_to(country_map)
        folium.LayerControl(collapsed=False).add_to(country_map)
        st_folium(country_map, height=560, use_container_width=True, key="global_country_search_map")
    else:
        st.info("No georeferenced locations are available for this country in worldcities.csv.")

    with st.expander("Country data storage", expanded=False):
        st.code(str(climate_file), language="text")
        st.caption(
            "All countries, including Mexico, are stored under Datasets/countries/<country>/agroclimate_longformat.csv."
        )


