def _release10_context_values() -> dict[str, str]:
    project = None
    try:
        project = _active_project()
    except Exception:
        project = st.session_state.get("active_project")

    field = None
    field_id = st.session_state.get("field_ops_active_field_id")
    if field_id:
        try:
            field = FIELD_OPERATIONS_DB.field(str(field_id))
        except Exception:
            field = None

    trial = None
    trial_id = st.session_state.get("pollination_active_trial_id")
    if trial_id:
        try:
            trial = POLLINATION_DB.get_trial(str(trial_id))
        except Exception:
            trial = None

    project_season = (project or {}).get("season", {}) or {}
    project_location = (project or {}).get("location", {}) or {}
    crop = (
        (field or {}).get("crop")
        or project_season.get("crop")
        or ("Maize" if trial else None)
        or "Not selected"
    )
    season = (
        (trial or {}).get("season_year")
        or (field or {}).get("season_year")
        or (str(project_season.get("planting_date", ""))[:4] if project_season.get("planting_date") else None)
        or "Not selected"
    )
    return {
        "Country": str(selected_country),
        "Project": str((project or {}).get("name") or "Not selected"),
        "Field": str((field or {}).get("name") or project_location.get("name") or "Not selected"),
        "Trial": str((trial or {}).get("name") or "Not selected"),
        "Season": str(season),
        "Crop": str(crop),
    }


def _release10_context_selector() -> None:
    project_library = pd.DataFrame()
    field_library = pd.DataFrame()
    trial_library = pd.DataFrame()
    try:
        project_library = PROJECT_STORE.list_projects()
    except Exception:
        pass
    try:
        field_library = FIELD_OPERATIONS_DB.fields()
    except Exception:
        pass
    try:
        trial_library = POLLINATION_DB.list_trials()
    except Exception:
        pass

    project_labels = {"No active project": None}
    if not project_library.empty:
        for _, row in project_library.iterrows():
            if str(row.get("Status", "")) == "Error":
                continue
            label = f"{row.get('Name', 'Project')} · {str(row.get('Project ID', ''))[:8]}"
            project_labels[label] = str(row.get("Project ID"))

    field_labels = {"No active field": None}
    if not field_library.empty:
        for _, row in field_library.iterrows():
            field_labels[f"{row.get('farm_name', 'Farm')} · {row.get('name', 'Field')}"] = str(row.get("field_id"))

    trial_labels = {"No active trial": None}
    if not trial_library.empty:
        for _, row in trial_library.iterrows():
            trial_labels[f"{row.get('Trial', 'Trial')} · {row.get('Year', '')}"] = str(row.get("Trial ID"))

    current_project = st.session_state.get("active_project_id")
    current_field = st.session_state.get("field_ops_active_field_id")
    current_trial = st.session_state.get("pollination_active_trial_id")

    def current_label(mapping: dict[str, str | None], value: str | None) -> str:
        for label, identifier in mapping.items():
            if identifier == value:
                return label
        return next(iter(mapping))

    selected_project_label = st.selectbox(
        "Project",
        list(project_labels),
        index=list(project_labels).index(current_label(project_labels, current_project)),
        key="release10_context_project",
    )
    selected_field_label = st.selectbox(
        "Field",
        list(field_labels),
        index=list(field_labels).index(current_label(field_labels, current_field)),
        key="release10_context_field",
    )
    selected_trial_label = st.selectbox(
        "Trial",
        list(trial_labels),
        index=list(trial_labels).index(current_label(trial_labels, current_trial)),
        key="release10_context_trial",
    )
    if st.button("Apply context", type="primary", width="stretch", key="release10_apply_context"):
        project_id = project_labels[selected_project_label]
        if project_id:
            _activate_project(project_id)
        else:
            st.session_state.active_project_id = None
            st.session_state.active_project = None
        st.session_state.field_ops_active_field_id = field_labels[selected_field_label]
        st.session_state.pollination_active_trial_id = trial_labels[selected_trial_label]
        st.success("Workspace context updated.")
        st.rerun()


def _release10_context_bar() -> None:
    values = _release10_context_values()
    breadcrumb_parts = [
        values["Country"],
        values["Field"] if values["Field"] != "Not selected" else values["Project"],
        values["Season"],
        values["Crop"],
    ]
    if values["Trial"] != "Not selected":
        breadcrumb_parts.append(values["Trial"])
    breadcrumb = "  ›  ".join(str(value) for value in breadcrumb_parts if value and value != "Not selected")
    columns = st.columns([8, 2])
    columns[0].caption("Active workspace context")
    columns[0].markdown(f"**{breadcrumb or 'No project, field or trial selected'}**")
    with columns[1]:
        if hasattr(st, "popover"):
            with st.popover("Change context", width="stretch"):
                _release10_context_selector()
        else:
            with st.expander("Change context", expanded=False):
                _release10_context_selector()


def _release10_choose_view(label: str, options: list[str], key: str, default: str | None = None) -> str:
    if not options:
        raise ValueError("A workspace must contain at least one view.")
    default_value = default if default in options else options[0]
    if hasattr(st, "segmented_control") and len(options) <= 6:
        try:
            value = st.segmented_control(
                label,
                options,
                default=default_value,
                selection_mode="single",
                key=key,
                width="stretch",
            )
        except TypeError:
            value = st.segmented_control(
                label,
                options,
                default=default_value,
                selection_mode="single",
                key=key,
            )
        return value or default_value
    return st.selectbox(label, options, index=options.index(default_value), key=key)


def _release10_render_embedded(function) -> None:
    previous = st.session_state.get("_release10_embedded_workspace", False)
    st.session_state["_release10_embedded_workspace"] = True
    try:
        reliability_profile_call(st.session_state, f"Embedded · {getattr(function, '__name__', 'tool')}", function)
    except Exception as error:
        st.session_state.release4_last_page_error = {
            "type": type(error).__name__,
            "message": str(error),
            "timestamp": datetime.now(timezone.utc).isoformat(),
        }
        release4_render_friendly_exception(error)
    finally:
        st.session_state["_release10_embedded_workspace"] = previous


