def _release10_open_task_counts() -> tuple[int, int]:
    try:
        tasks = FIELD_OPERATIONS_DB.tasks()
        task_count = int((~tasks.get("status", pd.Series(dtype=str)).astype(str).str.casefold().isin({"completed", "cancelled"})).sum()) if not tasks.empty else 0
    except Exception:
        task_count = 0
    try:
        alerts = FIELD_OPERATIONS_DB.alerts()
        alert_count = int(alerts.get("status", pd.Series(dtype=str)).astype(str).str.casefold().eq("open").sum()) if not alerts.empty else 0
    except Exception:
        alert_count = 0
    return task_count, alert_count


def _release11_7_frame_record(frame: pd.DataFrame | None, index: int = 0) -> dict[str, object] | None:
    if not isinstance(frame, pd.DataFrame) or frame.empty:
        return None
    try:
        return frame.iloc[index].to_dict()
    except Exception:
        return None


def _release11_7_latest_acquisition(acquisitions: pd.DataFrame, keywords: tuple[str, ...]) -> dict[str, object] | None:
    if not isinstance(acquisitions, pd.DataFrame) or acquisitions.empty:
        return None
    search_columns = [column for column in ("source", "source_type") if column in acquisitions]
    if not search_columns:
        return None
    mask = pd.Series(False, index=acquisitions.index)
    for column in search_columns:
        text = acquisitions[column].astype(str).str.casefold()
        for keyword in keywords:
            mask |= text.str.contains(str(keyword).casefold(), regex=False, na=False)
    subset = acquisitions.loc[mask].copy()
    if subset.empty:
        return None
    if "created_at" in subset:
        subset["_sort_time"] = pd.to_datetime(subset["created_at"], errors="coerce", utc=True)
        subset = subset.sort_values("_sort_time", ascending=False)
    return subset.iloc[0].to_dict()


def _release11_7_home_snapshot() -> dict[str, object]:
    """Collect only small persisted summaries for Home.

    No large country CSV reads, satellite searches, NASA calls, model fitting or Twin
    recomputation are performed here.  Expensive work remains explicit behind buttons.
    """
    context = _release10_context_values()
    project = None
    try:
        project = _active_project()
    except Exception:
        project = st.session_state.get("active_project")

    field_id = st.session_state.get("field_ops_active_field_id")
    trial_id = st.session_state.get("pollination_active_trial_id")
    field = None
    trial = None
    if field_id:
        try:
            field = FIELD_OPERATIONS_DB.field(str(field_id))
        except Exception:
            field = None
    if trial_id:
        try:
            trial = POLLINATION_DB.get_trial(str(trial_id))
        except Exception:
            trial = None

    # A mapped trial retains its authoritative source field. Use that linkage for
    # Home evidence summaries even when the researcher selected the trial without
    # separately selecting the field in the context bar. Do not mutate context.
    effective_field_id = field_id or (trial or {}).get("source_field_id")
    if field is None and effective_field_id:
        try:
            field = FIELD_OPERATIONS_DB.field(str(effective_field_id))
        except Exception:
            field = None
    if field and context.get("Field") == "Not selected":
        context = dict(context)
        context["Field"] = str(field.get("name") or "Not selected")
        if context.get("Crop") == "Not selected" and field.get("crop"):
            context["Crop"] = str(field.get("crop"))
        if context.get("Season") == "Not selected" and field.get("season_year"):
            context["Season"] = str(field.get("season_year"))

    scope_field_id = str(effective_field_id) if effective_field_id else None
    try:
        tasks = FIELD_OPERATIONS_DB.tasks(scope_field_id)
    except Exception:
        tasks = pd.DataFrame()
    try:
        alerts = FIELD_OPERATIONS_DB.alerts(scope_field_id)
    except Exception:
        alerts = pd.DataFrame()
    try:
        field_timeline = FIELD_OPERATIONS_DB.field_timeline(scope_field_id) if scope_field_id else pd.DataFrame()
    except Exception:
        field_timeline = pd.DataFrame()

    sensor_latest = None
    active_sensor_count = 0
    if scope_field_id:
        try:
            sensor_status = FIELD_OPERATIONS_DB.frame(
                """SELECT COUNT(DISTINCT CASE WHEN s.status='Active' THEN s.sensor_id END) AS active_sensors,
                          MAX(r.timestamp) AS latest_timestamp
                   FROM sensors s LEFT JOIN sensor_readings r ON r.sensor_id=s.sensor_id
                   WHERE s.field_id=?""",
                (scope_field_id,),
            )
            if not sensor_status.empty:
                active_sensor_value = pd.to_numeric(sensor_status.iloc[0].get("active_sensors"), errors="coerce")
                active_sensor_count = int(active_sensor_value) if pd.notna(active_sensor_value) else 0
                sensor_latest = sensor_status.iloc[0].get("latest_timestamp")
        except Exception:
            pass

    twin_link = None
    twin_state = None
    twin_snapshot = None
    weather_record = None
    satellite_record = None
    root_zone_record = None
    try:
        links = AGROLATTICE_TWIN_DB.links()
        if not links.empty:
            candidates = links.copy()
            exact = pd.DataFrame()
            if effective_field_id and trial_id and {"field_id", "trial_id"}.issubset(candidates.columns):
                exact = candidates.loc[
                    candidates["field_id"].astype(str).eq(str(effective_field_id))
                    & candidates["trial_id"].astype(str).eq(str(trial_id))
                ]
            if exact.empty and trial_id and "trial_id" in candidates:
                exact = candidates.loc[candidates["trial_id"].astype(str).eq(str(trial_id))]
            if exact.empty and effective_field_id and "field_id" in candidates:
                exact = candidates.loc[candidates["field_id"].astype(str).eq(str(effective_field_id))]
            if not exact.empty:
                twin_link = exact.iloc[0].to_dict()
        if twin_link:
            link_id = str(twin_link.get("link_id"))
            session_state = st.session_state.get("agrolattice_twin_state")
            if isinstance(session_state, dict):
                state_field = str(session_state.get("Field") or "")
                state_trial = str(session_state.get("Trial") or "")
                field_match = not field or not state_field or state_field == str(field.get("name") or "")
                trial_match = not trial or not state_trial or state_trial == str(trial.get("name") or "")
                if field_match and trial_match:
                    twin_state = dict(session_state)
            snapshots = AGROLATTICE_TWIN_DB.snapshots(link_id)
            if not snapshots.empty:
                twin_snapshot = snapshots.iloc[-1].to_dict()
                if twin_state is None:
                    try:
                        twin_state = json.loads(str(twin_snapshot.get("state_json") or "{}"))
                    except Exception:
                        twin_state = None
            weather_record = AGROLATTICE_TWIN_DB.weather_record(link_id)
            satellite_record = AGROLATTICE_TWIN_DB.satellite_record(link_id)
            root_zone_record = AGROLATTICE_TWIN_DB.root_zone_record(link_id)
    except Exception:
        twin_link = twin_link or None

    try:
        acquisitions = RESEARCH_EVIDENCE_DB.data_acquisitions(field_id=scope_field_id, limit=80) if scope_field_id else pd.DataFrame()
    except Exception:
        acquisitions = pd.DataFrame()
    try:
        predictions = RESEARCH_EVIDENCE_DB.predictions(field_id=scope_field_id, trial_id=str(trial_id) if trial_id else None, limit=30)
    except Exception:
        predictions = pd.DataFrame()
    try:
        recommendations = RESEARCH_EVIDENCE_DB.recommendations(field_id=scope_field_id, trial_id=str(trial_id) if trial_id else None)
    except Exception:
        recommendations = pd.DataFrame()
    try:
        outcomes = RESEARCH_EVIDENCE_DB.treatment_outcomes(field_id=scope_field_id, trial_id=str(trial_id) if trial_id else None)
    except Exception:
        outcomes = pd.DataFrame()
    try:
        models = RESEARCH_EVIDENCE_DB.models()
    except Exception:
        models = pd.DataFrame()

    latest_prediction = _release11_7_frame_record(predictions)
    latest_model = None
    if latest_prediction and latest_prediction.get("model_id"):
        try:
            latest_model = RESEARCH_EVIDENCE_DB.model(str(latest_prediction.get("model_id")))
        except Exception:
            latest_model = None
    if latest_model is None:
        latest_model = _release11_7_frame_record(models)

    try:
        trial_observations = POLLINATION_DB.observations(str(trial_id)) if trial_id else pd.DataFrame()
    except Exception:
        trial_observations = pd.DataFrame()

    weather_acquisition = _release11_7_latest_acquisition(acquisitions, ("nasa", "power", "weather"))
    satellite_acquisition = _release11_7_latest_acquisition(acquisitions, ("sentinel", "satellite", "earth observation", "eo"))
    weather_latest = (weather_record or {}).get("end_date") or (weather_acquisition or {}).get("period_end") or (weather_acquisition or {}).get("created_at")
    satellite_latest = (satellite_record or {}).get("end_date") or (satellite_acquisition or {}).get("period_end") or (satellite_acquisition or {}).get("created_at")
    root_zone_latest = (root_zone_record or {}).get("end_date") or (root_zone_record or {}).get("updated_at")
    trial_obs_latest = None
    if isinstance(trial_observations, pd.DataFrame) and not trial_observations.empty:
        date_column = next((column for column in ("Date", "Observation date", "observation_date") if column in trial_observations), None)
        if date_column:
            values = pd.to_datetime(trial_observations[date_column], errors="coerce", utc=True).dropna()
            if not values.empty:
                trial_obs_latest = values.max()

    now = pd.Timestamp.now(tz="UTC")
    season_number = pd.to_numeric(pd.Series([context.get("Season")]), errors="coerce").iloc[0]
    trial_status = str((trial or {}).get("status") or "")
    historical_context = bool(
        (pd.notna(season_number) and int(season_number) < int(now.year))
        or trial_status.casefold() in {"completed", "archived"}
    )
    freshness = [
        home_freshness_status("Weather", weather_latest, fresh_days=1, warn_days=3, now=now, source=str((weather_record or {}).get("source") or (weather_acquisition or {}).get("source") or "NASA POWER / persistent field weather")),
        home_freshness_status("Satellite", satellite_latest, fresh_days=7, warn_days=16, now=now, source=str((satellite_record or {}).get("source") or (satellite_acquisition or {}).get("source") or "Sentinel-2 field EO")),
        home_freshness_status("Root zone", root_zone_latest, fresh_days=1, warn_days=3, now=now, source=str((root_zone_record or {}).get("source") or "FAO-56 / Twin root-zone state")),
        home_freshness_status("Sensors", sensor_latest, fresh_days=1, warn_days=3, now=now, source=f"{active_sensor_count} active field sensor(s)" if active_sensor_count else "Field Operations sensor registry", missing_detail="No current sensor reading is stored for the active field."),
    ]
    if trial_id:
        freshness.append(home_freshness_status("Phenology observations", trial_obs_latest, fresh_days=2, warn_days=7, now=now, source="Maize Synchrony Lab repeated observations", missing_detail="No flowering observation has been recorded for the active trial."))
    if historical_context:
        for row in freshness:
            if row.get("status") != "Missing":
                row["status"] = "Historical"
                row["tone"] = "neutral"
                row["detail"] = f"Stored through {row.get('latest')}; assessed as historical-season evidence rather than against today's date."

    recent_activity = home_build_recent_activity(
        field_timeline=field_timeline,
        data_acquisitions=acquisitions,
        predictions=predictions,
        recommendations=recommendations,
        limit=7,
    )
    upcoming = home_build_upcoming_timeline(tasks=tasks, twin_state=twin_state, trial=trial, now=now, days=14, limit=7)
    task_summary = home_open_task_summary(tasks, now=now)
    alert_count = home_open_alert_count(alerts)
    has_context = bool(field_id or trial_id or (project or {}).get("project_id"))
    actions = home_build_priority_actions(
        dataset_ready=bool(DATASET_READY),
        has_context=has_context,
        field_name=str((field or {}).get("name") or context.get("Field") or "") or None,
        tasks=tasks,
        alerts=alerts,
        freshness=freshness,
        trial_status=trial_status,
        trial_observations=trial_observations,
        latest_model=latest_model,
        latest_prediction=latest_prediction,
        recommendations=recommendations,
        treatment_outcomes=outcomes,
        twin_state=twin_state,
        now=now,
        limit=5,
    )
    next_measurement = home_next_best_measurement(
        twin_state=twin_state,
        freshness=freshness,
        trial_active=trial_status.casefold() in {"active", "planned"},
    )
    try:
        projects = PROJECT_STORE.list_projects()
        if not projects.empty:
            projects["_updated"] = pd.to_datetime(projects.get("Updated"), errors="coerce", utc=True)
            projects = projects.sort_values("_updated", ascending=False).drop(columns=["_updated"], errors="ignore")
    except Exception:
        projects = pd.DataFrame()

    return {
        "context": context,
        "project": project,
        "field": field,
        "trial": trial,
        "field_id": effective_field_id,
        "trial_id": trial_id,
        "tasks": tasks,
        "alerts": alerts,
        "task_summary": task_summary,
        "alert_count": alert_count,
        "twin_link": twin_link,
        "twin_state": twin_state,
        "twin_snapshot": twin_snapshot,
        "weather_record": weather_record,
        "satellite_record": satellite_record,
        "root_zone_record": root_zone_record,
        "freshness": freshness,
        "predictions": predictions,
        "recommendations": recommendations,
        "latest_prediction": latest_prediction,
        "latest_model": latest_model,
        "actions": actions,
        "next_measurement": next_measurement,
        "recent_activity": recent_activity,
        "upcoming": upcoming,
        "projects": projects,
        "historical_context": historical_context,
    }


def _release11_7_open_destination(page_key: str, tool_name: str | None = None) -> None:
    """Deep-link Home actions using the current command-centre routing contracts."""
    tool = str(tool_name or "")
    if tool in {"Research Data Hub", "Dataset updater"}:
        _release10_switch("all_tools", tool)
        return
    if tool == "Tasks, scouting & operations":
        queue_view_request(st.session_state, request_key="field_command_section_request", target="Work & scouting")
        _release10_switch("fields")
        return
    if tool == "Crop health, rules & alerts":
        queue_view_request(st.session_state, request_key="field_command_section_request", target="Crop health")
        _release10_switch("fields")
        return
    if tool == "Satellite crop monitoring":
        queue_view_request(st.session_state, request_key="release11_10_climate_command_view_request", target="Earth Observation")
        _release10_switch("climate")
        return
    if tool == "Soil-water balance":
        queue_view_request(st.session_state, request_key="crop_decision_command_view_request", target="Water & irrigation")
        _release10_switch("crop")
        return
    if tool == "Maize flowering trials & field data":
        queue_view_request(st.session_state, request_key="experiment_cc_requested_view", target="Design")
        _release10_switch("experiments")
        return
    if tool == "Validation Centre":
        queue_view_request(st.session_state, request_key="model_evidence_view_request_11_14", target="Validation")
        _release10_switch("evidence")
        return
    if tool == "Research Model & Evidence Registry":
        queue_view_request(st.session_state, request_key="model_evidence_view_request_11_14", target="Evidence & reproducibility")
        _release10_switch("evidence")
        return
    if tool == "Decision Intelligence & Research Optimisation":
        queue_view_request(st.session_state, request_key="crop_decision_command_view_request", target="Recommendations & outcomes")
        _release10_switch("crop")
        return
    _release10_switch(page_key, tool_name if page_key == "all_tools" else None)


def _release11_7_tone_icon(tone: str) -> str:
    return {"good": "✅", "warn": "⚠️", "bad": "🔴", "neutral": "◻️", "info": "ℹ️"}.get(str(tone), "•")


def _release11_7_format_age(timestamp: object) -> str:
    stamp = pd.to_datetime(timestamp, errors="coerce", utc=True)
    if pd.isna(stamp):
        return "No recent activity"
    delta = max(0.0, (pd.Timestamp.now(tz="UTC") - stamp).total_seconds())
    if delta < 3600:
        return f"{max(1, int(delta // 60))} min ago"
    if delta < 86400:
        return f"{int(delta // 3600)} h ago"
    return f"{int(delta // 86400)} d ago"


def page_release10_home() -> None:
    page_header(
        "AGROLATTICE Release 11.19",
        "Research Command Centre",
        "See the active field or experiment, data freshness, Twin/evidence state and the next scientifically useful action without running heavy analyses on page entry.",
    )
    _release10_context_bar()
    _release11_17_workspace_help("Home")
    snapshot = _release11_7_home_snapshot()
    context = snapshot["context"]
    field = snapshot["field"] or {}
    trial = snapshot["trial"] or {}
    twin_state = snapshot["twin_state"] or {}
    latest_prediction = snapshot["latest_prediction"] or {}
    latest_model = snapshot["latest_model"] or {}

    # First-glance status -------------------------------------------------
    crop_season = " · ".join(
        value for value in (str(context.get("Crop") or ""), str(context.get("Season") or ""))
        if value and value != "Not selected"
    ) or "No active crop"
    weather_row = next((row for row in snapshot["freshness"] if row.get("name") == "Weather"), {})
    environment_value = f"Through {weather_row.get('latest')}" if weather_row.get("latest") else "Needs field data"
    open_action_count = int(snapshot["task_summary"].get("open", 0)) + int(snapshot["alert_count"])
    active_recommendations = snapshot["recommendations"]
    if isinstance(active_recommendations, pd.DataFrame) and not active_recommendations.empty and "status" in active_recommendations:
        open_action_count += int((~active_recommendations["status"].astype(str).str.casefold().isin({"rejected", "completed", "superseded", "cancelled"})).sum())
    twin_value = "Not linked"
    if snapshot["twin_link"]:
        as_of = twin_state.get("As of") or (snapshot["twin_snapshot"] or {}).get("as_of")
        twin_value = f"Snapshot {as_of}" if as_of else "Linked"
    elif latest_model:
        twin_value = str(latest_model.get("status") or "Model registered")

    top = st.columns(4)
    top[0].metric("Active crop / season", crop_season, help=str(context.get("Field") or context.get("Project") or "No active field"))
    top[1].metric("Environmental evidence", environment_value, help=str(weather_row.get("status") or "No persistent field weather"))
    top[2].metric("Open actions", open_action_count, help=f"{snapshot['task_summary'].get('open', 0)} field task(s), {snapshot['alert_count']} alert(s), plus active recommendations")
    top[3].metric("Twin / model evidence", twin_value, help="Persistent Twin snapshot when available; otherwise the latest registered research-model status.")

    # Continue current work ---------------------------------------------
    st.markdown("### Continue current work")
    with st.container(border=True):
        left, right = st.columns([5, 2])
        with left:
            title_parts = [
                str(context.get("Field")) if context.get("Field") != "Not selected" else "",
                str(context.get("Trial")) if context.get("Trial") != "Not selected" else "",
            ]
            st.markdown(f"#### {' · '.join(part for part in title_parts if part) or context.get('Project') or 'No active research context'}")
            detail_parts = []
            if context.get("Project") != "Not selected":
                detail_parts.append(f"Project: **{context.get('Project')}**")
            if context.get("Crop") != "Not selected":
                detail_parts.append(f"Crop: **{context.get('Crop')}**")
            if context.get("Season") != "Not selected":
                detail_parts.append(f"Season: **{context.get('Season')}**")
            if snapshot["twin_link"]:
                detail_parts.append(f"Twin: **{snapshot['twin_link'].get('name') or 'Linked'}**")
            st.markdown("  ·  ".join(detail_parts) if detail_parts else "Select a project, field or trial using **Change context** above.")
            recent = snapshot["recent_activity"]
            if isinstance(recent, pd.DataFrame) and not recent.empty:
                st.caption(f"Last recorded activity: {_release11_7_format_age(recent.iloc[0].get('timestamp'))} · {recent.iloc[0].get('type')} · {recent.iloc[0].get('title')}")
            elif snapshot["project"]:
                st.caption(f"Project updated {_release11_7_format_age(snapshot['project'].get('updated_at'))}.")
            else:
                st.caption("Choose an active field/experiment to make Home field- and season-aware.")
        with right:
            if snapshot["twin_link"]:
                if st.button("Resume Twin", type="primary", width="stretch", key="release11_7_resume_twin"):
                    queue_view_request(st.session_state, request_key="twin_cc_view_request", target="Overview")
                    _release10_switch("twin")
            elif snapshot["field_id"]:
                if st.button("Open field", type="primary", width="stretch", key="release11_7_resume_field_primary"):
                    st.session_state.field_ops_active_field_id = str(snapshot["field_id"])
                    queue_view_request(st.session_state, request_key="field_command_section_request", target="Overview")
                    _release10_switch("fields")
            else:
                if st.button("Select / map a field", type="primary", width="stretch", key="release11_7_select_field"):
                    queue_view_request(st.session_state, request_key="field_command_section_request", target="Overview")
                    _release10_switch("fields")
            if snapshot["trial_id"] and st.button("Open experiment", width="stretch", key="release11_7_resume_trial"):
                queue_view_request(st.session_state, request_key="experiment_cc_requested_view", target="Overview")
                _release10_switch("experiments")
            if st.button("View evidence", width="stretch", key="release11_7_resume_evidence"):
                queue_view_request(st.session_state, request_key="model_evidence_view_request_11_14", target="Evidence & reproducibility")
                _release10_switch("evidence")

    # Twin Pulse + dynamic priorities -----------------------------------
    pulse_col, action_col = st.columns([1, 1])
    with pulse_col:
        st.markdown("### Twin Pulse")
        with st.container(border=True):
            if twin_state:
                development_bits = []
                for label, key in (("male", "Male progress (%)"), ("female", "Female progress (%)")):
                    value = pd.to_numeric(pd.Series([twin_state.get(key)]), errors="coerce").iloc[0]
                    if pd.notna(value):
                        development_bits.append(f"{label} {float(value):.0f}%")
                predicted_male = twin_state.get("Predicted male 50% flowering")
                predicted_female = twin_state.get("Predicted female 50% silking")
                st.markdown(f"**Development · Modelled** — {', '.join(development_bits) or 'stage progress unavailable'}")
                if predicted_male or predicted_female:
                    st.caption(f"Male flowering: {predicted_male or '—'} · Female silking: {predicted_female or '—'}")
                rain = pd.to_numeric(pd.Series([twin_state.get("Rain last 7 days (mm)")]), errors="coerce").iloc[0]
                temp = pd.to_numeric(pd.Series([twin_state.get("Mean temperature last 7 days (°C)")]), errors="coerce").iloc[0]
                st.markdown(f"**Environment · Retrieved/derived** — rain {float(rain):.1f} mm / 7 d" if pd.notna(rain) else "**Environment · Retrieved/derived** — recent rainfall unavailable")
                if pd.notna(temp):
                    st.caption(f"Mean temperature last 7 d: {float(temp):.1f} °C")
                ks = pd.to_numeric(pd.Series([twin_state.get("Latest root-zone Ks")]), errors="coerce").iloc[0]
                depletion = pd.to_numeric(pd.Series([twin_state.get("Latest relative depletion")]), errors="coerce").iloc[0]
                if pd.notna(ks) or pd.notna(depletion):
                    water_text = f"Ks {float(ks):.2f}" if pd.notna(ks) else "Ks —"
                    if pd.notna(depletion):
                        water_text += f" · relative depletion {100*float(depletion):.0f}%" if abs(float(depletion)) <= 1.5 else f" · relative depletion {float(depletion):.0f}%"
                    st.markdown(f"**Water · Model state** — {water_text}")
                else:
                    st.markdown("**Water · Model state** — no persistent root-zone state")
                ndvi = pd.to_numeric(pd.Series([twin_state.get("Latest NDVI")]), errors="coerce").iloc[0]
                st.markdown(f"**Earth observation · Retrieved** — latest NDVI {float(ndvi):.3f}" if pd.notna(ndvi) else "**Earth observation · Retrieved** — no usable NDVI in the latest Twin snapshot")
                uncertainty = pd.to_numeric(pd.Series([twin_state.get("Uncertainty (%)")]), errors="coerce").iloc[0]
                quality = pd.to_numeric(pd.Series([twin_state.get("Data quality score")]), errors="coerce").iloc[0]
                evidence_text = []
                if pd.notna(quality):
                    evidence_text.append(f"data quality {float(quality):.0f}/100")
                if pd.notna(uncertainty):
                    evidence_text.append(f"uncertainty {float(uncertainty):.0f}%")
                st.markdown(f"**Evidence · Model diagnostic** — {' · '.join(evidence_text) or 'diagnostics unavailable'}")
            else:
                st.info("No saved Twin state is linked to the active context. Home will not run the Twin automatically because that would slow navigation and blur saved versus newly computed evidence.")
                if snapshot["field_id"] and st.button("Create / configure Twin", width="stretch", key="release11_7_create_twin"):
                    queue_view_request(st.session_state, request_key="twin_cc_view_request", target="Setup")
                    _release10_switch("twin")
            if snapshot["next_measurement"]:
                st.divider()
                st.markdown(f"**Most useful next measurement → {snapshot['next_measurement']['title']}**")
                st.caption(snapshot["next_measurement"]["reason"])

    with action_col:
        st.markdown("### Priority actions")
        actions = snapshot["actions"]
        if actions:
            with st.container(border=True):
                for index, action in enumerate(actions):
                    row = st.columns([5, 1.2])
                    row[0].markdown(f"**{index + 1}. {action['title']}**")
                    row[0].caption(f"{action.get('kind', 'Research')} · {action['detail']}")
                    if row[1].button("Open", width="stretch", key=f"release11_7_action_{index}"):
                        if snapshot["field_id"] and not st.session_state.get("field_ops_active_field_id"):
                            st.session_state.field_ops_active_field_id = str(snapshot["field_id"])
                        _release11_7_open_destination(str(action["page"]), action.get("tool"))
                    if index < len(actions) - 1:
                        st.divider()
        else:
            st.success("No high-priority action was detected from the persisted active-context records. Continue planned measurements and review model assumptions when conditions change.")

    # Data freshness + evidence status ----------------------------------
    freshness_col, evidence_col = st.columns([1.15, 0.85])
    with freshness_col:
        st.markdown("### Data freshness & completeness")
        with st.container(border=True):
            if snapshot["historical_context"]:
                st.caption("Historical context detected: stored datasets are assessed as historical evidence, not penalised merely because they are old relative to today.")
            for index, row in enumerate(snapshot["freshness"]):
                line = st.columns([2.1, 1.2, 2.7])
                line[0].markdown(f"**{_release11_7_tone_icon(row.get('tone'))} {row.get('name')}**")
                line[1].markdown(f"**{row.get('status')}**")
                latest_text = f"through {row.get('latest')}" if row.get("latest") else "not available"
                line[2].caption(f"{latest_text} · {row.get('source') or 'source not recorded'}")
                if index < len(snapshot["freshness"]) - 1:
                    st.divider()
            data_buttons = st.columns(2)
            if data_buttons[0].button("Retrieve / reuse field data", width="stretch", key="release11_7_data_hub"):
                if snapshot["field_id"] and not st.session_state.get("field_ops_active_field_id"):
                    st.session_state.field_ops_active_field_id = str(snapshot["field_id"])
                _release11_7_open_destination("settings", "Research Data Hub")
            if data_buttons[1].button("Open satellite monitoring", width="stretch", key="release11_7_satellite"):
                if snapshot["field_id"] and not st.session_state.get("field_ops_active_field_id"):
                    st.session_state.field_ops_active_field_id = str(snapshot["field_id"])
                _release11_7_open_destination("climate", "Satellite crop monitoring")

    with evidence_col:
        st.markdown("### Model & evidence status")
        with st.container(border=True):
            if latest_model:
                st.markdown(f"**{latest_model.get('name') or 'Registered model'}**")
                st.caption(f"{latest_model.get('family') or 'Model'} · target: {latest_model.get('target') or 'not recorded'}")
                st.markdown(f"Status: **{latest_model.get('status') or 'Not classified'}**")
                uncertainty_method = latest_model.get("uncertainty_method")
                if uncertainty_method:
                    st.caption(f"Uncertainty method: {uncertainty_method}")
            else:
                st.info("No research model is registered for this context yet.")
            if latest_prediction:
                st.divider()
                pred_value = latest_prediction.get("prediction")
                if pred_value is None or pd.isna(pred_value):
                    pred_value = latest_prediction.get("prediction_text") or "Recorded"
                target = latest_prediction.get("target") or "Prediction"
                st.markdown(f"Latest prediction · **{target}: {pred_value}**")
                interval = []
                if pd.notna(pd.to_numeric(pd.Series([latest_prediction.get('lower_bound')]), errors='coerce').iloc[0]):
                    interval.append(str(latest_prediction.get("lower_bound")))
                if pd.notna(pd.to_numeric(pd.Series([latest_prediction.get('upper_bound')]), errors='coerce').iloc[0]):
                    interval.append(str(latest_prediction.get("upper_bound")))
                if interval:
                    st.caption("Registered interval: " + " to ".join(interval))
                st.caption(f"Applicability: {latest_prediction.get('applicability_status') or 'Not assessed'}")
            if st.button("Inspect research evidence", width="stretch", key="release11_7_inspect_evidence"):
                _release11_7_open_destination("evidence", "Research Model & Evidence Registry")

    # Near-term timeline + recent change --------------------------------
    timeline_col, changed_col = st.columns(2)
    with timeline_col:
        st.markdown("### Next 14 days")
        with st.container(border=True):
            upcoming = snapshot["upcoming"]
            if isinstance(upcoming, pd.DataFrame) and not upcoming.empty:
                for index, record in upcoming.iterrows():
                    when = pd.to_datetime(record.get("date"), errors="coerce", utc=True)
                    when_text = when.date().isoformat() if pd.notna(when) else "Date unavailable"
                    st.markdown(f"**{when_text} · {record.get('title')}**")
                    st.caption(f"{record.get('type')} · {record.get('detail') or ''}")
                    if index < len(upcoming) - 1:
                        st.divider()
            else:
                st.caption("No scheduled task or saved Twin flowering event falls within the next 14 days.")

    with changed_col:
        st.markdown("### What changed recently")
        with st.container(border=True):
            activity = snapshot["recent_activity"]
            if isinstance(activity, pd.DataFrame) and not activity.empty:
                for index, record in activity.iterrows():
                    st.markdown(f"**{record.get('type')} · {record.get('title')}**")
                    st.caption(f"{_release11_7_format_age(record.get('timestamp'))} · {record.get('detail') or ''}")
                    if index < len(activity) - 1:
                        st.divider()
            else:
                st.caption("No recent field, data-acquisition, prediction or recommendation records are available for this context.")

    # Recent projects ----------------------------------------------------
    st.markdown("### Recent research projects")
    projects = snapshot["projects"]
    if isinstance(projects, pd.DataFrame) and not projects.empty:
        visible = projects.loc[~projects.get("Status", pd.Series(index=projects.index, dtype=str)).astype(str).eq("Error")].head(3)
        project_columns = st.columns(max(1, len(visible)))
        for position, (_, project_row) in enumerate(visible.iterrows()):
            with project_columns[position]:
                with st.container(border=True):
                    st.markdown(f"**{project_row.get('Name') or 'Project'}**")
                    st.caption(f"{project_row.get('Crop') or 'Crop not set'} · {project_row.get('Location') or 'Location not set'}")
                    st.caption(f"Updated {_release11_7_format_age(project_row.get('Updated'))} · {int(project_row.get('Model runs') or 0)} model run(s)")
                    if st.button("Activate", width="stretch", key=f"release11_7_recent_project_{position}"):
                        try:
                            _activate_project(str(project_row.get("Project ID")))
                            st.success("Project activated.")
                            st.rerun()
                        except Exception as error:
                            st.error(f"Could not activate project: {error}")
    else:
        st.info("No persistent research project exists yet. You can still work directly with mapped fields and trials, or create a project in Data & Settings.")

    with st.expander("Home-page interpretation & performance safeguards", expanded=False):
        st.markdown(
            "- Home reads **small persisted summaries only**. It does not automatically call NASA POWER, search satellite catalogues, run crop models or train ML models.\n"
            "- Labels such as **Retrieved, Derived, Modelled, Forecast** remain distinct; a Twin estimate is not displayed as a measurement.\n"
            "- Historical seasons are not marked stale simply because their observations are old relative to today.\n"
            "- Priority actions are transparent rule-based prompts from stored state, not autonomous agronomic decisions.\n"
            "- System diagnostics and dependency readiness remain under **Data & Settings → System diagnostics** rather than duplicating the legacy command centre here."
        )


