def _release11_10_field_season_window(field: Mapping[str, object]) -> tuple[date, date, str]:
    """Resolve an evidence-backed weather/EO window without inventing crop dates."""
    today = date.today()
    field_id = str(field.get("field_id") or "")
    start = end = None
    basis = None
    try:
        seasons = FIELD_OPERATIONS_DB.seasons(field_id) if field_id else pd.DataFrame()
        if isinstance(seasons, pd.DataFrame) and not seasons.empty:
            target_year = pd.to_numeric(field.get("season_year"), errors="coerce")
            if pd.notna(target_year) and "season_year" in seasons:
                match = seasons.loc[pd.to_numeric(seasons["season_year"], errors="coerce").eq(int(target_year))]
                row = match.iloc[0] if not match.empty else seasons.sort_values("season_year").iloc[-1]
            else:
                row = seasons.sort_values("season_year").iloc[-1]
            sowing = pd.to_datetime(row.get("sowing_date"), errors="coerce")
            harvest = pd.to_datetime(row.get("harvest_date"), errors="coerce")
            if pd.notna(sowing):
                start = max(date(1981, 1, 1), sowing.date())
                end = min(today, harvest.date()) if pd.notna(harvest) else today
                basis = "Recorded structured-season sowing date" + (" and harvest date" if pd.notna(harvest) else "")
    except Exception:
        pass
    if start is None:
        season_year = pd.to_numeric(field.get("season_year"), errors="coerce")
        if pd.notna(season_year) and int(season_year) <= today.year:
            year = int(season_year)
            start = date(max(1981, year), 1, 1)
            end = min(today, date(year, 12, 31))
            basis = "Season-year calendar window because no sowing date was recorded"
        else:
            start = max(date(1981, 1, 1), (pd.Timestamp(today) - pd.Timedelta(days=365)).date())
            end = today
            basis = "Rolling 12 months because no usable season/sowing date was recorded"
    if end < start:
        end = today
    return start, end, str(basis)


def _release11_10_quick_update_field_weather(field: Mapping[str, object]) -> dict[str, object] | None:
    """Retrieve the established 19-variable NASA-derived field weather profile."""
    field_id = str(field.get("field_id") or "")
    lat = pd.to_numeric(field.get("centroid_lat"), errors="coerce")
    lon = pd.to_numeric(field.get("centroid_lon"), errors="coerce")
    if pd.isna(lat) or pd.isna(lon):
        raise ValueError("The active field has no valid centroid coordinates.")
    start, end, basis = _release11_10_field_season_window(field)
    with st.status("Updating NASA POWER field weather…", expanded=True) as status:
        st.write(f"Retrieving the AGROLATTICE canonical weather profile for {start} to {end} from the mapped field centroid.")
        acquired = fetch_canonical_nasa_weather(
            latitude=float(lat),
            longitude=float(lon),
            start_date=start,
            end_date=end,
            cache_dir=daily_weather_cache_dir,
            force_refresh=False,
            time_standard="LST",
        )
        frame = acquired.frame
        metadata = dict(acquired.metadata or {})
        if frame.empty:
            status.update(label="NASA POWER returned no usable field weather", state="error", expanded=True)
            raise ValueError("NASA POWER returned no usable weather rows for the selected field window.")
        st.session_state.daily_weather_raw = frame.copy()
        st.session_state.daily_weather_metadata = metadata
        st.session_state.daily_weather_request = {
            "field_id": field_id, "latitude": float(lat), "longitude": float(lon),
            "start_date": str(start), "end_date": str(end), "window_basis": basis,
            "time_standard": "LST", "canonical_variables": list(RESEARCH_HUB_CANONICAL_WEATHER_VARIABLES),
        }
        try:
            RESEARCH_EVIDENCE_DB.save_data_acquisition({
                "source": "NASA POWER Daily Point API",
                "source_type": "Mapped-field canonical weather update",
                "field_id": field_id or None,
                "latitude": float(lat), "longitude": float(lon),
                "period_start": str(start), "period_end": str(end),
                "temporal_resolution": "Daily",
                "variables": list(RESEARCH_HUB_CANONICAL_WEATHER_VARIABLES),
                "request": st.session_state.daily_weather_request,
                "provenance": {
                    "window_basis": basis,
                    "canonical_profile": "AGROLATTICE 19-variable weather profile",
                    "metadata": metadata,
                },
                "row_count": int(len(frame)),
                "status": "Completed",
            })
        except Exception as evidence_error:
            st.warning(f"Weather retrieval succeeded, but Research Evidence provenance could not be saved: {evidence_error}")

        twin_saved = False
        try:
            links = AGROLATTICE_TWIN_DB.links()
            if isinstance(links, pd.DataFrame) and not links.empty and "field_id" in links:
                hit = links.loc[links["field_id"].astype(str).eq(field_id)]
                if not hit.empty:
                    result = AGROLATTICE_TWIN_DB.save_weather(
                        str(hit.iloc[0]["link_id"]),
                        frame,
                        latitude=float(lat), longitude=float(lon),
                        parameters=list(RESEARCH_HUB_POWER_PARAMETERS),
                        time_standard="LST",
                        metadata=metadata,
                        request=st.session_state.daily_weather_request,
                        source="NASA POWER Daily Point API via AGROLATTICE 11.10",
                        merge=True,
                    )
                    twin_saved = True
        except Exception as twin_error:
            st.warning(f"Weather retrieval succeeded, but it was not merged into the linked Twin: {twin_error}")
        status.update(label=f"Field weather updated · {len(frame):,} daily row(s)", state="complete", expanded=False)
    dates = pd.to_datetime(frame.get("DATE"), errors="coerce") if "DATE" in frame else pd.Series(dtype="datetime64[ns]")
    return {
        "rows": int(len(frame)),
        "start_date": str(dates.min().date()) if not dates.empty and dates.notna().any() else str(start),
        "end_date": str(dates.max().date()) if not dates.empty and dates.notna().any() else str(end),
        "twin_saved": twin_saved,
        "window_basis": basis,
    }


def _release11_10_quick_update_field_eo(field: Mapping[str, object]) -> dict[str, object] | None:
    """One-click Sentinel-2 update for an authoritative mapped field.

    Uses conservative defaults, keeps the full advanced workflow available below, and
    persists provenance to Research Evidence. If a Persistent Twin is already linked to
    the same field geometry, the approved update is also merged into its satellite
    attachment. Nothing runs unless the researcher explicitly presses Quick update EO.
    """
    geometry = field.get("geometry") if isinstance(field, Mapping) else None
    if not geometry:
        raise ValueError("The active field has no authoritative geometry.")
    geometry = validate_aoi_geometry(geometry)
    today = date.today()
    field_id = str(field.get("field_id") or "")

    # Prefer an observed structured sowing date. If none exists, use a clearly
    # documented calendar/rolling fallback rather than inventing a crop date.
    start = None
    start_basis = None
    try:
        seasons = FIELD_OPERATIONS_DB.seasons(field_id) if field_id else pd.DataFrame()
        if isinstance(seasons, pd.DataFrame) and not seasons.empty:
            target_year = pd.to_numeric(field.get("season_year"), errors="coerce")
            if pd.notna(target_year) and "season_year" in seasons:
                match = seasons.loc[pd.to_numeric(seasons["season_year"], errors="coerce").eq(int(target_year))]
                row = match.iloc[0] if not match.empty else seasons.sort_values("season_year").iloc[-1]
            else:
                row = seasons.sort_values("season_year").iloc[-1]
            sowing = pd.to_datetime(row.get("sowing_date"), errors="coerce")
            if pd.notna(sowing):
                start = max(date(2017, 1, 1), sowing.date())
                start_basis = "Recorded structured-season sowing date"
    except Exception:
        pass
    if start is None:
        season_year = pd.to_numeric(field.get("season_year"), errors="coerce")
        if pd.notna(season_year) and int(season_year) <= today.year:
            start = max(date(2017, 1, 1), date(int(season_year), 1, 1))
            start_basis = "Season-year calendar start because no sowing date was recorded"
        else:
            start = max(date(2017, 1, 1), (pd.Timestamp(today) - pd.Timedelta(days=365)).date())
            start_basis = "Rolling 12 months because no usable season/sowing date was recorded"
    if start > today:
        raise ValueError("The selected field season starts in the future; Sentinel-2 update is not yet applicable.")

    indices = ["NDVI", "EVI", "NDMI", "NDRE"]
    config = SatelliteSearchConfig(
        start_date=str(start),
        end_date=str(today),
        maximum_scene_cloud_percent=60.0,
        maximum_items=240,
        provider_preference="Automatic failover",
    )
    with st.status("Updating field Earth Observation…", expanded=True) as status:
        st.write(f"Searching Sentinel-2 Level-2A from {start} to {today}.")
        items = search_sentinel2_scenes(geometry, config)
        if not items:
            status.update(label="No Sentinel-2 scenes matched the quick-update criteria", state="error", expanded=True)
            raise SatelliteMonitoringError("No Sentinel-2 scenes matched the field and search period.")
        st.write(f"Found {len(items):,} catalogue acquisition(s); selecting the lowest-cloud scene per month.")
        selected_items = select_scene_subset(items, "Lowest-cloud scene per month", 24)
        progress = st.progress(0.0)
        progress_text = st.empty()
        def _progress(i: int, total: int, scene_id: str) -> None:
            progress.progress(min(1.0, i / max(total, 1)))
            progress_text.caption(f"Processing {i}/{total}: {scene_id}")
        frame = process_scene_collection(
            selected_items,
            geometry,
            indices,
            satellite_cache_dir,
            resolution_m=20.0,
            minimum_usable_pixel_percent=30.0,
            excluded_scl_classes=set(DEFAULT_EXCLUDED_SCL),
            maximum_pixels=2_000_000,
            force_refresh=False,
            progress_callback=_progress,
        )
        progress.progress(1.0)
        catalog = scene_catalog_table(selected_items)
        usable = frame.loc[frame.get("Status", pd.Series(index=frame.index, dtype=str)).astype(str).str.casefold().eq("usable")].copy() if not frame.empty else pd.DataFrame()
        if usable.empty:
            status.update(label="Sentinel-2 scenes were found but none passed field-level QA", state="error", expanded=True)
            raise SatelliteMonitoringError("No processed scene met the 30% clear-field-pixel threshold.")

        provider_values = sorted({scene_provider(item) for item in selected_items if scene_provider(item) != "Unknown"})
        request = {
            "Start date": str(start),
            "End date": str(today),
            "Start basis": start_basis,
            "Maximum scene cloud (%)": 60.0,
            "Scene selection": "Lowest-cloud scene per month",
            "Maximum processed scenes": 24,
            "Resolution (m)": 20.0,
            "Minimum clear field pixels (%)": 30.0,
            "Indices": indices,
            "Provider preference": "Automatic failover",
            "Providers used": provider_values,
        }
        st.session_state.satellite_scene_items = selected_items
        st.session_state.satellite_scene_catalog = catalog
        st.session_state.satellite_search_config = request
        st.session_state.satellite_processing_config = request
        st.session_state.satellite_time_series = frame
        st.session_state.satellite_aoi_geometry = geometry
        st.session_state.satellite_aoi_metadata = {
            "Area source": "Mapped AGROLATTICE field",
            "Field ID": field_id,
            "Location": field.get("name"),
            "Farm / research centre": field.get("farm_name"),
            "Area (ha)": field.get("area_ha"),
            "Centroid latitude": field.get("centroid_lat"),
            "Centroid longitude": field.get("centroid_lon"),
        }

        start_obs = pd.to_datetime(usable["Date"], errors="coerce").min()
        end_obs = pd.to_datetime(usable["Date"], errors="coerce").max()
        try:
            RESEARCH_EVIDENCE_DB.save_data_acquisition({
                "source": "Sentinel-2 Level-2A public STAC catalogues",
                "source_type": "Earth observation quick update",
                "field_id": field_id or None,
                "latitude": field.get("centroid_lat"),
                "longitude": field.get("centroid_lon"),
                "period_start": str(start_obs.date()) if pd.notna(start_obs) else str(start),
                "period_end": str(end_obs.date()) if pd.notna(end_obs) else str(today),
                "temporal_resolution": "Irregular clear-sky acquisitions",
                "variables": indices,
                "request": request,
                "provenance": {
                    "field_geometry_authoritative": True,
                    "field_area_ha": field.get("area_ha"),
                    "cloud_mask": "Sentinel-2 SCL exclusions",
                    "module": "Climate & Earth Observation 11.10 quick update",
                },
                "row_count": int(len(frame)),
                "status": "Completed",
            })
        except Exception as evidence_error:
            st.warning(f"EO processing succeeded, but Research Evidence provenance could not be saved: {evidence_error}")

        twin_saved = False
        try:
            links = AGROLATTICE_TWIN_DB.links()
            if isinstance(links, pd.DataFrame) and not links.empty and "field_id" in links:
                hit = links.loc[links["field_id"].astype(str).eq(field_id)]
                if not hit.empty:
                    link_id = str(hit.iloc[0]["link_id"])
                    AGROLATTICE_TWIN_DB.save_satellite(
                        link_id,
                        frame,
                        geometry=geometry,
                        indices=indices,
                        catalog=catalog,
                        metadata={"generated_utc": datetime.now(timezone.utc).isoformat(), "quick_update": True},
                        request=request,
                        source="Sentinel-2 Level-2A public STAC catalogues via AGROLATTICE 11.10",
                        merge=True,
                    )
                    twin_saved = True
        except Exception as twin_error:
            st.warning(f"EO processing succeeded, but it was not merged into the linked Twin: {twin_error}")

        status.update(label=f"Earth Observation updated · {len(usable)} usable scene(s)", state="complete", expanded=False)
    return {
        "rows": int(len(frame)),
        "usable_rows": int(len(usable)),
        "start_date": str(start_obs.date()) if pd.notna(start_obs) else str(start),
        "end_date": str(end_obs.date()) if pd.notna(end_obs) else str(today),
        "twin_saved": twin_saved,
        "start_basis": start_basis,
    }


