def _release_artifact_version_key(path: Path) -> tuple[int, ...]:
    """Sort release artifacts numerically (11.10 after 11.9), not lexicographically."""
    match = re.search(r"RELEASE[_-]?(\d+)[_.-](\d+)", path.name, flags=re.IGNORECASE)
    if match:
        return (int(match.group(1)), int(match.group(2)))
    match = re.search(r"_(\d+)_(\d+)", path.stem)
    if match:
        return (int(match.group(1)), int(match.group(2)))
    return (0, 0)


def page_release10_release_notes() -> None:
    st.markdown("### Release notes")
    release_files = sorted(data_dir.glob("CHANGELOG_RELEASE_*.txt"), key=_release_artifact_version_key, reverse=True)
    manifest_files = sorted(data_dir.glob("RELEASE_MANIFEST_*.json"), key=_release_artifact_version_key, reverse=True)
    current_readme = None
    if manifest_files:
        try:
            manifest = json.loads(manifest_files[0].read_text(encoding="utf-8"))
            readme_name = str(manifest.get("readme") or "").strip()
            if readme_name:
                candidate = data_dir / readme_name
                if candidate.exists():
                    current_readme = candidate
        except Exception:
            current_readme = None
    if current_readme is None:
        candidates = sorted(data_dir.glob("README_START_HERE_RELEASE*.txt"), key=_release_artifact_version_key, reverse=True)
        current_readme = candidates[0] if candidates else None
    if current_readme and current_readme.exists():
        st.text(current_readme.read_text(encoding="utf-8"))
    else:
        st.info("No release README was found in this installation.")
    with st.expander("Earlier release changelogs", expanded=False):
        for path in release_files[:12]:
            st.markdown(f"**{path.name}**")
            try:
                st.text(path.read_text(encoding="utf-8")[:4000])
            except Exception:
                st.caption("Could not read this changelog.")


