def page_publication_reference() -> None:
    st.markdown("### Publication Reference Release")
    st.caption("Frozen software/reference object for the AGROLATTICE platform manuscript. This page performs no remote retrieval or model execution.")
    st.code(PUBLICATION_REFERENCE_ID, language=None)
    summary = publication_reference_demo_summary()
    cols = st.columns(4)
    cols[0].metric("Release", "11.19")
    cols[1].metric("Demo EUs", int(summary.get("experimental_units", 0)))
    cols[2].metric("Weather variables", int(summary.get("weather_variables", 0)))
    cols[3].metric("Scientific DB migrations", "None")
    st.info("The bundled example project is deterministic and synthetic. Its values demonstrate reproducibility plumbing only and are not field measurements, NASA/Sentinel retrievals or agronomic validation evidence.")

    root = data_dir / "publication_reference"
    figure = root / "figures" / "figure_01_platform_architecture.png"
    if figure.exists():
        st.image(str(figure), caption="Figure 1 · AGROLATTICE 11.19 publication-reference architecture", use_container_width=True)
    workflow = root / "figures" / "figure_02_evidence_workflow.png"
    if workflow.exists():
        st.image(str(workflow), caption="Figure 2 · Persistent research workflow and evidence chain", use_container_width=True)

    download_cols = st.columns(3)
    citation = data_dir / "CITATION.cff"
    if citation.exists():
        download_cols[0].download_button("Download CITATION.cff", citation.read_bytes(), file_name="CITATION.cff", mime="text/plain", width="stretch")
    workflow_doc = data_dir / "PUBLICATION_REFERENCE_WORKFLOW.md"
    if workflow_doc.exists():
        download_cols[1].download_button("Download reproducibility workflow", workflow_doc.read_bytes(), file_name=workflow_doc.name, mime="text/markdown", width="stretch")
    demo_dir = root / "demo_project"
    if demo_dir.exists():
        buffer = io.BytesIO()
        with zipfile.ZipFile(buffer, "w", compression=zipfile.ZIP_DEFLATED) as archive:
            for path in sorted(demo_dir.rglob("*")):
                if path.is_file():
                    archive.write(path, path.relative_to(root))
        download_cols[2].download_button("Download synthetic demo bundle", buffer.getvalue(), file_name="AGROLATTICE_11_19_synthetic_demo.zip", mime="application/zip", width="stretch")

    with st.expander("Archive, citation and environment files", expanded=False):
        st.markdown("""- `PUBLICATION_REFERENCE_ID.txt` — stable internal reference identifier.
- `CITATION.cff`, `.zenodo.json`, `codemeta.json` — archive/citation metadata.
- `requirements_publication_reference_lock.txt` — exact release reference pins.
- `FREEZE_PUBLICATION_ENV.bat` — records the exact Windows/Anaconda environment actually used for manuscript analyses.
- `SOURCE_FILE_MANIFEST_11_19.sha256` — source/archive file integrity manifest.
- `LICENSE` and `THIRD_PARTY_NOTICE.md` — software and third-party licensing boundaries.
- `build_public_archive.py` + schema-only SQL exports — publication-safe source archive without user databases or installed datasets.""")
        st.warning("11.19 does not contain a DOI because a DOI must be minted by an external archive. Deposit the exact final ZIP/checksum, then record the returned DOI in the manuscript/public repository metadata without rewriting the frozen scientific release.")


