def _release10_tool_matches(query: str, category: str = "All") -> list[str]:
    query_text = str(query or "").strip().casefold()
    matches = []
    for name in page_functions:
        tool_category = RELEASE10_TOOL_CATEGORY.get(name, "Other")
        if category != "All" and tool_category != category:
            continue
        haystack = " ".join([name, tool_category, RELEASE10_TOOL_DESCRIPTIONS.get(name, "")]).casefold()
        if not query_text or all(token in haystack for token in query_text.split()):
            matches.append(name)
    return sorted(matches, key=lambda item: (RELEASE10_TOOL_CATEGORY.get(item, "Other"), item))


